	private static Skill[] boostableSkills()
	{
		List<Skill> skills = new ArrayList<>();
		for (Skill skill : Skill.values())
		{
			if (skill != Skill.HITPOINTS && skill != Skill.PRAYER)
			{
				skills.add(skill);
			}
		}
		return skills.toArray(new Skill[0]);
	}

