	/** Settings saved while the plugin was called Pickup Profit, and ones that no longer exist. */
	private static final String[] LEGACY_SETTINGS = {
		"trackCombat", "trackFarming", "trackAmmo", "skillLayout", "collapseNew"
	};
	/** Skills are always tracked now; "Hide skilling" only hides them. */
	private static final String[] RETIRED_SETTINGS = {"trackPurchases", "attributionWindow", "lootValue", "trackSkilling"};

	private void migrateLegacySettings()
	{
		for (String key : LEGACY_SETTINGS)
		{
			String value = configManager.getConfiguration(GildedLedgerConfig.LEGACY_GROUP, key);
			if (value != null)
			{
				if (configManager.getConfiguration(GildedLedgerConfig.GROUP, key) == null)
				{
					configManager.setConfiguration(GildedLedgerConfig.GROUP, key, value);
				}
				configManager.unsetConfiguration(GildedLedgerConfig.LEGACY_GROUP, key);
			}
		}
		for (String key : RETIRED_SETTINGS)
		{
			configManager.unsetConfiguration(GildedLedgerConfig.LEGACY_GROUP, key);
		}
	}

	@Override
	protected void startUp()
	{
		migrateLegacySettings();
		ledger = new Ledger(System::currentTimeMillis);
		itemInfo = new ClientItemInfo();
		groundDrops = new GroundDropLedger();
		supplies = new SupplyTracker(itemInfo, this::bookSupply);
		recentSupplies = new RecentSupplies(ledger);
		sessions = new SessionTracker(ledger, lootPrices::value, System::currentTimeMillis);

		Map<String, Integer> compostIds = new HashMap<>();
		compostIds.put("Compost", ItemID.BUCKET_COMPOST);
		compostIds.put("Supercompost", ItemID.BUCKET_SUPERCOMPOST);
		compostIds.put("Ultracompost", ItemID.BUCKET_ULTRACOMPOST);
		farming = new FarmingTracker(ledger, itemInfo, compostIds);

		skilling = new SkillingTracker(ledger, itemInfo);
		// A boost drunk or eaten just before a skilling action (a dragonfruit pie before
		// fletching) is that action's supply, if the action's skill is still boosted.
		skilling.setActionListener((key, name, category) ->
		{
			Skill skill = skillFor(category);
			if (skill != null && client.getBoostedSkillLevel(skill) > client.getRealSkillLevel(skill))
			{
				recentSupplies.moveGeneralTo(key, name, category, false,
					client.getTickCount() - RecentSupplies.PRE_FIGHT_TICKS);
			}
		});
		drops = new DropTracker();

		buildPanel();

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invoke(this::onLogin);
		}
	}

	/** Builds the side panel (again, when the font setting changes) and its toolbar button. */
	private void buildPanel()
	{
		Fonts.use(config.panelFont().getFamily());
		boolean wasOpen = panel != null && panel.isShowing();
		NavigationButton old = navButton;
		panel = new GildedLedgerPanel(itemManager, skillIconManager, this::onPanelAction);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Gilded Ledger")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		if (old != null)
		{
			clientToolbar.removeNavigation(old);
		}
		clientToolbar.addNavigation(navButton);
		if (wasOpen)
		{
			clientToolbar.openPanel(navButton);
		}
	}

	@Override
	protected void shutDown()
	{
		// A session running when the plugin or client stops is paused, time counted up to now.
		if (profileLoaded)
		{
			sessions.pause();
		}
		save();
		clientThread.invoke(popup::close);
		clientToolbar.removeNavigation(navButton);
		resetTransientState();
		profileLoaded = false;
		panel = null;
		navButton = null;
	}

	// ---------------------------------------------------------------- lifecycle

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		GameState previous = lastGameState;
		lastGameState = state;
		if (state == GameState.LOGGED_IN)
		{
			// LOADING -> LOGGED_IN is just a region change; keep baselines so no XP or items are missed.
			if (previous != GameState.LOADING || !profileLoaded)
			{
				onLogin();
			}
		}
		else if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			save();
			resetTransientState();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		save();
		profileLoaded = false;
		loadProfile();
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		if (profileLoaded)
		{
			sessions.pause();
		}
		save();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (GildedLedgerConfig.GROUP.equals(event.getGroup()) && "panelFont".equals(event.getKey()))
		{
			SwingUtilities.invokeLater(() ->
			{
				buildPanel();
				clientThread.invoke(() -> refreshPanel(true));
			});
			return;
		}
		if (GildedLedgerConfig.GROUP.equals(event.getGroup()) && !DATA_KEY.equals(event.getKey()))
		{
			clientThread.invoke(() -> refreshPanel(true));
		}
	}

	/** Categories hidden from the panel (still tracked): every skill, or the ones picked. */
	private Set<SourceCategory> hiddenCategories()
	{
		Set<SourceCategory> hidden = EnumSet.noneOf(SourceCategory.class);
		for (SourceCategory category : SourceCategory.values())
		{
			if (!category.isSkill() && category != SourceCategory.OTHER)
			{
				continue;
			}
			boolean hideThis = Boolean.parseBoolean(
				configManager.getConfiguration(GildedLedgerConfig.GROUP, "hide" + category.getLabel().replace(" ", "")));
			if (config.hideSkilling() && category.isSkill() || hideThis)
			{
				hidden.add(category);
			}
		}
		return hidden;
	}

	private void onLogin()
	{
		loginTick = client.getTickCount();
		slayerBlankCount = 0;
		if (!profileLoaded)
		{
			loadProfile();
		}
		lastCarried = null;
		lastSeedBox = null;
		clearTickChanges();
		lastXp.clear();
		cannonballs = -1;
		syncEquipmentBaseline();
		syncPouchBaseline();
		refreshPanel(true);
	}

	private void loadProfile()
	{
		String json = configManager.getRSProfileConfiguration(GildedLedgerConfig.GROUP, DATA_KEY);
		if (json == null)
		{
			// Saved while the plugin was called Pickup Profit: move it to the new group.
			String legacy = configManager.getRSProfileConfiguration(GildedLedgerConfig.LEGACY_GROUP, DATA_KEY);
			if (legacy != null && configManager.getRSProfileKey() != null)
			{
				json = legacy;
				configManager.setRSProfileConfiguration(GildedLedgerConfig.GROUP, DATA_KEY, legacy);
				configManager.unsetRSProfileConfiguration(GildedLedgerConfig.LEGACY_GROUP, DATA_KEY);
			}
		}
		TrackerData data = null;
		if (json != null && !json.isEmpty())
		{
			try
			{
				data = gson.fromJson(json, TrackerData.class);
			}
			catch (JsonParseException e)
			{
				log.warn("Gilded Ledger: saved data could not be read, starting fresh", e);
			}
		}
		ledger.load(data);
		farming.tidyUnknownCrops();
		skilling.tidyGroups();
		LegacyTidy.tidy(ledger, itemInfo);
		sessions.pauseAfterRestart();
		profileLoaded = configManager.getRSProfileKey() != null;
		taskTargetNames.clear();
		refreshPanel(true);
	}

	private void save()
	{
		if (ledger == null || !profileLoaded || !ledger.isDirty())
		{
			return;
		}
		configManager.setRSProfileConfiguration(GildedLedgerConfig.GROUP, DATA_KEY, gson.toJson(ledger.data()));
		ledger.markSaved();
	}

	private void resetTransientState()
	{
		groundDrops.clear();
		supplies.reset();
		recentSupplies.reset();
		reminders.reset();
		rewards.reset();
		farming.reset();
		skilling.reset();
		drops.reset();
		lastCarried = null;
		lastSeedBox = null;
		clearTickChanges();
		lastXp.clear();
		combatKey = null;
		combatName = null;
		combatIsTask = false;
	}

	private boolean tracking()
	{
		return profileLoaded && client.getGameState() == GameState.LOGGED_IN;
	}

	// ---------------------------------------------------------------- PvM loot

	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		if (tracking() && config.trackCombat())
		{
			groundDrops.recordSpawn(tileKey(event.getTile()), event.getItem().getId(),
				event.getItem().getQuantity(), client.getTickCount());
		}
	}

	@Subscribe
	public void onItemQuantityChanged(ItemQuantityChanged event)
	{
		if (!tracking() || !config.trackCombat())
		{
			return;
		}
		int change = event.getNewQuantity() - event.getOldQuantity();
		if (change > 0)
		{
			groundDrops.recordSpawn(tileKey(event.getTile()), event.getItem().getId(), change, client.getTickCount());
		}
		else if (change < 0)
		{
			onFloorItemRemoved(event.getTile(), event.getItem().getId(), -change);
		}
	}

	@Subscribe
	public void onItemDespawned(ItemDespawned event)
	{
		if (tracking() && config.trackCombat())
		{
			onFloorItemRemoved(event.getTile(), event.getItem().getId(), event.getItem().getQuantity());
		}
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		if (!tracking() || !config.trackCombat())
		{
			return;
		}
		NPC npc = event.getNpc();
		String name = npcName(npc);
		if (name == null)
		{
			return;
		}
		boolean task = isTaskTarget(name);
		List<int[]> stacks = new ArrayList<>();
		for (ItemStack stack : event.getItems())
		{
			stacks.add(new int[]{stack.getId(), stack.getQuantity()});
		}
		WorldArea area = npc.getWorldArea();
		TileKey southWest = area != null
			? new TileKey(area.getX(), area.getY(), area.getPlane())
			: tileKey(npc.getWorldLocation());
		int size = area != null ? area.getWidth() : 1;
		groundDrops.tagNpcLoot(npcKey(name), task, southWest, size, stacks, client.getTickCount());

		ledger.incrementCount(npcKey(name), name, SourceCategory.COMBAT);
		// A potion before the fight, or charges spent before it registered as one: this kill's.
		// Boss fights (a boss, or any kill inside an instance) can be long, so for those
		// everything since entering the instance counts, up to 15 minutes before the kill.
		int tickNow = client.getTickCount();
		int since = fightStartTick - RecentSupplies.PRE_FIGHT_TICKS;
		if (ItemRules.isBoss(name) || client.isInInstancedRegion())
		{
			int arrived = client.isInInstancedRegion() ? instanceEnteredTick : fightStartTick;
			since = Math.max(Math.min(since, arrived - RecentSupplies.PRE_FIGHT_TICKS),
				tickNow - RecentSupplies.BOSS_TICKS);
		}
		recentSupplies.moveGeneralToKill(npcKey(name), name, task, since);
		if (task && ledger.data().currentTask != null && !ledger.data().currentTask.isFinished())
		{
			ledger.data().currentTask.kills++;
			ledger.changed();
		}
	}

	private void onFloorItemRemoved(Tile tile, int itemId, int quantity)
	{
		Player local = client.getLocalPlayer();
		TileKey playerTile = local == null ? null : tileKey(local.getWorldLocation());
		List<GroundDropLedger.Pickup> pickups = groundDrops.recordRemoval(
			tileKey(tile), itemId, quantity, client.getTickCount(), playerTile);
		for (GroundDropLedger.Pickup pickup : pickups)
		{
			// Either a monster's drop, or something the player dropped and is picking back up.
			SourceRecord record = ledger.data().sources.get(pickup.sourceKey);
			if (record == null && !pickup.sourceKey.startsWith("npc:"))
			{
				continue;
			}
			String name = record != null ? record.name : pickup.sourceKey.substring("npc:".length());
			SourceCategory category = record != null ? record.category : SourceCategory.COMBAT;
			ledger.addLoot(pickup.sourceKey, name, category, pickup.itemId, pickup.quantity);
			TaskRecord task = ledger.data().currentTask;
			if (pickup.taskTarget && task != null && !task.isFinished())
			{
				task.lootGp += lootPrice(pickup.itemId) * pickup.quantity;
				ledger.changed();
			}
		}
	}

	// ---------------------------------------------------------------- clicks

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!tracking())
		{
			return;
		}
		int tick = client.getTickCount();
		String option = Text.removeTags(event.getMenuOption());
		String optionLower = option == null ? "" : option.toLowerCase(Locale.ENGLISH);
		MenuAction action = event.getMenuAction();

		String target = Text.removeTags(event.getMenuTarget());

		// Minigame reward pulls: the Rewards Guardian, the Tempoross reward pool, a supply crate...
		MinigameRewards.Minigame reward = event.isItemOp() && event.getItemId() > 0
			? MinigameRewards.forItem(itemInfo.name(event.getItemId()), option)
			: MinigameRewards.forTarget(target, option);
		if (reward != null)
		{
			rewards.onRewardClicked(reward, tick);
			skilling.onOtherAction();
			farming.onOtherAction();
			return;
		}
		if (!event.isItemOp() && action != MenuAction.WALK && action != MenuAction.CC_OP
			&& action != MenuAction.CC_OP_LOW_PRIORITY && action != MenuAction.WIDGET_CONTINUE)
		{
			// Clicking another object or NPC ends a reward pull; dropping junk or walking doesn't.
			rewards.onOtherClick();
		}

		boolean spellbookOp = action == MenuAction.CC_OP || action == MenuAction.CC_OP_LOW_PRIORITY;
		if (spellbookOp && !event.isItemOp() && SkillRules.isTeleportSpell(option, target))
		{
			// Teleport runes go to Teleports, and teleporting ends whatever you were doing.
			supplies.onTeleportCast(SkillRules.teleportSpellName(option, target), tick);
			lastTeleportCastTick = tick;
			stopActivities();
		}
		else if (optionLower.startsWith("cast") || isSpellbookWidget(spellbookOp, event))
		{
			supplies.onCastClicked(tick);
			// A spell cast straight from the spellbook (Superglass Make, Humidify...). Combat
			// spells need a target, so they never come through here.
			if (spellbookOp && !event.isItemOp())
			{
				startProcessing(tick, spellName(target));
			}
		}

		// An inventory item's own option (Eat, Drop, Clean...). Using an item ON something
		// (compost or a seed on a patch) is handled below with the thing it was used on.
		if (event.isItemOp() && event.getItemId() > 0 && !isUseOnSomething(action))
		{
			onInventoryItemClicked(event.getItemId(), option, tick);
			return;
		}

		switch (action)
		{
			case GROUND_ITEM_FIRST_OPTION:
			case GROUND_ITEM_SECOND_OPTION:
			case GROUND_ITEM_THIRD_OPTION:
			case GROUND_ITEM_FOURTH_OPTION:
			case GROUND_ITEM_FIFTH_OPTION:
				if ("take".equals(optionLower))
				{
					groundDrops.recordTake(sceneTile(event.getParam0(), event.getParam1()), event.getId(), tick);
				}
				stopActivities();
				break;
			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
			case WIDGET_TARGET_ON_GAME_OBJECT:
				paymentClickTick = Integer.MIN_VALUE / 2;
				onObjectClicked(event.getId(), event.getParam0(), event.getParam1(), option,
					action == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT, tick);
				break;
			case NPC_FIRST_OPTION:
			case NPC_SECOND_OPTION:
			case NPC_THIRD_OPTION:
			case NPC_FOURTH_OPTION:
			case NPC_FIFTH_OPTION:
			case WIDGET_TARGET_ON_NPC:
				onNpcClicked(event.getMenuEntry().getNpc(), option, action == MenuAction.WIDGET_TARGET_ON_NPC, tick);
				break;
			case WIDGET_TARGET_ON_WIDGET:
				// Using one inventory item on another (herb on vial, knife on logs), or a spell on
				// an item ("High Level Alchemy -> Rune platebody"), which is filed by spell.
				startProcessing(tick, "cast".equals(optionLower) ? spellName(target) : null);
				break;
			case WALK:
			case PLAYER_FIRST_OPTION:
			case PLAYER_SECOND_OPTION:
			case PLAYER_THIRD_OPTION:
			case PLAYER_FOURTH_OPTION:
			case PLAYER_FIFTH_OPTION:
			case PLAYER_SIXTH_OPTION:
			case PLAYER_SEVENTH_OPTION:
			case PLAYER_EIGHTH_OPTION:
				// Walking off, or trading with another player, is never skilling.
				paymentClickTick = Integer.MIN_VALUE / 2;
				stopActivities();
				break;
			default:
				break;
		}
	}

	/**
	 * A spell's own right-click option in the spellbook, like NPC Contact → Dark Mage:
	 * a cast, even though the option doesn't say "Cast".
	 */
	private static boolean isSpellbookWidget(boolean spellbookOp, MenuOptionClicked event)
	{
		return spellbookOp && !event.isItemOp() && (event.getParam1() >>> 16) == InterfaceID.MAGIC_SPELLBOOK;
	}

	/** Something unrelated to farming or skilling was clicked. */
	private void stopActivities()
	{
		farming.onOtherAction();
		skilling.onOtherAction();
	}

	private void startProcessing(int tick)
	{
		startProcessing(tick, null);
	}

	/** @param spell the spell cast, when the action is a spell; Magic is filed by spell */
	private void startProcessing(int tick, String spell)
	{
		farming.onOtherAction();
		skilling.onProcessClicked(tick, spell);
	}

	private void onNpcClicked(NPC npc, String option, boolean usedSomethingOn, int tick)
	{
		farming.onOtherAction();
		String optionLower = option == null ? "" : option.toLowerCase(Locale.ENGLISH);
		if (npc == null)
		{
			skilling.onOtherAction();
			return;
		}
		paymentClickTick = optionLower.startsWith("pay") ? tick : Integer.MIN_VALUE / 2;

		SourceCategory gather = usedSomethingOn ? null : SkillRules.gatherFromNpc(option);
		String name = npcName(npc);
		if (gather != null && name != null)
		{
			String sourceName = gather == SourceCategory.FISHING ? SkillRules.fishingMethod(option) : name;
			skilling.onGatherClicked(gather, sourceName, tileKey(npc.getWorldLocation()), tick);
		}
		else if (!usedSomethingOn && name != null && SkillRules.couldGiveSkillingXp(option))
		{
			// Includes Talk-to, so conversions chosen in dialogue (the sawmill) are tracked too.
			skilling.onOtherTargetClicked(name, tileKey(npc.getWorldLocation()), tick);
		}
		else
		{
			skilling.onOtherAction();
		}
	}

	private void onInventoryItemClicked(int itemId, String option, int tick)
	{
		if (option == null)
		{
			return;
		}
		String o = option.toLowerCase(Locale.ENGLISH);
		if (o.equals("drop"))
		{
			drops.onDropClicked(itemId, tick);
			return;
		}
		if (o.equals("bury") || o.equals("scatter"))
		{
			buryClickTick = tick;
		}
		if (SkillRules.isProcessingItemOption(o))
		{
			startProcessing(tick);
			return;
		}
		SupplyTracker.Kind kind = null;
		if (o.equals("drink"))
		{
			kind = SupplyTracker.Kind.POTION;
		}
		else if (o.equals("eat"))
		{
			kind = SupplyTracker.Kind.FOOD;
		}
		else if (ItemRules.isTeleportConsumable(itemInfo.name(itemId), option))
		{
			kind = SupplyTracker.Kind.TELEPORT;
			stopActivities();
		}
		else if (SkillRules.isPouchShuffle(itemInfo.name(itemId), option))
		{
			pouchClickTick = tick;
			pouchClickContents = SkillRules.bagContents(itemInfo.name(itemId));
			return;
		}
		if (kind != null)
		{
			supplies.onConsumeClicked(itemId, kind, inventoryCount(itemId), tick);
		}
	}

	private void onObjectClicked(int objectId, int sceneX, int sceneY, String option, boolean usedItemOn, int tick)
	{
		ObjectComposition base = client.getObjectDefinition(objectId);
		if (base == null)
		{
			stopActivities();
			return;
		}
		ObjectComposition shown = base.getImpostorIds() != null ? base.getImpostor() : base;
		if (shown != null && shown.getName() != null && shown.getName().toLowerCase(Locale.ENGLISH).contains("totem"))
		{
			skilling.onValeTotemClicked(tick);
		}
		if (shown == null)
		{
			shown = base;
		}
		TileKey tile = sceneTile(sceneX, sceneY);

		if (isFarmingPatch(base, shown))
		{
			skilling.onOtherAction();
			if (config.trackFarming())
			{
				farming.onPatchClicked(tile, patchCategory(base, shown),
					ItemRules.cropFromPatchAppearance(shown.getName()), tick);
			}
			return;
		}
		farming.onOtherAction();

		if (usedItemOn)
		{
			// Raw food on a range, ore on a furnace, logs on a fire...
			startProcessing(tick);
			return;
		}
		SourceCategory gather = SkillRules.gatherFromObject(option);
		if (gather != null && shown.getName() != null)
		{
			String sourceName = gather == SourceCategory.FISHING ? SkillRules.fishingMethod(option) : shown.getName();
			skilling.onGatherClicked(gather, sourceName, tile, tick);
		}
		else if (SkillRules.isProcessingObjectOption(option))
		{
			startProcessing(tick);
		}
		else if (shown.getName() != null && !"null".equals(shown.getName()) && SkillRules.couldGiveSkillingXp(option))
		{
			// Anything else, e.g. "Tend-to" on a Forester's campfire: tracked if it gives XP.
			skilling.onOtherTargetClicked(shown.getName(), tile, tick);
		}
		else
		{
			skilling.onOtherAction();
		}
	}

	private static boolean isUseOnSomething(MenuAction action)
	{
		return action == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT || action == MenuAction.WIDGET_TARGET_ON_NPC
			|| action == MenuAction.WIDGET_TARGET_ON_WIDGET || action == MenuAction.WIDGET_TARGET_ON_GROUND_ITEM
			|| action == MenuAction.WIDGET_TARGET_ON_PLAYER;
	}

	/** Patches are recognised by name ("Herb patch") or by the farming-only Guide / Rake options. */
	private static boolean isFarmingPatch(ObjectComposition base, ObjectComposition shown)
	{
		for (ObjectComposition comp : new ObjectComposition[]{base, shown})
		{
			if (comp == null)
			{
				continue;
			}
			String name = comp.getName();
			if (name != null && name.toLowerCase(Locale.ENGLISH).contains("patch"))
			{
				return true;
			}
			String[] actions = comp.getActions();
			if (actions == null)
			{
				continue;
			}
			for (String action : actions)
			{
				if ("Guide".equalsIgnoreCase(action) || "Rake".equalsIgnoreCase(action))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** "Herb patch" from the base object, or from the patch's current look when the base has no name. */
	private static String patchCategory(ObjectComposition base, ObjectComposition shown)
	{
		String name = base.getName();
		if ((name == null || "null".equals(name) || !name.toLowerCase(Locale.ENGLISH).contains("patch"))
			&& shown.getName() != null && shown.getName().toLowerCase(Locale.ENGLISH).contains("patch"))
		{
			name = shown.getName();
		}
		return ItemRules.patchCategory(name);
	}

	// ---------------------------------------------------------------- inventory, equipment, varps

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (!tracking())
		{
			return;
		}
		if (event.getContainerId() == InventoryID.INV)
		{
			onInventoryChanged(event.getItemContainer());
			accumulateCarriedChanges();
		}
		else if (event.getContainerId() == InventoryID.WORN)
		{
			onEquipmentChanged(event.getItemContainer());
			accumulateCarriedChanges();
		}
		else if (event.getContainerId() == InventoryID.SEED_BOX)
		{
			// Seeds from a Master Farmer or a bird's nest go straight into an open seed box.
			// Counting its contents as carried makes those gains (and seeds planted from it) show,
			// while moving seeds between it and the inventory cancels out.
			Map<Integer, Integer> now = counts(event.getItemContainer());
			if (lastSeedBox != null && !isStorageOpen())
			{
				InventoryDiff.between(lastSeedBox, now).changes()
					.forEach((id, delta) -> tickChanges.merge(id, delta, Integer::sum));
			}
			lastSeedBox = now;
		}
	}

	private void onInventoryChanged(ItemContainer container)
	{
		Map<Integer, Integer> now = counts(container);
		int tick = client.getTickCount();

		// Banking, the tool leprechaun and the seed vault move items in and out;
		// none of that is ever loot or a supply cost.
		if (isStorageOpen())
		{
			supplies.reset();
			paymentClickTick = Integer.MIN_VALUE / 2;
			return;
		}
		tickConsumed.addAll(supplies.onInventoryChanged(id -> now.getOrDefault(id, 0), tick));
	}

	/**
	 * Inventory and worn equipment are compared as one pool of carried items, so
	 * equipping or unequipping something moves it within the pool and changes
	 * nothing. Changes are gathered over the tick and handled together on GameTick.
	 */
	private void accumulateCarriedChanges()
	{
		if (isStorageOpen())
		{
			storageThisTick = true;
		}
		if (lastCarried == null)
		{
			return;
		}
		Map<Integer, Integer> carried = carriedCounts();
		InventoryDiff.between(lastCarried, carried).changes()
			.forEach((id, delta) -> tickChanges.merge(id, delta, Integer::sum));
		lastCarried = carried;
	}

	private Map<Integer, Integer> carriedCounts()
	{
		Map<Integer, Integer> carried = new HashMap<>();
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (inv != null)
		{
			counts(inv).forEach((id, qty) -> carried.merge(id, qty, Integer::sum));
		}
		if (worn != null)
		{
			counts(worn).forEach((id, qty) -> carried.merge(id, qty, Integer::sum));
		}
		return carried;
	}

	/** Books everything carried items did this tick. Runs first on each GameTick. */
	private void processCarriedChanges(int tick)
	{
		if (lastCarried == null)
		{
			// First tick after login: both containers are loaded now, so take the baseline.
			lastCarried = carriedCounts();
			clearTickChanges();
			return;
		}
		for (Map.Entry<Integer, Integer> change : tickChanges.entrySet())
		{
			int id = change.getKey();
			if (change.getValue() < 0
				&& (id == ItemID.SNAKEBOSS_SCALE || ChargedWeapons.BLOWPIPE_DART_PROJECTILES.containsValue(id)))
			{
				// Darts or scales loaded into the blowpipe: the last Check is out of date.
				recentSupplies.forgetBlowpipeCheck();
				break;
			}
		}
		if (storageThisTick)
		{
			// Items went into or out of storage, so recent loot can no longer be matched to drops.
			ledger.forgetLootHistory();
			clearTickChanges();
			return;
		}
		if (tickChanges.isEmpty())
		{
			tickConsumed.clear();
			return;
		}

		InventoryDiff diff = InventoryDiff.of(tickChanges).withoutNoteConversions(itemInfo);
		List<Integer> consumed = new ArrayList<>(tickConsumed);
		clearTickChanges();

		// Dropped items come back out of whichever source gave them, and are remembered on
		// the floor so picking them back up puts them back. They are never a cost.
		Map<Integer, Integer> dropped = drops.dropsIn(diff, tick);
		TileKey here = localTile();
		dropped.forEach((id, amount) ->
			ledger.removeDroppedLoot(id, -amount).forEach((sourceKey, qty) ->
				groundDrops.recordPlayerDrop(sourceKey, id, (int) (long) qty, here, tick)));
		diff = diff.without(dropped);

		// Minigame-only items (Guardians of the Rift essence, Wintertodt roots...) never count,
		// and neither does an essence pouch degrading or being repaired.
		Map<Integer, Integer> ignored = new HashMap<>();
		diff.changes().forEach((id, delta) ->
		{
			String name = itemInfo.name(id);
			if (ItemRules.isMinigameItem(name) || ItemRules.isDegrading(name))
			{
				ignored.put(id, delta);
			}
		});
		diff = diff.without(ignored);
		if (diff.isEmpty())
		{
			return;
		}

		// Filling or emptying a pouch or bag (essence pouches, rune pouch, fish barrel, log
		// basket, gem bag, herb sack, seed box) only moves items around. Only what that bag
		// holds is ignored, so runes crafted right after emptying a pouch still count.
		if (tick - pouchClickTick <= POUCH_WINDOW_TICKS)
		{
			Map<Integer, Integer> shuffled = new HashMap<>();
			diff.changes().forEach((id, delta) ->
			{
				if (pouchClickContents.test(itemInfo.name(id)))
				{
					shuffled.put(id, delta);
				}
			});
			diff = diff.without(shuffled);
		}

		// A binding necklace crumbling is charged per craft instead (see bookBindingCharge).
		Map<Integer, Integer> necklace = new HashMap<>();
		diff.changes().forEach((id, delta) ->
		{
			if (delta < 0 && "binding necklace".equalsIgnoreCase(itemInfo.name(id)))
			{
				necklace.put(id, delta);
			}
		});
		diff = diff.without(necklace);
		bookBindingCharge(diff);

		// Food eaten and potions drunk are already supplies; the leftover dose isn't loot.
		diff = diff.without(consumedChanges(consumed, diff));
		if (diff.isEmpty())
		{
			return;
		}

		// A minigame reward pull: everything received is that minigame's loot.
		if (rewards.onCarriedChanges(diff, tick, ledger))
		{
			return;
		}

		Map<Integer, Integer> loadedIntoCannon = new HashMap<>();
		for (Map.Entry<Integer, Integer> change : diff.changes().entrySet())
		{
			int id = change.getKey();
			int delta = change.getValue();
			if (delta < 0 && ItemRules.isRune(itemInfo.name(id), itemInfo.stackable(id)))
			{
				supplies.onRunesLost(id, -delta);
			}
			if (delta < 0 && isCannonball(id))
			{
				// Loading the cannon isn't a cost: each ball is charged when it's fired.
				cannonballItem = id;
				loadedIntoCannon.put(id, delta);
			}
		}
		diff = diff.without(loadedIntoCannon);
		if (diff.isEmpty())
		{
			return;
		}

		if (config.trackFarming())
		{
			// A payment only ever removes items; anything gained means it's something else.
			if (tick - paymentClickTick <= PAYMENT_WINDOW_TICKS && diff.hasNoGains())
			{
				farming.onGardenerPayment(diff, tick, localTile());
				paymentClickTick = Integer.MIN_VALUE / 2;
			}
			else
			{
				farming.onInventoryChanged(diff);
			}
		}
		// While a patch is being worked, its changes are farming's, never a skill's.
		if (!(config.trackFarming() && farming.isArmed()))
		{
			skilling.onInventoryChanged(diff);
		}
	}

	/** Each combination-rune craft uses one of a worn binding necklace's 16 charges. */
	private void bookBindingCharge(InventoryDiff diff)
	{
		boolean crafted = diff.changes().entrySet().stream()
			.anyMatch(e -> e.getValue() > 0 && SkillGroups.isCombinationRune(itemInfo.name(e.getKey())));
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (!crafted || worn == null)
		{
			return;
		}
		Item amulet = worn.getItem(EquipmentInventorySlot.AMULET.getSlotIdx());
		if (amulet == null || !"binding necklace".equalsIgnoreCase(itemInfo.name(amulet.getId())))
		{
			return;
		}
		int id = amulet.getId();
		skilling.onSupplyUsed(SupplyTracker.charge(id, "binding-charge", "Binding necklace", "charges", 1,
			Math.round(itemInfo.marketPrice(id) / 16.0)));
	}

	private static boolean isCannonball(int itemId)
	{
		return itemId == ItemID.MCANNONBALL || itemId == ItemID.GRANITE_CANNONBALL;
	}

	private void clearTickChanges()
	{
		tickChanges.clear();
		tickConsumed.clear();
		storageThisTick = false;
	}

	/** The inventory changes explained by consumables: the item eaten or sipped, and what it left behind. */
	private Map<Integer, Integer> consumedChanges(List<Integer> consumed, InventoryDiff diff)
	{
		Map<Integer, Integer> explained = new HashMap<>();
		for (int id : consumed)
		{
			explained.merge(id, -1, Integer::sum);
			String base = ItemRules.withoutDoses(itemInfo.name(id));
			for (Map.Entry<Integer, Integer> change : diff.changes().entrySet())
			{
				if (change.getValue() <= 0)
				{
					continue;
				}
				String name = itemInfo.name(change.getKey());
				if (ItemRules.isLeftover(base, name))
				{
					explained.merge(change.getKey(), 1, Integer::sum);
				}
			}
		}
		return explained;
	}

	private void onEquipmentChanged(ItemContainer container)
	{
		Item ammo = container.getItem(EquipmentInventorySlot.AMMO.getSlotIdx());
		Item weapon = container.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		int newAmmoId = ammo == null ? -1 : ammo.getId();
		int newAmmoQty = ammo == null ? 0 : ammo.getQuantity();
		int newWeaponId = weapon == null ? -1 : weapon.getId();
		int newWeaponQty = weapon == null ? 0 : weapon.getQuantity();

		updateCombatTarget(client.getTickCount());
		boolean inCombat = client.getTickCount() - lastCombatTick <= AMMO_WINDOW_TICKS;
		if (config.trackAmmo() && inCombat && !isStorageOpen())
		{
			if (newAmmoId == ammoId && newAmmoQty < ammoQty)
			{
				supplies.recordDirect(SupplyTracker.Kind.AMMO, ammoId, ammoQty - newAmmoQty);
			}
			// Thrown weapons (darts, knives, chinchompas) are stackable and held in the weapon slot.
			if (newWeaponId == weaponId && newWeaponQty < weaponQty && weaponQty > 1)
			{
				supplies.recordDirect(SupplyTracker.Kind.AMMO, weaponId, weaponQty - newWeaponQty);
			}
		}
		// Serpentine, tanzanite and magma helms show their scales as the item's quantity.
		Item head = container.getItem(EquipmentInventorySlot.HEAD.getSlotIdx());
		int newHeadId = head == null ? -1 : head.getId();
		int newHeadQty = head == null ? 0 : head.getQuantity();
		if (config.trackAmmo() && inCombat && headId > 0 && ChargedWeapons.isScaleHelm(itemInfo.name(headId)))
		{
			int used = 0;
			if (newHeadId == headId && newHeadQty < headQty)
			{
				used = headQty - newHeadQty;
			}
			else if (newHeadId > 0 && !ChargedWeapons.isScaleHelm(itemInfo.name(newHeadId))
				&& itemInfo.name(newHeadId).toLowerCase(Locale.ENGLISH).contains("helm") && headQty <= 10)
			{
				// The last scales used up: the helm turns into its uncharged version.
				used = headQty;
			}
			if (used > 0)
			{
				supplies.recordDirect(SupplyTracker.Kind.CHARGES, ItemID.SNAKEBOSS_SCALE, used);
			}
		}
		Item cape = container.getItem(EquipmentInventorySlot.CAPE.getSlotIdx());
		capeId = cape == null ? -1 : cape.getId();

		ammoId = newAmmoId;
		ammoQty = newAmmoQty;
		weaponId = newWeaponId;
		weaponQty = newWeaponQty;
		headId = newHeadId;
		headQty = newHeadQty;
	}

	// ---------------------------------------------------------------- charged weapons, quiver, cannon

	/**
	 * The blowpipe's shots are too quick to count by animation changes, so (like the
	 * Supplies Tracker plugin) a shot is counted when its attack animation is on its
	 * first frame at the start of a tick. Darts and scales aren't visible to plugins,
	 * so their use is the expected amount per shot.
	 */
	private void trackBlowpipe(int tick)
	{
		Player local = client.getLocalPlayer();
		// Once blowpipe shots have been seen as projectiles, those are counted instead:
		// one projectile is exactly one shot, where the animation can be missed or repeat.
		if (blowpipeProjectilesSeen || !config.trackAmmo() || local == null || weaponId <= 0
			|| tick == lastChargedAttackTick || local.getAnimationFrame() != 0
			|| !ChargedWeapons.isBlowpipeAttack(local.getAnimation()) || !ChargedWeapons.isBlowpipe(itemInfo.name(weaponId)))
		{
			return;
		}
		lastChargedAttackTick = tick;
		bookBlowpipeShot();
	}

	/** A blowpipe dart leaving the player: exactly one shot. */
	private void onBlowpipeProjectile(Projectile projectile, int tick)
	{
		if (!config.trackAmmo() || weaponId <= 0 || !ChargedWeapons.isBlowpipe(itemInfo.name(weaponId))
			|| !countedBlowpipeShots.add(projectile))
		{
			return;
		}
		if (!blowpipeProjectilesSeen)
		{
			blowpipeProjectilesSeen = true;
			if (tick - lastChargedAttackTick <= 1)
			{
				// This shot was already counted from its animation.
				return;
			}
		}
		lastChargedAttackTick = tick;
		bookBlowpipeShot();
	}

	private void bookBlowpipeShot()
	{
		bookingBlowpipe = true;
		try
		{
			bookBlowpipeCharges();
		}
		finally
		{
			bookingBlowpipe = false;
		}
	}

	private void bookBlowpipeCharges()
	{
		// 2 Zulrah's scales every 3 shots.
		blowpipeScaleRemainder += 2;
		int scales = blowpipeScaleRemainder / 3;
		blowpipeScaleRemainder %= 3;
		if (scales > 0)
		{
			supplies.recordDirect(SupplyTracker.Kind.CHARGES, ItemID.SNAKEBOSS_SCALE, scales);
		}
		int dart = ledger.data().blowpipeDart;
		if (dart > 0)
		{
			blowpipeDartRemainder += ChargedWeapons.dartLossRate(capeId > 0 ? itemInfo.name(capeId) : null);
			int darts = (int) blowpipeDartRemainder;
			blowpipeDartRemainder -= darts;
			if (darts > 0)
			{
				supplies.recordDirect(SupplyTracker.Kind.CHARGES, dart, darts);
			}
		}
	}

	/**
	 * Charged staves, the Scythe of vitur, Tumeken's shadow and revenant weapons:
	 * one charge per attack animation, priced at what refilling it costs.
	 */
	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (!tracking() || !config.trackAmmo() || event.getActor() != client.getLocalPlayer() || weaponId <= 0)
		{
			return;
		}
		int animation = event.getActor().getAnimation();
		for (int[] part : ChargedWeapons.costPerAttack(itemInfo.name(weaponId), animation))
		{
			int itemId = part[0];
			int per = part[2];
			int quantity = part[1];
			if (per > 1)
			{
				// e.g. one vial of blood every 100 scythe swings
				int owed = chargeRemainders.merge(itemId, quantity, Integer::sum);
				quantity = owed / per;
				chargeRemainders.put(itemId, owed % per);
			}
			if (quantity > 0)
			{
				supplies.recordDirect(SupplyTracker.Kind.CHARGES, itemId, quantity);
			}
		}
	}

	private void setBlowpipeDart(int dartId)
	{
		if (dartId > 0 && ledger.data().blowpipeDart != dartId)
		{
			ledger.data().blowpipeDart = dartId;
			ledger.changed();
		}
	}

	/** Dizana's quiver keeps its ammo in varps, not the equipment's ammo slot. */
	private void trackQuiverAmmo()
	{
		int newId = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
		int newQty = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
		updateCombatTarget(client.getTickCount());
		boolean inCombat = client.getTickCount() - lastCombatTick <= AMMO_WINDOW_TICKS;
		if (config.trackAmmo() && inCombat && !isStorageOpen() && quiverAmmoId > 0)
		{
			int used = 0;
			if (newId == quiverAmmoId && newQty < quiverAmmoQty)
			{
				used = quiverAmmoQty - newQty;
			}
			else if (newId <= 0 && quiverAmmoQty <= 2)
			{
				used = quiverAmmoQty;
			}
			if (used > 0 && used <= 2)
			{
				supplies.recordDirect(SupplyTracker.Kind.AMMO, quiverAmmoId, used);
			}
		}
		quiverAmmoId = newId;
		quiverAmmoQty = Math.max(0, newQty);
	}

	@Subscribe
	public void onProjectileMoved(ProjectileMoved event)
	{
		if (!tracking())
		{
			return;
		}
		Projectile projectile = event.getProjectile();
		int id = projectile.getId();

		// The dart flying out of a blowpipe tells us which dart is loaded.
		// A dart leaving our own tile while we fire a blowpipe tells us which dart is loaded.
		Integer dart = ChargedWeapons.BLOWPIPE_DART_PROJECTILES.get(id);
		Player local = client.getLocalPlayer();
		boolean fromMe = local != null
			&& (projectile.getSourceActor() == local || local.getWorldLocation().equals(projectile.getSourcePoint()));
		if (dart != null && fromMe && ChargedWeapons.isBlowpipeAttack(local.getAnimation()))
		{
			setBlowpipeDart(dart);
		}
		// Any projectile the player fires mid blowpipe attack is a shot (the special attack included).
		if (local != null && projectile.getSourceActor() == local && ChargedWeapons.isBlowpipeAttack(local.getAnimation()))
		{
			onBlowpipeProjectile(projectile, client.getTickCount());
		}

		// Remember which monster the cannon is shooting, so its cannonballs are charged to it.
		if (id == SpotanimID.CANNONBALL_TRAVEL || id == SpotanimID.CANNONBALL_TRAVEL_GRANITE
			|| id == SpotanimID.CANNONBALL_TRAVEL_LEAGUE || id == SpotanimID.CANNONBALL_TRAVEL_GRANITE_LEAGUE)
		{
			Actor target = projectile.getTargetActor();
			if (target instanceof NPC && npcName((NPC) target) != null)
			{
				cannonTargetName = npcName((NPC) target);
				cannonTargetIsTask = isTaskTarget(cannonTargetName);
				cannonTargetTick = client.getTickCount();
			}
			if (id == SpotanimID.CANNONBALL_TRAVEL_GRANITE || id == SpotanimID.CANNONBALL_TRAVEL_GRANITE_LEAGUE)
			{
				cannonballItem = ItemID.GRANITE_CANNONBALL;
			}
		}
	}

	/** Cannonballs go to the monster the cannon was shooting, else the one you're fighting. */
	private void bookCannonballs(int spent)
	{
		if (!config.trackCombat())
		{
			return;
		}
		int tick = client.getTickCount();
		String name;
		boolean task;
		if (cannonTargetName != null && tick - cannonTargetTick <= CANNON_TARGET_TICKS)
		{
			name = cannonTargetName;
			task = cannonTargetIsTask;
		}
		else if (combatKey != null && tick - lastCombatTick <= SUPPLY_ATTRIBUTION_TICKS)
		{
			name = combatName;
			task = combatIsTask;
		}
		else
		{
			supplies.recordDirect(SupplyTracker.Kind.CANNONBALL, cannonballItem, spent);
			return;
		}
		long gp = itemInfo.marketPrice(cannonballItem) * spent;
		ledger.addSupply(npcKey(name), name, SourceCategory.COMBAT, String.valueOf(cannonballItem), cannonballItem,
			itemInfo.name(cannonballItem), null, spent, gp);
		TaskRecord current = ledger.data().currentTask;
		if (task && current != null && !current.isFinished())
		{
			current.supplyGp += gp;
			ledger.changed();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (!tracking())
		{
			return;
		}
		if (event.getVarpId() == VarPlayerID.ROCKTHROWER)
		{
			int now = event.getValue();
			int spent = cannonballs - now;
			boolean placed = client.getVarpValue(VarPlayerID.DROPCANNON) == CANNON_PLACED;
			if (cannonballs >= 0 && placed && spent > 0 && spent <= MAX_BALLS_PER_TICK)
			{
				bookCannonballs(spent);
			}
			cannonballs = now;
			if (reminders.onCannonballs(now, config.cannonReminderBalls(), placed))
			{
				remind(config.cannonReminder(), "Cannon", now == 0
					? "Your cannon is out of cannonballs."
					: "Your cannon has " + now + (now == 1 ? " cannonball" : " cannonballs") + " left.");
			}
			return;
		}

		if (event.getVarpId() == VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO
			|| event.getVarpId() == VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT)
		{
			trackQuiverAmmo();
			return;
		}

		int varbit = event.getVarbitId();
		for (int i = 0; i < POUCH_QUANTITY_VARBITS.length; i++)
		{
			if (varbit == POUCH_TYPE_VARBITS[i])
			{
				pouchTypes[i] = event.getValue();
				pouchQuantities[i] = client.getVarbitValue(POUCH_QUANTITY_VARBITS[i]);
				return;
			}
			if (varbit == POUCH_QUANTITY_VARBITS[i])
			{
				int lost = pouchQuantities[i] - event.getValue();
				pouchQuantities[i] = event.getValue();
				int runeId = pouchRuneId(pouchTypes[i]);
				boolean pouchShuffle = client.getTickCount() - pouchClickTick <= POUCH_WINDOW_TICKS;
				if (lost > 0 && runeId > 0 && !isStorageOpen() && !pouchShuffle)
				{
					supplies.onPouchRunesLost(runeId, lost);
				}
				return;
			}
		}
	}

	private void syncPouchBaseline()
	{
		for (int i = 0; i < POUCH_TYPE_VARBITS.length; i++)
		{
			pouchTypes[i] = client.getVarbitValue(POUCH_TYPE_VARBITS[i]);
			pouchQuantities[i] = client.getVarbitValue(POUCH_QUANTITY_VARBITS[i]);
		}
	}

	private void syncEquipmentBaseline()
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn != null)
		{
			Item ammo = worn.getItem(EquipmentInventorySlot.AMMO.getSlotIdx());
			Item weapon = worn.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
			ammoId = ammo == null ? -1 : ammo.getId();
			ammoQty = ammo == null ? 0 : ammo.getQuantity();
			weaponId = weapon == null ? -1 : weapon.getId();
			weaponQty = weapon == null ? 0 : weapon.getQuantity();
			Item head = worn.getItem(EquipmentInventorySlot.HEAD.getSlotIdx());
			headId = head == null ? -1 : head.getId();
			headQty = head == null ? 0 : head.getQuantity();
			Item cape = worn.getItem(EquipmentInventorySlot.CAPE.getSlotIdx());
			capeId = cape == null ? -1 : cape.getId();
		}
		quiverAmmoId = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
		quiverAmmoQty = Math.max(0, client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT));
	}

	private int pouchRuneId(int type)
	{
		if (type <= 0)
		{
			return -1;
		}
		EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		return runes == null ? -1 : runes.getIntValue(type);
	}

	// ---------------------------------------------------------------- XP

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		int xp = event.getXp();
		Integer previous = lastXp.put(skill, xp);
		if (!tracking() || previous == null || xp <= previous)
		{
			return;
		}
		int gained = xp - previous;
		int tick = client.getTickCount();

		if (skill == Skill.MAGIC)
		{
			supplies.onMagicXp();
			// Teleport spells give Magic XP; it belongs to Teleports, not the last fight or skill.
			if (tick - lastTeleportCastTick <= TELEPORT_XP_WINDOW_TICKS)
			{
				ledger.addXp(TrackerData.TELEPORTS_KEY, TrackerData.TELEPORTS_NAME, SourceCategory.TELEPORTS,
					skill.getName(), gained);
				return;
			}
		}
		boolean fighting = combatKey != null && tick - lastCombatTick <= COMBAT_XP_WINDOW_TICKS;
		if (skill == Skill.FARMING && fighting && FarmingTracker.HESPORI.equalsIgnoreCase(combatName))
		{
			// Killing Hespori gives Farming XP: Farming's, not the fight's.
			ledger.addXp("farming:" + FarmingTracker.HESPORI, FarmingTracker.HESPORI, SourceCategory.FARMING,
				skill.getName(), gained);
			return;
		}
		if (skill == Skill.PRAYER && tick - buryClickTick > 5 && (fighting || !skilling.isActive())
			&& bookCrusherCharge(gained))
		{
			return;
		}
		if (config.trackFarming())
		{
			farming.onXp(skill.getName(), gained);
		}
		// Magic XP during a skilling action (alching mid-task, say) is that action's, not the fight's.
		boolean magicForSkilling = skill == Skill.MAGIC && skilling.isActive();
		boolean farmingXp = skill == Skill.FARMING
			|| (config.trackFarming() && farming.isArmed() && skill == Skill.WOODCUTTING);
		if (!NON_SKILLING_XP.contains(skill) && !farmingXp
			&& (!fighting || skill != Skill.MAGIC || magicForSkilling))
		{
			if (skilling.isActive())
			{
				skilling.onXp(skill.getName(), gained);
			}
			else if (skill != Skill.MAGIC || tick - lastCombatTick > COMBAT_XP_WINDOW_TICKS)
			{
				// XP from nothing being done: minigame rewards (Guardians of the Rift, Wintertodt...),
				// lamps and the like go to the skill's "Other".
				skilling.bookOtherXp(skill.getName(), gained);
			}
		}

		TaskRecord task = ledger.data().currentTask;
		boolean taskActive = task != null && !task.isFinished();
		if (skill == Skill.SLAYER && taskActive)
		{
			task.slayerXp += gained;
			ledger.changed();
		}

		if (config.trackCombat() && COMBAT_SKILLS.contains(skill) && combatKey != null
			&& tick - lastCombatTick <= COMBAT_XP_WINDOW_TICKS && !magicForSkilling)
		{
			ledger.addXp(combatKey, combatName, SourceCategory.COMBAT, skill.getName(), gained);
			if (combatIsTask && taskActive && skill != Skill.SLAYER)
			{
				task.xp += gained;
				ledger.changed();
			}
		}
	}

	// ---------------------------------------------------------------- chat

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() == ChatMessageType.GAMEMESSAGE
			&& Text.removeTags(event.getMessage()).startsWith("A superior foe has appeared"))
		{
			remind(config.superiorReminder(), "Superior spawn", "A superior foe has appeared!");
		}
		if (tracking() && (event.getType() == ChatMessageType.GAMEMESSAGE || event.getType() == ChatMessageType.SPAM))
		{
			// "You've caught a crimson swift." names what a trap caught (some are filtered spam).
			skilling.onChatMessage(Text.removeTags(event.getMessage()), client.getTickCount());
		}
		if (tracking() && event.getType() == ChatMessageType.GAMEMESSAGE)
		{
			// "Check" on a blowpipe: "Darts: Adamant dart x 1,234. Scales: ..." tells us the dart.
			String message = Text.removeTags(event.getMessage());
			String dart = ChargedWeapons.dartFromCheckMessage(message);
			int dartId = -1;
			if (dart != null)
			{
				for (int id : ChargedWeapons.BLOWPIPE_DART_PROJECTILES.values())
				{
					if (dart.equalsIgnoreCase(itemInfo.name(id)))
					{
						setBlowpipeDart(id);
						dartId = id;
					}
				}
			}
			long[] counts = ChargedWeapons.blowpipeCheckCounts(message);
			if (counts != null)
			{
				// The exact darts and scales left: correct the per-shot estimate since the last Check.
				recentSupplies.onBlowpipeCheck(dartId, counts[0], counts[1], ItemID.SNAKEBOSS_SCALE, itemInfo::marketPrice);
				blowpipeDartRemainder = 0;
				blowpipeScaleRemainder = 0;
			}
		}
		if (tracking() && config.trackFarming()
			&& (event.getType() == ChatMessageType.GAMEMESSAGE || event.getType() == ChatMessageType.SPAM))
		{
			farming.onChatMessage(Text.removeTags(event.getMessage()), localTile(), client.getTickCount());
		}
	}

	// ---------------------------------------------------------------- tick

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!tracking())
		{
			return;
		}
		int tick = client.getTickCount();
		updateCombatTarget(tick);
		trackBlowpipe(tick);
		processCarriedChanges(tick);
		supplies.onGameTick(tick);
		// Runes taken from the rune pouch by no spell (combination runecrafting) cost the action.
		Map<Integer, Integer> pouchRunes = supplies.takeUnusedPouchRunes();
		if (!pouchRunes.isEmpty() && skilling.isActive())
		{
			Map<Integer, Integer> used = new HashMap<>();
			pouchRunes.forEach((id, qty) -> used.put(id, -qty));
			skilling.onInventoryChanged(InventoryDiff.of(used));
		}
		farming.onGameTick(tick, localTile());
		skilling.onGameTick(tick, localTile());
		groundDrops.expire(tick);
		recentSupplies.expire(tick);
		if (profileLoaded)
		{
			sessions.heartbeat();
		}
		boolean inInstance = client.isInInstancedRegion();
		if (inInstance && !wasInInstance)
		{
			instanceEnteredTick = tick;
		}
		wasInInstance = inInstance;
		checkReminders(tick);

		if (tick - loginTick > SLAYER_SETTLE_TICKS)
		{
			syncSlayerTask();
		}
		if (tick % SAVE_INTERVAL_TICKS == 0)
		{
			save();
		}
		refreshPanel(false);
	}

	// ---------------------------------------------------------------- reminders

	private void checkReminders(int tick)
	{
		if (reminders.onPrayer(client.getBoostedSkillLevel(Skill.PRAYER), config.prayerReminderPoints()))
		{
			remind(config.prayerReminder(), "Prayer",
				"Your prayer is low: " + client.getBoostedSkillLevel(Skill.PRAYER) + " points left.");
		}

		Map<String, Integer> boosts = new LinkedHashMap<>();
		Map<String, Integer> divine = new HashMap<>();
		for (Skill skill : BOOSTED_SKILLS)
		{
			if (config.boostReminderCombatOnly() && !COMBAT_BOOST_SKILLS.contains(skill))
			{
				continue;
			}
			boosts.put(skill.getName(), client.getBoostedSkillLevel(skill) - client.getRealSkillLevel(skill));
			divine.put(skill.getName(), divinePotionTicks(skill));
		}
		int warnTicks = (int) Math.ceil(config.boostReminderSeconds() / 0.6);
		List<String> ending = reminders.onBoosts(tick, boosts, divine, client.isPrayerActive(Prayer.PRESERVE), warnTicks);
		if (!ending.isEmpty())
		{
			remind(config.boostReminder(), "Boost", "Your " + joinSkills(ending)
				+ (ending.size() == 1 ? " boost runs" : " boosts run") + " out in about "
				+ config.boostReminderSeconds() + " seconds.");
		}
	}

	/**
	 * Prayer XP with no burying or scattering: a bonecrusher or ash sanctifier did it as a
	 * monster died. Each one uses a charge (the ash sanctifier's are a tenth of a death rune;
	 * the bonecrusher's ecto-tokens are worth nothing). Returns true if it was booked.
	 */
	private boolean bookCrusherCharge(long xp)
	{
		boolean crusher = carries("bonecrusher");
		boolean sanctifier = carries("ash sanctifier");
		if (!crusher && !sanctifier)
		{
			return false;
		}
		boolean ashes = sanctifier && (!crusher || ItemRules.isAshSanctifierXp(xp));
		String name = ashes ? "Ash sanctifier" : "Bonecrusher";
		int itemId = itemInfo.idByName(name);
		long gp = ashes ? Math.round(itemInfo.marketPrice(ItemID.DEATHRUNE) / 10.0) : 0;
		String key = "item:PRAYER:" + name;
		ledger.addSupply(key, name, SourceCategory.PRAYER, name.toLowerCase(Locale.ENGLISH) + "-charge",
			Math.max(itemId, 0), name, "charges", 1, gp);
		ledger.addXp(key, name, SourceCategory.PRAYER, Skill.PRAYER.getName(), xp);
		return true;
	}

	/** Is an item whose name starts with this carried (inventory or worn)? */
	private boolean carries(String namePrefix)
	{
		for (int containerId : new int[]{InventoryID.INV, InventoryID.WORN})
		{
			ItemContainer container = client.getItemContainer(containerId);
			if (container == null)
			{
				continue;
			}
			for (Item item : container.getItems())
			{
				if (item != null && item.getId() > 0
					&& itemInfo.name(item.getId()).toLowerCase(Locale.ENGLISH).startsWith(namePrefix))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Sends a reminder's notification, plus the popup box saying what it's for. */
	private void remind(Notification notification, String title, String message)
	{
		if (!notification.isEnabled())
		{
			return;
		}
		notifier.notify(notification, message);
		if (config.reminderPopup())
		{
			popup.show(title, message);
		}
	}

	/** Game ticks left on a divine potion boosting this skill (the varbits count game ticks). */
	private int divinePotionTicks(Skill skill)
	{
		int combat = client.getVarbitValue(VarbitID.DIVINECOMBAT_POTION_TIME);
		int bastion = client.getVarbitValue(VarbitID.DIVINEBASTION_POTION_TIME);
		int battlemage = client.getVarbitValue(VarbitID.DIVINEBATTLEMAGE_POTION_TIME);
		int steps;
		switch (skill)
		{
			case ATTACK:
				steps = Math.max(combat, client.getVarbitValue(VarbitID.DIVINEATTACK_POTION_TIME));
				break;
			case STRENGTH:
				steps = Math.max(combat, client.getVarbitValue(VarbitID.DIVINESTRENGTH_POTION_TIME));
				break;
			case DEFENCE:
				steps = Math.max(Math.max(combat, client.getVarbitValue(VarbitID.DIVINEDEFENCE_POTION_TIME)),
					Math.max(bastion, battlemage));
				break;
			case RANGED:
				steps = Math.max(bastion, client.getVarbitValue(VarbitID.DIVINERANGE_POTION_TIME));
				break;
			case MAGIC:
				steps = Math.max(battlemage, client.getVarbitValue(VarbitID.DIVINEMAGIC_POTION_TIME));
				break;
			default:
				steps = 0;
		}
		return steps;
	}

	private static Skill skillFor(SourceCategory category)
	{
		String skillName = category == null ? null : category.getSkillName();
		if (skillName == null)
		{
			return null;
		}
		for (Skill skill : Skill.values())
		{
			if (skill.getName().equalsIgnoreCase(skillName))
			{
				return skill;
			}
		}
		return null;
	}

	/** "Attack", "Attack and Strength", "Attack, Strength and Defence". */
	private static String joinSkills(List<String> skills)
	{
		if (skills.size() == 1)
		{
			return skills.get(0);
		}
		return String.join(", ", skills.subList(0, skills.size() - 1)) + " and " + skills.get(skills.size() - 1);
	}

	private void updateCombatTarget(int tick)
	{
		Player local = client.getLocalPlayer();
		if (local == null || !(local.getInteracting() instanceof NPC))
		{
			return;
		}
		NPC npc = (NPC) local.getInteracting();
		if (!isAttackable(npc))
		{
			return;
		}
		String name = npcName(npc);
		if (name == null)
		{
			return;
		}
		if (combatKey == null || !combatKey.equals(npcKey(name)) || tick - lastCombatTick > SUPPLY_ATTRIBUTION_TICKS)
		{
			fightStartTick = tick;
		}
		combatName = name;
		combatKey = npcKey(name);
		combatIsTask = isTaskTarget(name);
		lastCombatTick = tick;
	}

	private void syncSlayerTask()
	{
		String task = slayerService.getTask();
		int remaining = slayerService.getRemainingAmount();
		TrackerData data = ledger.data();
		TaskRecord current = data.currentTask;
		long now = ledger.now();

		if (task == null || task.isEmpty() || remaining <= 0)
		{
			// The Slayer plugin reports a blank task briefly while loading, so wait for it to settle.
			if (current != null && !current.isFinished() && ++slayerBlankCount >= SLAYER_BLANK_CONFIRMATIONS)
			{
				current.remainingAmount = 0;
				current.finishedMillis = now;
				ledger.changed();
			}
			return;
		}
		slayerBlankCount = 0;

		if (current == null || current.isFinished() || !task.equalsIgnoreCase(current.taskName))
		{
			data.archiveCurrentTask(now);
			data.currentTask = new TaskRecord(task, slayerService.getTaskLocation(),
				slayerService.getInitialAmount(), remaining, now);
			taskTargetNames.clear();
			ledger.changed();
		}
		else if (current.remainingAmount != remaining)
		{
			current.remainingAmount = remaining;
			current.initialAmount = Math.max(current.initialAmount, slayerService.getInitialAmount());
			ledger.changed();
		}

		for (NPC npc : slayerService.getTargets())
		{
			String name = npcName(npc);
			if (name != null)
			{
				taskTargetNames.add(name.toLowerCase(Locale.ENGLISH));
			}
		}
	}

	// ---------------------------------------------------------------- supply booking

	private void bookSupply(SupplyTracker.Use use)
	{
		if (ItemRules.isMinigameItem(itemInfo.name(use.itemId)))
		{
			return;
		}
		// Teleports are their own category, never charged to a monster, task or skill.
		if (use.teleport != null)
		{
			ledger.addSupply(TrackerData.TELEPORTS_KEY, TrackerData.TELEPORTS_NAME, SourceCategory.TELEPORTS,
				use.lineKey, use.itemId, use.lineName, use.unit, use.quantity, use.gp);
			if (use.countsAsUse)
			{
				ledger.incrementCount(TrackerData.TELEPORTS_KEY, TrackerData.TELEPORTS_NAME, SourceCategory.TELEPORTS);
			}
			return;
		}

		int tick = client.getTickCount();
		// Supplies used on the very first attack arrive before this tick's target update.
		updateCombatTarget(tick);
		boolean recentFight = config.trackCombat() && combatKey != null
			&& tick - lastCombatTick <= SUPPLY_ATTRIBUTION_TICKS;

		// During a skilling action (alching, say), its runes and food are that action's, even
		// mid-Slayer task. Cannonballs and arrows only ever come from a fight.
		boolean combatOnly = use.kind == SupplyTracker.Kind.CANNONBALL || use.kind == SupplyTracker.Kind.AMMO
			|| use.kind == SupplyTracker.Kind.CHARGES;
		if (!combatOnly && skilling.onSupplyUsed(use))
		{
			return;
		}
		if (!recentFight)
		{
			// Used outside any fight or skilling action: one General supplies table.
			ledger.addSupply(TrackerData.GENERAL_SUPPLIES_KEY, TrackerData.GENERAL_SUPPLIES_NAME,
				SourceCategory.GENERAL_SUPPLIES, use.lineKey, use.itemId, use.lineName, use.unit, use.quantity, use.gp);
			ledger.incrementCount(TrackerData.GENERAL_SUPPLIES_KEY, TrackerData.GENERAL_SUPPLIES_NAME,
				SourceCategory.GENERAL_SUPPLIES);
			RecentSupplies.Booked booked = new RecentSupplies.Booked(TrackerData.GENERAL_SUPPLIES_KEY,
				TrackerData.GENERAL_SUPPLIES_NAME, SourceCategory.GENERAL_SUPPLIES, false, use.lineKey, use.itemId,
				use.lineName, use.unit, use.quantity, use.gp, tick, true);
			recentSupplies.addGeneral(booked);
			if (bookingBlowpipe)
			{
				recentSupplies.addBlowpipe(booked);
			}
			return;
		}
		ledger.addSupply(combatKey, combatName, SourceCategory.COMBAT, use.lineKey, use.itemId, use.lineName,
			use.unit, use.quantity, use.gp);
		if (bookingBlowpipe)
		{
			recentSupplies.addBlowpipe(new RecentSupplies.Booked(combatKey, combatName, SourceCategory.COMBAT,
				combatIsTask, use.lineKey, use.itemId, use.lineName, use.unit, use.quantity, use.gp, tick, false));
		}

		TaskRecord task = ledger.data().currentTask;
		if (recentFight && combatIsTask && task != null && !task.isFinished())
		{
			task.supplyGp += use.gp;
			ledger.changed();
		}
	}

	// ---------------------------------------------------------------- panel

	private void onPanelAction(GildedLedgerPanel.Action action, String key)
	{
		clientThread.invoke(() ->
		{
			switch (action)
			{
				case RESET_SOURCE:
					ledger.remove(key);
					break;
				case RESET_CATEGORY:
					SourceCategory category = SourceCategory.valueOf(key);
					if (ledger.data().sources.values().removeIf(r -> r.category == category))
					{
						ledger.changed();
					}
					break;
				case RESET_ALL:
					ledger.data().sources.clear();
					resetTaskTotals();
					ledger.changed();
					break;
				case RESET_TASK:
					resetTaskTotals();
					break;
				case TOGGLE_LOOT:
				case TOGGLE_SUPPLY:
					toggleExcluded(action, key);
					break;
				case SESSION_START:
					sessions.start();
					break;
				case SESSION_PAUSE:
					sessions.pause();
					break;
				case SESSION_RESUME:
					sessions.resume();
					break;
				case SESSION_END:
					sessions.end();
					break;
				case SESSION_RENAME:
				{
					int split = key.indexOf('\n');
					if (split > 0)
					{
						sessions.rename(key.substring(0, split), key.substring(split + 1));
					}
					break;
				}
				case SESSION_DELETE:
					sessions.delete(key);
					break;
				case SESSION_CLEAR:
					sessions.clearLog();
					break;
			}
			save();
			refreshPanel(true);
		});
	}

	/** Right-click "Exclude from profit" / "Include in profit" on a loot or supply icon. */
	private void toggleExcluded(GildedLedgerPanel.Action action, String key)
	{
		int split = key.indexOf('\n');
		if (split < 0)
		{
			return;
		}
		String sourceKey = key.substring(0, split);
		String item = key.substring(split + 1);
		boolean loot = action == GildedLedgerPanel.Action.TOGGLE_LOOT;
		int itemId;
		try
		{
			itemId = loot ? Integer.parseInt(item) : -1;
		}
		catch (NumberFormatException e)
		{
			return;
		}

		// A skill shown as one combined table: apply to every entry in that skill.
		List<SourceRecord> records = new ArrayList<>();
		if (sourceKey.startsWith(PanelModel.COMBINED_PREFIX))
		{
			SourceCategory category;
			try
			{
				category = SourceCategory.valueOf(sourceKey.substring(PanelModel.COMBINED_PREFIX.length()));
			}
			catch (IllegalArgumentException e)
			{
				return;
			}
			for (SourceRecord r : ledger.data().sources.values())
			{
				if (r.category == category && (loot ? r.loot.containsKey(itemId) : r.supplies.containsKey(item)))
				{
					records.add(r);
				}
			}
		}
		else if (ledger.data().sources.containsKey(sourceKey))
		{
			records.add(ledger.data().sources.get(sourceKey));
		}
		if (records.isEmpty())
		{
			return;
		}

		boolean exclude = false;
		for (SourceRecord r : records)
		{
			exclude |= loot ? !r.excludedLoot.contains(itemId) : !r.excludedSupplies.contains(item);
		}
		for (SourceRecord r : records)
		{
			if (loot)
			{
				if (exclude)
				{
					r.excludedLoot.add(itemId);
				}
				else
				{
					r.excludedLoot.remove(itemId);
				}
			}
			else if (exclude)
			{
				r.excludedSupplies.add(item);
			}
			else
			{
				r.excludedSupplies.remove(item);
			}
		}
		ledger.changed();
	}

	/** "High Level Alchemy -> Rune platebody" → "High Level Alchemy". */
	private static String spellName(String target)
	{
		if (target == null)
		{
			return null;
		}
		int arrow = target.indexOf("->");
		String spell = (arrow >= 0 ? target.substring(0, arrow) : target).trim();
		return spell.isEmpty() ? null : spell;
	}

	/** Zeroes the current Slayer task's totals but keeps the task itself. */
	private void resetTaskTotals()
	{
		TaskRecord t = ledger.data().currentTask;
		if (t == null)
		{
			return;
		}
		t.kills = 0;
		t.lootGp = 0;
		t.supplyGp = 0;
		t.xp = 0;
		t.slayerXp = 0;
		t.startedMillis = ledger.now();
		ledger.changed();
	}

	private void refreshPanel(boolean force)
	{
		if (panel == null || ledger == null)
		{
			return;
		}
		if (!force && ledger.revision() == shownRevision)
		{
			return;
		}
		shownRevision = ledger.revision();
		Set<SourceCategory> hiddenCategories = hiddenCategories();
		boolean hidePlants = config.hideUntradeablePlants();
		Set<String> untradeableCrops = new HashSet<>(ledger.data().untradeableCrops);
		PanelModel model = PanelModel.build(ledger.data(), lootPrices, itemInfo::name, profileLoaded,
			config.skillLayout() == GildedLedgerConfig.SkillLayout.COMBINED,
			record -> hiddenCategories.contains(record.category)
				|| (hidePlants && record.category == SourceCategory.FARMING && untradeableCrops.contains(record.name)));
		boolean collapseNew = config.collapseNew();
		GpSession liveSession = profileLoaded ? sessions.live() : null;
		List<GpSession> sessionLog = new ArrayList<>(ledger.data().sessionLog);
		Map<String, PanelModel.SessionDetail> sessionDetails = new HashMap<>();
		for (GpSession logged : sessionLog)
		{
			sessionDetails.put(logged.id, PanelModel.sessionDetail(logged, lootPrices, itemInfo::name));
		}
		GildedLedgerPanel target = panel;
		SwingUtilities.invokeLater(() ->
		{
			target.setCollapseNew(collapseNew);
			target.update(model);
			target.updateSessions(liveSession, sessionLog, sessionDetails);
		});
	}

	// ---------------------------------------------------------------- helpers

	/** GE price, falling back to High Alchemy for untradeable items. Client thread only. */
	private final LootPrices lootPrices = new LootPrices()
	{
		@Override
		public long ge(int itemId)
		{
			int id = itemManager.canonicalize(itemId);
			if (id == ItemID.COINS)
			{
				return 1;
			}
			if (id == ItemID.PLATINUM)
			{
				return 1000;
			}
			if (isZeroValue(id))
			{
				return 0;
			}
			return itemManager.getItemPrice(id);
		}

		@Override
		public long highAlch(int itemId)
		{
			int id = itemManager.canonicalize(itemId);
			if (id == ItemID.COINS)
			{
				return 1;
			}
			if (id == ItemID.PLATINUM)
			{
				return 1000;
			}
			ItemComposition comp = itemManager.getItemComposition(id);
			return comp == null || ItemRules.isZeroValue(comp.getName()) ? 0 : comp.getHaPrice();
		}

		@Override
		public boolean valuedAtAlch(int itemId)
		{
			ItemComposition comp = itemManager.getItemComposition(itemManager.canonicalize(itemId));
			return comp != null && ItemRules.isTarnished(comp.getName());
		}

		@Override
		public boolean tradeable(int itemId)
		{
			int id = itemManager.canonicalize(itemId);
			if (id == ItemID.COINS || id == ItemID.PLATINUM)
			{
				return true;
			}
			ItemComposition comp = itemManager.getItemComposition(id);
			return comp != null && comp.isTradeable();
		}
	};

	/** Clues and reward currencies (marks of grace, abyssal pearls...) are worth nothing here. */
	private boolean isZeroValue(int itemId)
	{
		ItemComposition comp = itemManager.getItemComposition(itemId);
		return comp != null && ItemRules.isZeroValue(comp.getName());
	}

	private long lootPrice(int itemId)
	{
		return lootPrices.value(itemId);
	}

	private static final int[] STORAGE_INTERFACES = {
		InterfaceID.Bankmain.UNIVERSE,
		InterfaceID.BankDepositbox.UNIVERSE,
		InterfaceID.FarmingTools.UNIVERSE,
		InterfaceID.SeedVault.UNIVERSE
	};

	/** Bank, deposit box, tool leprechaun or seed vault is on screen. */
	private boolean isStorageOpen()
	{
		for (int component : STORAGE_INTERFACES)
		{
			Widget widget = client.getWidget(component);
			if (widget != null && !widget.isHidden())
			{
				return true;
			}
		}
		return false;
	}

	private boolean isTaskTarget(String npcName)
	{
		TaskRecord task = ledger.data().currentTask;
		return task != null && !task.isFinished()
			&& taskTargetNames.contains(npcName.toLowerCase(Locale.ENGLISH));
	}

	private static boolean isAttackable(NPC npc)
	{
		NPCComposition comp = npc.getTransformedComposition();
		if (comp == null || comp.getActions() == null)
		{
			return false;
		}
		for (String action : comp.getActions())
		{
			if ("Attack".equalsIgnoreCase(action))
			{
				return true;
			}
		}
		return false;
	}

	private static String npcName(NPC npc)
	{
		if (npc == null || npc.getName() == null)
		{
			return null;
		}
		String name = Text.removeTags(npc.getName()).trim();
		// Parts of a boss fight (Hespori's flowers, Zulrah's snakelings) are filed under the boss.
		return name.isEmpty() || "null".equalsIgnoreCase(name) ? null : ItemRules.bossGroup(name);
	}

	private static String npcKey(String name)
	{
		return "npc:" + name;
	}

	private int inventoryCount(int itemId)
	{
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		return inv == null ? 0 : inv.count(itemId);
	}

	private static Map<Integer, Integer> counts(ItemContainer container)
	{
		Item[] items = container.getItems();
		int[] ids = new int[items.length];
		int[] qty = new int[items.length];
		for (int i = 0; i < items.length; i++)
		{
			ids[i] = items[i].getId();
			qty[i] = items[i].getQuantity();
		}
		return InventoryDiff.counts(ids, qty);
	}

	private TileKey localTile()
	{
		Player local = client.getLocalPlayer();
		return local == null ? null : tileKey(local.getWorldLocation());
	}

	private TileKey sceneTile(int sceneX, int sceneY)
	{
		WorldView wv = client.getTopLevelWorldView();
		return tileKey(WorldPoint.fromScene(wv, sceneX, sceneY, wv.getPlane()));
	}

	private static TileKey tileKey(Tile tile)
	{
		return tile == null ? null : tileKey(tile.getWorldLocation());
	}

	private static TileKey tileKey(WorldPoint wp)
	{
		return wp == null ? null : new TileKey(wp.getX(), wp.getY(), wp.getPlane());
	}

	/** Item lookups backed by RuneLite's item manager. Must be used on the client thread. */
	private final class ClientItemInfo implements ItemInfo
	{
		@Override
		public String name(int itemId)
		{
			ItemComposition comp = itemManager.getItemComposition(itemId);
			return comp == null ? "" : comp.getName();
		}

		@Override
		public long marketPrice(int itemId)
		{
			int id = itemManager.canonicalize(itemId);
			if (id == ItemID.COINS)
			{
				return 1;
			}
			if (isZeroValue(id))
			{
				return 0;
			}
			long ge = itemManager.getItemPrice(id);
			if (ge > 0)
			{
				return ge;
			}
			// No GE price: tradeable items and tarnished items (a tarnished ring polishes into
			// a real ring) use their High Alchemy value; anything else untradeable is worth 0.
			ItemComposition item = itemManager.getItemComposition(id);
			if (item == null || !(item.isTradeable() || ItemRules.isTarnished(item.getName())))
			{
				return 0;
			}
			return Math.max(0, item.getHaPrice());
		}

		private final Map<String, Integer> idsByName = new HashMap<>();

		@Override
		public int idByName(String name)
		{
			if (name == null || name.isEmpty())
			{
				return -1;
			}
			String key = name.toLowerCase(Locale.ENGLISH);
			return idsByName.computeIfAbsent(key, k ->
			{
				for (var price : itemManager.search(k))
				{
					if (price.getName().equalsIgnoreCase(k))
					{
						return price.getId();
					}
				}
				return -1;
			});
		}

		@Override
		public boolean stackable(int itemId)
		{
			ItemComposition comp = itemManager.getItemComposition(itemId);
			return comp != null && comp.isStackable();
		}

		@Override
		public boolean tradeable(int itemId)
		{
			ItemComposition comp = itemManager.getItemComposition(itemManager.canonicalize(itemId));
			return comp != null && comp.isTradeable();
		}

		@Override
		public int canonical(int itemId)
		{
			return itemManager.canonicalize(itemId);
		}
	}
}

package com.gildedledger;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WidgetNode;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.ColorUtil;

/**
 * The small box that slides in at the top of the game screen (the one the game uses
 * for collection log entries), saying what a reminder is for.
 *
 * <p>Technique adapted from PvM Toolkit (BSD-2): open the game's notification
 * interface and run its own script to fill in the title and text.
 */
@Singleton
class ReminderPopup
{
	/** The game's script that animates the notification box with a title and text. */
	private static final int NOTIFICATION_SCRIPT = 3343;
	private static final int RESIZED_CHILD = 13;
	private static final int FIXED_CHILD = 43;
	private static final int CONTENT_CHILD = 1;

	private final Client client;
	private final ClientThread clientThread;
	private WidgetNode open;

	@Inject
	ReminderPopup(Client client, ClientThread clientThread)
	{
		this.client = client;
		this.clientThread = clientThread;
	}

	/** Shows the box. Must be called on the client thread. */
	void show(String title, String message)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		int topLevel = client.getTopLevelInterfaceId();
		if (topLevel < 0)
		{
			return;
		}
		close();
		int component = topLevel << 16 | (client.isResized() ? RESIZED_CHILD : FIXED_CHILD);
		WidgetNode node = client.openInterface(component, InterfaceID.NOTIFICATION_DISPLAY, WidgetModalMode.MODAL_CLICKTHROUGH);
		open = node;
		client.runScript(NOTIFICATION_SCRIPT, ColorUtil.wrapWithColorTag(title, ColorUtil.fromHex("ffb000")),
			ColorUtil.wrapWithColorTag(message, ColorUtil.fromHex("ffffff")), -1);
		// Close the interface once the box has finished sliding away.
		clientThread.invokeLater(() ->
		{
			Widget content = client.getWidget(InterfaceID.NOTIFICATION_DISPLAY, CONTENT_CHILD);
			if (content != null && content.getWidth() > 0)
			{
				return false;
			}
			if (open == node)
			{
				close();
			}
			return true;
		});
	}

	void close()
	{
		WidgetNode node = open;
		open = null;
		if (node == null)
		{
			return;
		}
		try
		{
			client.closeInterface(node, true);
		}
		catch (IllegalArgumentException ignored)
		{
			// Already closed by the game.
		}
	}
}

package com.gildedledger.data;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * A GP/hour session: either the one running now, or a finished one in the session log.
 * Profit only counts while the session is running, never while it's paused.
 */
public class GpSession
{
	public String id;
	public String title;
	/** The player renamed it, so the automatic title is no longer used. */
	public boolean renamed;
	public long startedMillis;
	public long endedMillis;
	/** Time spent running, not counting pauses (and not the part still running, if any). */
	public long activeMillis;
	/** When the current running stretch began; 0 while paused or finished. */
	public long runningSinceMillis;
	/** Last time the client was seen running this session (to keep its time if the client crashes). */
	public long lastSeenMillis;
	public long profit;
	public long xp;
	/** What each source did during the session: used to name it after the main activity. */
	public Map<String, Activity> activity = new LinkedHashMap<>();
	/** Each source's totals when the current running stretch began. */
	public Map<String, Activity> stretchStart = new LinkedHashMap<>();
	/** Everything picked up or made during the session, all sources together. */
	public Map<Integer, Long> loot = new LinkedHashMap<>();
	/** Everything used up during the session, all sources together, by supply line. */
	public Map<String, SupplyLine> supplies = new LinkedHashMap<>();
	/** All loot and supplies when the current running stretch began. */
	public Map<Integer, Long> stretchLoot = new LinkedHashMap<>();
	public Map<String, SupplyLine> stretchSupplies = new LinkedHashMap<>();

	public boolean isRunning()
	{
		return runningSinceMillis > 0;
	}

	/** Profit per hour of running time. */
	public static long gpPerHour(long profit, long activeMillis)
	{
		return activeMillis < 1000 ? 0 : Math.round(profit * 3_600_000.0 / activeMillis);
	}

	public long gpPerHour()
	{
		return gpPerHour(profit, activeMillis);
	}

	/** A source's count, profit and XP: a snapshot, or what changed over a session. */
	public static class Activity
	{
		public String name;
		public SourceCategory category;
		public long count;
		public long profit;
		public long xp;

		public Activity()
		{
		}

		public Activity(String name, SourceCategory category, long count, long profit, long xp)
		{
			this.name = name;
			this.category = category;
			this.count = count;
			this.profit = profit;
			this.xp = xp;
		}
	}
}

package com.gildedledger.data;

/**
 * The kind of activity a tracked source represents. The panel groups sources
 * by category, in this order. Skilling categories are named after the skill
 * that gave the most XP for the action.
 */
public enum SourceCategory
{
	COMBAT("PvM", "Kills", "Attack"),
	FARMING("Farming", "Harvests", "Farming"),
	WOODCUTTING("Woodcutting", "Logs cut", "Woodcutting"),
	FISHING("Fishing", "Catches", "Fishing"),
	MINING("Mining", "Ores mined", "Mining"),
	HUNTER("Hunter", "Catches", "Hunter"),
	THIEVING("Thieving", "Successes", "Thieving"),
	RUNECRAFTING("Runecrafting", "Crafts", "Runecraft"),
	HERBLORE("Herblore", "Made", "Herblore"),
	COOKING("Cooking", "Made", "Cooking"),
	FLETCHING("Fletching", "Made", "Fletching"),
	CRAFTING("Crafting", "Made", "Crafting"),
	SMITHING("Smithing", "Made", "Smithing"),
	FIREMAKING("Firemaking", "Burned", "Firemaking"),
	MAGIC("Magic", "Casts", "Magic"),
	PRAYER("Prayer", "Used", "Prayer"),
	CONSTRUCTION("Construction", "Built", "Construction"),
	AGILITY("Agility", "Laps", "Agility"),
	SAILING("Sailing", "Actions", "Sailing"),
	/** Older saves filed all processing here; kept so they still load. */
	PROCESSING("Processing", "Made", null),
	TELEPORTS("Teleports", "Uses", null),
	GENERAL_SUPPLIES("General supplies", "Uses", null),
	/** Minigame rewards that belong to no skill. */
	OTHER("Other", "Rewards", null),
	PURCHASE("Purchases", "Purchases", null);

	private final String label;
	private final String countLabel;
	/** RuneLite skill name for the icon and XP matching, or null. */
	private final String skillName;

	SourceCategory(String label, String countLabel, String skillName)
	{
		this.label = label;
		this.countLabel = countLabel;
		this.skillName = skillName;
	}

	public String getLabel()
	{
		return label;
	}

	public String getCountLabel()
	{
		return countLabel;
	}

	public String getSkillName()
	{
		return skillName;
	}

	/** A skilling category, the kind "Hide skilling" hides (PvM and Farming have their own settings). */
	public boolean isSkill()
	{
		return skillName != null && this != COMBAT && this != FARMING;
	}

	/** The skilling category for a skill name such as "Fletching", or null if there is none. */
	public static SourceCategory forSkill(String skillName)
	{
		if (skillName == null)
		{
			return null;
		}
		for (SourceCategory category : values())
		{
			if (category != COMBAT && skillName.equalsIgnoreCase(category.skillName))
			{
				return category;
			}
		}
		return null;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.gildedledger.data;

import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.IntToLongFunction;

/**
 * Everything tracked for one source: a monster, a farming crop, a skilling action
 * or a processing product. Loot is stored as item quantities and valued at
 * current prices; supplies are stored with the gp they cost when used.
 */
public class SourceRecord
{
	public String key;
	public String name;
	public SourceCategory category;
	/** Kills, harvests, logs cut and so on, depending on the category. */
	public long count;
	public Map<Integer, Long> loot = new LinkedHashMap<>();
	public Map<String, SupplyLine> supplies = new LinkedHashMap<>();
	public Map<String, Long> xp = new LinkedHashMap<>();
	/** Loot items the player chose not to count towards profit (right-click, Exclude). */
	public Set<Integer> excludedLoot = new LinkedHashSet<>();
	/** Supply lines (by key) the player chose not to count towards profit. */
	public Set<String> excludedSupplies = new LinkedHashSet<>();
	public long firstSeenMillis;
	public long lastUpdatedMillis;

	public SourceRecord()
	{
	}

	public SourceRecord(String key, String name, SourceCategory category, long nowMillis)
	{
		this.key = key;
		this.name = name;
		this.category = category;
		this.firstSeenMillis = nowMillis;
		this.lastUpdatedMillis = nowMillis;
	}

	public void addLoot(int itemId, long quantity, long nowMillis)
	{
		if (itemId <= 0 || quantity <= 0)
		{
			return;
		}
		loot.merge(itemId, quantity, Long::sum);
		lastUpdatedMillis = nowMillis;
	}

	/** Takes up to {@code quantity} of an item back out of the loot. Returns how many were removed. */
	public long removeLoot(int itemId, long quantity, long nowMillis)
	{
		Long have = loot.get(itemId);
		if (have == null || quantity <= 0)
		{
			return 0;
		}
		long removed = Math.min(have, quantity);
		if (have - removed <= 0)
		{
			loot.remove(itemId);
		}
		else
		{
			loot.put(itemId, have - removed);
		}
		lastUpdatedMillis = nowMillis;
		return removed;
	}

	public void addSupply(String lineKey, int itemId, String lineName, String unit, long quantity, long gp, long nowMillis)
	{
		if (quantity <= 0 || gp < 0)
		{
			return;
		}
		SupplyLine line = supplies.computeIfAbsent(lineKey, k -> new SupplyLine(itemId, lineName, unit));
		line.quantity += quantity;
		line.gp += gp;
		lastUpdatedMillis = nowMillis;
	}

	/** Takes back part of a supply line. Returns false if there isn't that much on it. */
	public boolean removeSupply(String lineKey, long quantity, long gp)
	{
		SupplyLine line = supplies.get(lineKey);
		if (line == null || line.quantity < quantity)
		{
			return false;
		}
		line.quantity -= quantity;
		line.gp = Math.max(0, line.gp - gp);
		if (line.quantity <= 0)
		{
			supplies.remove(lineKey);
			excludedSupplies.remove(lineKey);
		}
		return true;
	}

	/** Takes back some XP. Returns false if there isn't that much. */
	public boolean removeXp(String skill, long amount)
	{
		Long have = xp.get(skill);
		if (have == null || have < amount)
		{
			return false;
		}
		if (have == amount)
		{
			xp.remove(skill);
		}
		else
		{
			xp.put(skill, have - amount);
		}
		return true;
	}

	public void addXp(String skill, long amount, long nowMillis)
	{
		if (amount <= 0)
		{
			return;
		}
		xp.merge(skill, amount, Long::sum);
		lastUpdatedMillis = nowMillis;
	}

	public void incrementCount(long nowMillis)
	{
		count++;
		lastUpdatedMillis = nowMillis;
	}

	/** Folds another record for the same source into this one. */
	public void mergeFrom(SourceRecord other)
	{
		count += other.count;
		other.loot.forEach((id, qty) -> loot.merge(id, qty, Long::sum));
		other.xp.forEach((skill, amount) -> xp.merge(skill, amount, Long::sum));
		other.supplies.forEach((key, line) ->
		{
			SupplyLine mine = supplies.get(key);
			if (mine == null)
			{
				supplies.put(key, line);
			}
			else
			{
				mine.quantity += line.quantity;
				mine.gp += line.gp;
			}
		});
		excludedLoot.addAll(other.excludedLoot);
		excludedSupplies.addAll(other.excludedSupplies);
		firstSeenMillis = Math.min(firstSeenMillis, other.firstSeenMillis);
		lastUpdatedMillis = Math.max(lastUpdatedMillis, other.lastUpdatedMillis);
	}

	public long lootValue(IntToLongFunction unitPrice)
	{
		long total = 0;
		for (Map.Entry<Integer, Long> entry : loot.entrySet())
		{
			if (!excludedLoot.contains(entry.getKey()))
			{
				total += unitPrice.applyAsLong(entry.getKey()) * entry.getValue();
			}
		}
		return total;
	}

	public long supplyCost()
	{
		long total = 0;
		for (Map.Entry<String, SupplyLine> entry : supplies.entrySet())
		{
			if (!excludedSupplies.contains(entry.getKey()))
			{
				total += entry.getValue().gp;
			}
		}
		return total;
	}

	/** Right-click "Exclude from profit" / "Include in profit" on a loot item. */
	public void toggleLootExcluded(int itemId)
	{
		if (!excludedLoot.remove(itemId))
		{
			excludedLoot.add(itemId);
		}
	}

	/** Right-click "Exclude from profit" / "Include in profit" on a supply. */
	public void toggleSupplyExcluded(String lineKey)
	{
		if (!excludedSupplies.remove(lineKey))
		{
			excludedSupplies.add(lineKey);
		}
	}

	public long totalXp()
	{
		long total = 0;
		for (long amount : xp.values())
		{
			total += amount;
		}
		return total;
	}

	public boolean isEmpty()
	{
		return count == 0 && loot.isEmpty() && supplies.isEmpty() && xp.isEmpty();
	}
}

package com.gildedledger.data;

/**
 * One kind of supply used by a source. Supplies are valued at the moment they
 * are used, so the stored gp never changes afterwards even if prices move.
 */
public class SupplyLine
{
	/** Item shown as the icon, e.g. the potion that was sipped. */
	public int itemId;
	/** Display name with doses stripped, e.g. "Prayer potion". */
	public String name;
	public long quantity;
	public long gp;
	/** Unit for the quantity, e.g. "doses"; null for plain items. */
	public String unit;

	public SupplyLine()
	{
	}

	public SupplyLine(int itemId, String name, String unit)
	{
		this.itemId = itemId;
		this.name = name;
		this.unit = unit;
	}
}

package com.gildedledger.data;

/**
 * Running totals for one Slayer task. Values are captured in gp at the time
 * each event happened, so a finished task keeps the numbers it ended with.
 */
public class TaskRecord
{
	public String taskName;
	public String location;
	public int initialAmount;
	public int remainingAmount;
	public long startedMillis;
	public long finishedMillis;
	public long kills;
	public long lootGp;
	public long supplyGp;
	public long xp;
	public long slayerXp;

	public TaskRecord()
	{
	}

	public TaskRecord(String taskName, String location, int initialAmount, int remainingAmount, long nowMillis)
	{
		this.taskName = taskName;
		this.location = location;
		this.initialAmount = initialAmount;
		this.remainingAmount = remainingAmount;
		this.startedMillis = nowMillis;
	}

	public long profit()
	{
		return lootGp - supplyGp;
	}

	public boolean isFinished()
	{
		return finishedMillis > 0;
	}

	public boolean hasActivity()
	{
		return kills > 0 || lootGp > 0 || supplyGp > 0 || xp > 0 || slayerXp > 0;
	}
}

package com.gildedledger.data;

import com.gildedledger.tracking.FarmingTracker;
import com.gildedledger.tracking.ItemRules;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Everything saved for one RuneScape account. Serialized to JSON and stored in
 * the account's RuneLite profile, so each character keeps its own ledger.
 */
public class TrackerData
{
	public static final int MAX_TASK_HISTORY = 25;
	public static final String GENERAL_SUPPLIES_KEY = "supplies:general";
	public static final String GENERAL_SUPPLIES_NAME = "General supplies";
	public static final String TELEPORTS_KEY = "teleport:all";
	public static final String TELEPORTS_NAME = "Teleports";

	public int version = 1;
	public Map<String, SourceRecord> sources = new LinkedHashMap<>();
	public TaskRecord currentTask;
	public List<TaskRecord> taskHistory = new ArrayList<>();
	/** The dart last seen loaded in the blowpipe (from a "Check" or a shot); 0 if unknown. */
	public int blowpipeDart;
	/** Which crop was last planted in each farming patch, keyed by packed patch location. */
	public Map<String, String> patchCrops = new LinkedHashMap<>();
	/** Crops grown from untradeable seeds (quest plants like goutweed), hidden by a setting. */
	public java.util.Set<String> untradeableCrops = new java.util.HashSet<>();
	/** The GP/hour session in progress (running or paused), or null. */
	public GpSession activeSession;
	/** Finished GP/hour sessions, newest first. */
	public List<GpSession> sessionLog = new ArrayList<>();

	public SourceRecord source(String key, String name, SourceCategory category, long nowMillis)
	{
		SourceRecord record = sources.get(key);
		if (record == null)
		{
			record = new SourceRecord(key, name, category, nowMillis);
			sources.put(key, record);
		}
		return record;
	}

	public void archiveCurrentTask(long nowMillis)
	{
		if (currentTask == null)
		{
			return;
		}
		if (!currentTask.isFinished())
		{
			currentTask.finishedMillis = nowMillis;
		}
		if (currentTask.hasActivity())
		{
			taskHistory.add(0, currentTask);
			while (taskHistory.size() > MAX_TASK_HISTORY)
			{
				taskHistory.remove(taskHistory.size() - 1);
			}
		}
		currentTask = null;
	}

	/**
	 * Earlier versions kept unassigned supplies under PvM and filed all processing
	 * as "Processing: Skill: Product". Move those into the current categories.
	 */
	private void migrateOldCategories()
	{
		Map<String, SourceRecord> migrated = new LinkedHashMap<>();
		for (SourceRecord record : sources.values())
		{
			if (record.category == SourceCategory.FARMING)
			{
				migrateFarming(record);
			}
			if ("supplies:unassigned".equals(record.key)
				|| record.category == SourceCategory.GENERAL_SUPPLIES
				|| (record.category == SourceCategory.COMBAT && record.key.startsWith("supplies:")))
			{
				// General supplies are one table, not one entry per item.
				record.category = SourceCategory.GENERAL_SUPPLIES;
				record.key = GENERAL_SUPPLIES_KEY;
				record.name = GENERAL_SUPPLIES_NAME;
			}
			else if (record.category == SourceCategory.PURCHASE || "process:PROCESSING:Battlestaff".equals(record.key)
				|| "item:PROCESSING:Battlestaff".equals(record.key))
			{
				// Buying from NPCs (Zaff's battlestaves) is no longer tracked at all.
				continue;
			}
			else if (record.category == SourceCategory.TELEPORTS)
			{
				// Teleports are one table, not one entry per teleport.
				record.key = TELEPORTS_KEY;
				record.name = TELEPORTS_NAME;
			}
			else if (record.category == SourceCategory.PROCESSING && !record.xp.isEmpty())
			{
				// Something filed as Processing that did give XP (lighting a log before the XP
				// arrived, in older versions): move it to that skill.
				SourceCategory skill = SourceCategory.forSkill(topSkill(record));
				if (skill != null)
				{
					String product = record.key.startsWith("process:PROCESSING:")
						? record.key.substring("process:PROCESSING:".length()) : record.name;
					record.category = skill;
					record.name = product;
					record.key = "process:" + skill.name() + ":" + product;
				}
			}
			else if (record.category == SourceCategory.PROCESSING && record.key.startsWith("process:"))
			{
				String[] parts = record.key.split(":", 3);
				SourceCategory skill = parts.length == 3 ? SourceCategory.forSkill(parts[1]) : null;
				if (skill != null)
				{
					record.category = skill;
					record.name = parts[2];
					record.key = "process:" + skill.name() + ":" + parts[2];
				}
			}
			// Skills are now split by item ("item:...") or, for Thieving, by NPC ("target:...").
			if (record.key.startsWith("process:"))
			{
				record.key = "item:" + record.key.substring("process:".length());
			}
			else if (record.key.startsWith("gather:THIEVING:"))
			{
				record.key = "target:" + record.key.substring("gather:".length());
			}
			SourceRecord existing = migrated.get(record.key);
			if (existing == null)
			{
				migrated.put(record.key, record);
			}
			else
			{
				existing.mergeFrom(record);
			}
		}
		sources = migrated;
	}

	/**
	 * Farming is filed by crop now ("Toadflax", "Yew tree"). Older saves used
	 * "farming:Herb:Toadflax", and some farming was misfiled by item
	 * ("item:FARMING:Toadflax seed", "item:FARMING:Grimy toadflax").
	 */
	private static void migrateFarming(SourceRecord record)
	{
		String key = record.key;
		String crop = null;
		if (key.startsWith("farming:") && key.split(":", -1).length == 3)
		{
			String[] parts = key.split(":", 3);
			String name = FarmingTracker.cropName(parts[1], "Unknown".equals(parts[2]) ? null : parts[2]);
			record.key = "farming:" + name;
			record.name = name;
			return;
		}
		if (key.startsWith("item:FARMING:"))
		{
			String item = key.substring("item:FARMING:".length());
			String lower = item.toLowerCase(java.util.Locale.ENGLISH);
			if (lower.startsWith("grimy "))
			{
				crop = ItemRules.capitalize(item.substring("grimy ".length()));
			}
			else if (ItemRules.isPlantable(item))
			{
				crop = ItemRules.cropFromPlantable(item);
				if (lower.endsWith("sapling") || lower.endsWith("acorn"))
				{
					crop = crop + " tree";
				}
			}
			String name = crop != null ? crop : "Unsorted farming";
			record.key = "farming:" + name;
			record.name = name;
		}
	}

	private static String topSkill(SourceRecord record)
	{
		String best = null;
		long bestXp = 0;
		for (Map.Entry<String, Long> entry : record.xp.entrySet())
		{
			if (entry.getValue() != null && entry.getValue() > bestXp)
			{
				best = entry.getKey();
				bestXp = entry.getValue();
			}
		}
		return best;
	}

	/** Gson leaves fields null when an older save lacks them; repair that after loading. */
	public TrackerData normalize()
	{
		if (sources == null)
		{
			sources = new LinkedHashMap<>();
		}
		if (taskHistory == null)
		{
			taskHistory = new ArrayList<>();
		}
		if (patchCrops == null)
		{
			patchCrops = new LinkedHashMap<>();
		}
		sources.values().removeIf(r -> r == null || r.key == null || r.category == null);
		for (SourceRecord record : sources.values())
		{
			if (record.loot == null)
			{
				record.loot = new LinkedHashMap<>();
			}
			if (record.supplies == null)
			{
				record.supplies = new LinkedHashMap<>();
			}
			if (record.xp == null)
			{
				record.xp = new LinkedHashMap<>();
			}
			if (record.excludedLoot == null)
			{
				record.excludedLoot = new java.util.LinkedHashSet<>();
			}
			if (record.excludedSupplies == null)
			{
				record.excludedSupplies = new java.util.LinkedHashSet<>();
			}
		}
		migrateOldCategories();
		return this;
	}
}

package com.gildedledger.tracking;

import java.util.HashMap;
import java.util.Map;

/**
 * Recognizes items the player drops from their inventory, so the trackers can
 * take them back out of the loot instead of treating them as used up.
 */
public class DropTracker
{
	static final int DROP_WINDOW_TICKS = 3;

	private final Map<Integer, Integer> lastDropClick = new HashMap<>();

	public void onDropClicked(int itemId, int tick)
	{
		if (itemId > 0)
		{
			lastDropClick.put(itemId, tick);
		}
	}

	/**
	 * Returns the decreases in this change that are drops, as negative amounts
	 * keyed by item id, ready for {@link InventoryDiff#without}.
	 */
	public Map<Integer, Integer> dropsIn(InventoryDiff diff, int tick)
	{
		Map<Integer, Integer> drops = new HashMap<>();
		lastDropClick.values().removeIf(clickTick -> tick - clickTick > DROP_WINDOW_TICKS);
		for (Map.Entry<Integer, Integer> change : diff.changes().entrySet())
		{
			if (change.getValue() < 0 && lastDropClick.containsKey(change.getKey()))
			{
				drops.put(change.getKey(), change.getValue());
			}
		}
		return drops;
	}

	public void reset()
	{
		lastDropClick.clear();
	}
}

package com.gildedledger.tracking;

import com.gildedledger.data.SourceCategory;
import com.gildedledger.data.SourceRecord;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Tracks every farming patch the same way, filed by crop: all Toadflax together,
 * all Yew trees together, whichever patch they grew in.
 *
 * <p>A session opens for a patch when the player clicks it, uses an item on it,
 * or the game sends a farming message ("You plant a toadflax seed in the herb
 * patch.", "You treat the herb patch with ultracompost."). The messages make the
 * tracker work even when the patch object itself isn't recognised. While the
 * session lasts:
 * <ul>
 *   <li>Items gained are loot (herbs, fruit, logs from chopping a patch tree...).
 *       If the crop isn't known yet, it's worked out from the harvest
 *       ("Grimy huasca" → Huasca, "Yew logs" → Yew tree).</li>
 *   <li>Seeds, saplings and compost are charged the moment they're used. Compost
 *       goes on the crop in the patch; if a different seed is then planted on the
 *       same visit, that compost moves to the new crop.</li>
 *   <li>Paying a gardener to protect the patch is charged to that crop too.</li>
 * </ul>
 *
 * Clicking anything other than the patch (a leprechaun, a bank, an NPC) pauses
 * the session, so noting herbs or banking never looks like a harvest.
 */
public class FarmingTracker
{
	static final int MAX_DISTANCE = 12;
	static final int IDLE_TICKS = 100;
	static final int PAYMENT_WINDOW_TICKS = 500;
	static final int PAYMENT_DISTANCE = 20;

	/** "You plant a toadflax seed in the herb patch." / "You plant 3 potato seeds in the allotment." */
	private static final Pattern PLANT_MESSAGE = Pattern.compile(
		"^You plant (?:a |an |the |\\d+ )?(.+?) in the (.+?)\\.?$", Pattern.CASE_INSENSITIVE);
	/** "You treat the herb patch with ultracompost." */
	private static final Pattern TREAT_MESSAGE = Pattern.compile(
		"^You treat the (.+?) with (compost|supercompost|ultracompost)\\.?$", Pattern.CASE_INSENSITIVE);
	/** "You begin to harvest the herb patch." */
	private static final Pattern HARVEST_MESSAGE = Pattern.compile(
		"^You begin to harvest the (.+?)\\.?$", Pattern.CASE_INSENSITIVE);
	/** "You examine the tree for signs of disease and find that it is in perfect health." */
	private static final Pattern CHECK_HEALTH_MESSAGE = Pattern.compile(
		"^You examine the (.+?) for signs of disease.*$", Pattern.CASE_INSENSITIVE);

	private final Ledger ledger;
	private final ItemInfo items;
	private final Map<String, Integer> compostItemIds;

	private Session session;
	private Session lastSession;
	private int lastSessionEndTick;

	private final Map<Integer, Integer> tickChanges = new HashMap<>();
	private final Map<String, Long> tickXp = new HashMap<>();
	private final List<String> tickCompostMessages = new ArrayList<>();
	private String tickPlantedCrop;

	/** Compost already charged on this visit, so it can follow a newly planted crop. */
	private static final class BookedCompost
	{
		final String sourceKey;
		final int itemId;
		final long quantity;
		final long gp;
		final Map<String, Long> xp = new HashMap<>();

		BookedCompost(String sourceKey, int itemId, long quantity, long gp)
		{
			this.sourceKey = sourceKey;
			this.itemId = itemId;
			this.quantity = quantity;
			this.gp = gp;
		}
	}

	private static final class Session
	{
		final TileKey patch;
		String category;
		String crop;
		boolean armed = true;
		int lastActivityTick;
		final List<BookedCompost> compostThisVisit = new ArrayList<>();
		final Set<String> countedSources = new HashSet<>();

		Session(TileKey patch, String category, String crop, int tick)
		{
			this.patch = patch;
			this.category = category;
			this.crop = crop;
			this.lastActivityTick = tick;
		}
	}

	public FarmingTracker(Ledger ledger, ItemInfo items, Map<String, Integer> compostItemIds)
	{
		this.ledger = ledger;
		this.items = items;
		this.compostItemIds = compostItemIds;
	}

	/**
	 * The player clicked a farming patch or used an item on one.
	 *
	 * @param category       e.g. "Herb", "Tree", "Fruit tree"
	 * @param appearanceCrop crop guessed from the patch's current look; may be null
	 */
	public void onPatchClicked(TileKey patch, String category, String appearanceCrop, int tick)
	{
		if (session != null && session.patch != null && session.patch.equals(patch))
		{
			session.armed = true;
			session.lastActivityTick = tick;
			if (session.crop == null && appearanceCrop != null)
			{
				session.crop = appearanceCrop;
			}
			return;
		}
		closeSession(tick);
		String remembered = ledger.data().patchCrops.get(patchMemoryKey(patch, category));
		session = new Session(patch, category, remembered != null ? remembered : appearanceCrop, tick);
	}

	/** The player clicked something that isn't the patch; stop booking changes until they return. */
	public void onOtherAction()
	{
		if (session != null)
		{
			session.armed = false;
		}
	}

	/** True while a patch is being worked; the skilling tracker stays out of the way then. */
	public boolean isArmed()
	{
		return session != null && session.armed;
	}

	public void onInventoryChanged(InventoryDiff diff)
	{
		if (session == null || !session.armed)
		{
			return;
		}
		diff.changes().forEach((id, delta) -> tickChanges.merge(id, delta, Integer::sum));
	}

	public void onXp(String skill, long amount)
	{
		if (session != null && session.armed && amount > 0
			&& ("Farming".equals(skill) || "Woodcutting".equals(skill)))
		{
			tickXp.merge(skill, amount, Long::sum);
		}
	}

	/**
	 * A game message. Farming messages open (or re-arm) a session on their own, so
	 * planting and composting are tracked even if the patch click wasn't recognised.
	 */
	public void onChatMessage(String message, TileKey playerTile, int tick)
	{
		if (message == null)
		{
			return;
		}
		String text = message.trim();

		Matcher plant = PLANT_MESSAGE.matcher(text);
		if (plant.matches())
		{
			ensureSession(ItemRules.patchCategory(plant.group(2)), playerTile, tick);
			tickPlantedCrop = cropFromPlanted(plant.group(1));
			return;
		}
		Matcher treat = TREAT_MESSAGE.matcher(text);
		if (treat.matches())
		{
			ensureSession(ItemRules.patchCategory(treat.group(1)), playerTile, tick);
			tickCompostMessages.add(ItemRules.capitalize(treat.group(2).toLowerCase(Locale.ENGLISH)));
			return;
		}
		Matcher harvest = HARVEST_MESSAGE.matcher(text);
		if (harvest.matches())
		{
			ensureSession(ItemRules.patchCategory(harvest.group(1)), playerTile, tick);
			return;
		}
		Matcher check = CHECK_HEALTH_MESSAGE.matcher(text);
		if (check.matches() && session != null)
		{
			session.armed = true;
			session.lastActivityTick = tick;
		}
	}

	/**
	 * Something left the inventory after the player chose to pay a gardener.
	 * Charged to the patch most recently worked, if it was recent and nearby.
	 */
	public void onGardenerPayment(InventoryDiff diff, int tick, TileKey playerTile)
	{
		Session target = session != null ? session : lastSession;
		if (target == null || target.crop == null)
		{
			return;
		}
		if (session == null && tick - lastSessionEndTick > PAYMENT_WINDOW_TICKS)
		{
			return;
		}
		TileKey where = target.patch;
		if (where != null && playerTile != null && where.distanceTo(playerTile) > PAYMENT_DISTANCE)
		{
			return;
		}
		diff.changes().forEach((id, delta) ->
		{
			if (delta < 0)
			{
				bookCost(target, id, -delta, items.marketPrice(id) * -delta);
			}
		});
	}

	/** Called once per game tick: books this tick's changes and closes stale sessions. */
	public void onGameTick(int tick, TileKey playerTile)
	{
		if (session != null)
		{
			resolveTick(tick);
			boolean walkedAway = playerTile != null && session.patch != null
				&& session.patch.distanceTo(playerTile) > MAX_DISTANCE;
			if (walkedAway || tick - session.lastActivityTick > IDLE_TICKS)
			{
				closeSession(tick);
			}
		}
		tickChanges.clear();
		tickXp.clear();
		tickCompostMessages.clear();
		tickPlantedCrop = null;
	}

	/** Logging out or hopping: forget the session (everything is already charged). */
	public void reset()
	{
		session = null;
		lastSession = null;
		tickChanges.clear();
		tickXp.clear();
		tickCompostMessages.clear();
		tickPlantedCrop = null;
	}

	boolean hasSession()
	{
		return session != null;
	}

	/** Patches are remembered per region and patch type: one herb patch, one tree patch... */
	public static String patchMemoryKey(TileKey tile, String category)
	{
		if (tile == null)
		{
			return "unknown:" + category;
		}
		return (tile.x >> 6) + "," + (tile.y >> 6) + "," + tile.plane + ":" + category;
	}

	/**
	 * The name a crop is filed under: "Toadflax", "Yew tree", "Apple tree". Trees get
	 * "tree" added so a Yew sapling and a grown Yew tree land on the same entry.
	 */
	public static String cropName(String category, String crop)
	{
		if (crop == null)
		{
			return category == null || "Farming".equals(category)
				? "Unknown crop" : category + " patch (unknown crop)";
		}
		String name = canonicalCrop(crop);
		// The Farming Guild's anima plants don't get their own entries.
		return ANIMA_PLANTS.contains(name.toLowerCase(Locale.ENGLISH)) ? "Other" : name;
	}

	private static final Set<String> ANIMA_PLANTS = Set.of("attas", "kronos", "iasor");

	/** Crops that grow as trees, so "Yew", "Yew sapling" and "Yew tree" all become "Yew tree". */
	private static final Set<String> TREE_CROPS = Set.of(
		"oak", "willow", "maple", "yew", "magic", "teak", "mahogany", "camphor", "ironwood", "rosewood",
		"apple", "banana", "orange", "curry", "pineapple", "papaya", "palm", "dragonfruit",
		"calquat", "celastrus", "redwood", "spirit", "crystal");

	/**
	 * One name per crop whichever way it was seen: "Papaya", "Papaya tree" and a papaya
	 * sapling are all "Papaya tree"; "Ranarr" stays "Ranarr".
	 */
	public static String canonicalCrop(String crop)
	{
		if (crop == null)
		{
			return null;
		}
		String base = crop.trim();
		String lower = base.toLowerCase(Locale.ENGLISH);
		if (lower.endsWith(" tree"))
		{
			base = base.substring(0, base.length() - " tree".length()).trim();
			lower = base.toLowerCase(Locale.ENGLISH);
		}
		base = ItemRules.capitalize(lower);
		return TREE_CROPS.contains(lower) ? base + " tree" : base;
	}

	public static String sourceKey(String category, String crop)
	{
		return "farming:" + cropName(category, crop);
	}

	// ---------------------------------------------------------------- internals

	/** Opens a session from a farming message when no matching one is running. */
	private void ensureSession(String category, TileKey playerTile, int tick)
	{
		boolean near = session != null && (session.patch == null || playerTile == null
			|| session.patch.distanceTo(playerTile) <= MAX_DISTANCE);
		if (session != null && near)
		{
			session.armed = true;
			session.lastActivityTick = tick;
			if ("Farming".equals(session.category) && category != null && !"Farming".equals(category))
			{
				session.category = category;
			}
			return;
		}
		closeSession(tick);
		String remembered = ledger.data().patchCrops.get(patchMemoryKey(playerTile, category));
		session = new Session(playerTile, category, remembered, tick);
	}

	/** "toadflax seed" → "Toadflax"; "yew sapling" → "Yew tree". */
	private static String cropFromPlanted(String planted)
	{
		if (planted == null)
		{
			return null;
		}
		String crop = ItemRules.cropFromPlantable(planted.trim());
		return canonicalCrop(crop);
	}

	private void resolveTick(int tick)
	{
		Session s = session;
		boolean active = !tickChanges.isEmpty() || !tickXp.isEmpty() || !tickCompostMessages.isEmpty()
			|| tickPlantedCrop != null;
		if (active)
		{
			s.lastActivityTick = tick;
		}

		// Gains first, credited to whatever was growing before any replant this tick.
		boolean harvestGained = false;
		for (Map.Entry<Integer, Integer> change : tickChanges.entrySet())
		{
			int id = change.getKey();
			int delta = change.getValue();
			String name = items.name(id);
			if (delta > 0 && !ItemRules.isFarmingTool(name) && !ItemRules.isPlantable(name))
			{
				// The harvest tells us the crop when we didn't know it (or remembered it wrong).
				String harvested = cropFromHarvest(name, s.category);
				if (harvested != null && (s.crop == null || name.toLowerCase(Locale.ENGLISH).startsWith("grimy ")))
				{
					setCrop(s, harvested);
					if (!items.tradeable(id))
					{
						markUntradeable(s.crop);
					}
				}
				ledger.addLoot(sourceKey(s), sourceName(s), SourceCategory.FARMING, id, delta);
				countOnce(s);
				harvestGained = true;
			}
		}

		// Then planting, which changes the crop for the rest of the tick.
		boolean planted = false;
		for (Map.Entry<Integer, Integer> change : tickChanges.entrySet())
		{
			int id = change.getKey();
			int delta = change.getValue();
			String name = items.name(id);
			if (delta < 0 && ItemRules.isPlantable(name))
			{
				setCrop(s, cropFromPlanted(name));
				if (!items.tradeable(id))
				{
					// Quest plants (goutweed) and the like: hidden when the setting says so.
					markUntradeable(s.crop);
				}
				bookCost(s, id, -delta, items.marketPrice(id) * -delta);
				planted = true;
			}
		}
		if (!planted && tickPlantedCrop != null)
		{
			// Planted from somewhere we can't see (a seed box): the crop still changes.
			setCrop(s, tickPlantedCrop);
			planted = true;
		}
		if (planted)
		{
			moveCompostToCrop(s);
		}

		// Compost, charged straight away to the crop in the patch.
		boolean compostItemUsed = false;
		for (Map.Entry<Integer, Integer> change : tickChanges.entrySet())
		{
			int id = change.getKey();
			int delta = change.getValue();
			if (delta < 0 && ItemRules.isCompost(items.name(id)))
			{
				compostItemUsed = true;
				bookCompost(s, id, -delta, items.marketPrice(id) * -delta);
			}
		}
		// Compost from a bottomless bucket: the message arrives but no compost item leaves.
		if (!compostItemUsed)
		{
			for (String compost : tickCompostMessages)
			{
				Integer id = compostItemIds.get(compost);
				if (id != null)
				{
					bookCompost(s, id, 1, items.marketPrice(id));
				}
			}
		}

		// Picking a herb gives Farming XP; with an open herb sack the herb never reaches the
		// inventory, so the XP alone says one more of the patch's herb was picked.
		boolean compostThisTick = compostItemUsed || !tickCompostMessages.isEmpty();
		if (!harvestGained && !planted && !compostThisTick && tickXp.getOrDefault("Farming", 0L) > 0
			&& s.crop != null && s.category != null && s.category.toLowerCase(Locale.ENGLISH).contains("herb"))
		{
			int herb = grimyHerb(s.crop);
			if (herb > 0)
			{
				ledger.addLoot(sourceKey(s), sourceName(s), SourceCategory.FARMING, herb, 1);
				countOnce(s);
			}
		}

		boolean compostOnlyTick = (compostItemUsed || !tickCompostMessages.isEmpty()) && !planted;
		for (Map.Entry<String, Long> xp : tickXp.entrySet())
		{
			ledger.addXp(sourceKey(s), sourceName(s), SourceCategory.FARMING, xp.getKey(), xp.getValue());
			if (compostOnlyTick && !s.compostThisVisit.isEmpty())
			{
				// The XP for composting moves with the compost if a new seed goes in.
				s.compostThisVisit.get(s.compostThisVisit.size() - 1).xp.merge(xp.getKey(), xp.getValue(), Long::sum);
			}
			if ("Woodcutting".equals(xp.getKey()) || isCheckHealthOrHarvest())
			{
				countOnce(s);
			}
		}
	}

	/**
	 * Remembers a crop grown from an untradeable seed (or giving an untradeable harvest),
	 * so "Hide untradeable plants" can hide it.
	 */
	private void markUntradeable(String crop)
	{
		if (crop != null && !HESPORI.equals(crop))
		{
			ledger.data().untradeableCrops.add(crop);
		}
	}


	/** Hespori is a boss: its seed is a PvM supply, though its Farming XP stays in Farming. */
	public static final String HESPORI = "Hespori";


	private void setCrop(Session s, String crop)
	{
		crop = canonicalCrop(crop);
		if (crop == null)
		{
			return;
		}
		String unknownKey = s.crop == null ? sourceKey(s) : null;
		s.crop = crop;
		ledger.data().patchCrops.put(patchMemoryKey(s.patch, s.category), crop);
		if (unknownKey != null)
		{
			// Everything booked while the crop was unknown (compost, its XP) belongs to it.
			ledger.mergeInto(unknownKey, sourceKey(s), sourceName(s));
			s.compostThisVisit.removeIf(c -> c.sourceKey.equals(unknownKey));
		}
	}

	/** Planting XP comes with a seed or compost leaving; only XP with nothing used up is a harvest. */
	private boolean isCheckHealthOrHarvest()
	{
		if (tickPlantedCrop != null || !tickCompostMessages.isEmpty())
		{
			return false;
		}
		for (int delta : tickChanges.values())
		{
			if (delta < 0)
			{
				return false;
			}
		}
		return true;
	}

	private void countOnce(Session s)
	{
		String key = sourceKey(s);
		if (s.countedSources.add(key))
		{
			ledger.incrementCount(key, sourceName(s), SourceCategory.FARMING);
		}
	}

	private void bookCost(Session s, int itemId, long quantity, long gp)
	{
		String name = items.name(itemId);
		if ("hespori seed".equalsIgnoreCase(name))
		{
			// Planting Hespori is the start of a boss fight: the seed is the fight's cost.
			ledger.addSupply("npc:" + HESPORI, HESPORI, SourceCategory.COMBAT,
				String.valueOf(itemId), itemId, name, null, quantity, gp);
			return;
		}
		ledger.addSupply(sourceKey(s), sourceName(s), SourceCategory.FARMING,
			String.valueOf(itemId), itemId, name, null, quantity, gp);
	}

	/**
	 * Farming entries saved before the crop was known ("Herb patch (unknown crop)")
	 * are merged into the crop their harvest shows, e.g. grimy huasca → Huasca.
	 */
	public void tidyUnknownCrops()
	{
		normaliseCropNames();
		List<SourceRecord> unknown = new ArrayList<>();
		for (SourceRecord record : ledger.data().sources.values())
		{
			if (record.category == SourceCategory.FARMING && record.name != null
				&& (record.name.endsWith("(unknown crop)") || record.name.equals("Unknown crop")))
			{
				unknown.add(record);
			}
		}
		boolean changed = false;
		for (SourceRecord record : unknown)
		{
			String category = record.name.endsWith(" patch (unknown crop)")
				? record.name.substring(0, record.name.length() - " patch (unknown crop)".length()) : "Farming";
			String crop = null;
			long best = -1;
			for (Map.Entry<Integer, Long> loot : record.loot.entrySet())
			{
				String harvested = cropFromHarvest(items.name(loot.getKey()), category);
				if (harvested != null && loot.getValue() > best)
				{
					crop = harvested;
					best = loot.getValue();
				}
			}
			if (crop == null)
			{
				continue;
			}
			String name = cropName(category, crop);
			String key = "farming:" + name;
			ledger.data().sources.remove(record.key);
			SourceRecord target = ledger.data().sources.get(key);
			if (target == null)
			{
				record.key = key;
				record.name = name;
				ledger.data().sources.put(key, record);
			}
			else
			{
				target.mergeFrom(record);
			}
			changed = true;
		}
		if (changed)
		{
			ledger.changed();
		}
	}

	/** The grimy herb a herb crop gives: "Ranarr" → Grimy ranarr weed, "Guam" → Grimy guam leaf. */
	private int grimyHerb(String crop)
	{
		String base = "Grimy " + crop.toLowerCase(Locale.ENGLISH);
		for (String name : new String[]{base, base + " weed", base + " leaf"})
		{
			int id = items.idByName(name);
			if (id > 0)
			{
				return id;
			}
		}
		return -1;
	}

	/** "Papaya" and "Papaya tree", "Yew" and "Yew tree": one entry per crop. */
	private void normaliseCropNames()
	{
		List<SourceRecord> farming = new ArrayList<>();
		for (SourceRecord record : ledger.data().sources.values())
		{
			if (record.category == SourceCategory.FARMING && record.name != null
				&& !record.name.endsWith("(unknown crop)") && !record.name.equals("Unknown crop")
				&& record.key.startsWith("farming:"))
			{
				farming.add(record);
			}
		}
		for (SourceRecord record : farming)
		{
			String name = cropName(null, record.name);
			String key = "farming:" + name;
			if (key.equals(record.key))
			{
				continue;
			}
			ledger.mergeInto(record.key, key, name);
		}
	}

	private void bookCompost(Session s, int itemId, long quantity, long gp)
	{
		bookCost(s, itemId, quantity, gp);
		s.compostThisVisit.add(new BookedCompost(sourceKey(s), itemId, quantity, gp));
	}

	/** A seed was planted after composting: the compost belongs to the new crop. */
	private void moveCompostToCrop(Session s)
	{
		String key = sourceKey(s);
		for (BookedCompost compost : s.compostThisVisit)
		{
			if (!compost.sourceKey.equals(key))
			{
				ledger.moveSupply(compost.sourceKey, key, sourceName(s), SourceCategory.FARMING,
					String.valueOf(compost.itemId), compost.itemId, items.name(compost.itemId),
					compost.quantity, compost.gp);
				compost.xp.forEach((skill, amount) ->
					ledger.moveXp(compost.sourceKey, key, sourceName(s), SourceCategory.FARMING, skill, amount));
			}
		}
		s.compostThisVisit.clear();
	}

	/**
	 * The crop a harvested item came from: "Grimy huasca" → Huasca; logs from a tree
	 * patch → "Yew tree"; otherwise the item itself (Potato, Redberries...).
	 */
	static String cropFromHarvest(String itemName, String category)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return null;
		}
		String lower = itemName.toLowerCase(Locale.ENGLISH);
		if (lower.startsWith("grimy "))
		{
			// Named like the seed: "Grimy ranarr weed" → Ranarr, "Grimy guam leaf" → Guam.
			String herb = lower.substring("grimy ".length()).trim();
			if (herb.endsWith(" leaf"))
			{
				herb = herb.substring(0, herb.length() - " leaf".length());
			}
			else if (herb.endsWith(" weed") && !herb.equals("dwarf weed"))
			{
				herb = herb.substring(0, herb.length() - " weed".length());
			}
			return ItemRules.capitalize(herb);
		}
		if (lower.equals("logs"))
		{
			return "Tree";
		}
		if (lower.equals("cooking apple"))
		{
			return "Apple tree";
		}
		if (lower.equals("coconut"))
		{
			return "Palm tree";
		}
		for (String suffix : new String[]{" logs", " fruit", " bark", " leaf"})
		{
			if (lower.endsWith(suffix))
			{
				return canonicalCrop(itemName.substring(0, itemName.length() - suffix.length()));
			}
		}
		return canonicalCrop(itemName);
	}

	private void closeSession(int tick)
	{
		if (session == null)
		{
			return;
		}
		lastSession = session;
		lastSessionEndTick = tick;
		session = null;
	}

	private static String sourceKey(Session s)
	{
		return sourceKey(s.category, s.crop);
	}

	private static String sourceName(Session s)
	{
		return cropName(s.category, s.crop);
	}
}

package com.gildedledger.tracking;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

/**
 * Remembers which items on the floor came from which monster, and decides when
 * one of them has really been picked up by the player.
 *
 * <p>A drop only becomes loot when all three happen: the player clicks "Take" on
 * that item on that tile, the item then leaves the tile, and the player is
 * standing on or next to the tile when it does. Items that despawn, are picked
 * up by someone else, or vanish because the player walked away never count.
 */
public class GroundDropLedger
{
	/** Spawns this old can no longer be matched to a monster's death. */
	static final int SPAWN_MATCH_TICKS = 2;
	/** A Take click stays valid long enough to walk to an item across a boss room. */
	static final int TAKE_WINDOW_TICKS = 30;
	/** Floor items despawn for everyone after a few minutes; forget them after 5. */
	static final int DROP_LIFETIME_TICKS = 500;
	static final int PICKUP_REACH = 1;
	static final int FAR_LOOT_DISTANCE = 16;

	public static final class Pickup
	{
		public final String sourceKey;
		public final boolean taskTarget;
		public final int itemId;
		public final int quantity;

		Pickup(String sourceKey, boolean taskTarget, int itemId, int quantity)
		{
			this.sourceKey = sourceKey;
			this.taskTarget = taskTarget;
			this.itemId = itemId;
			this.quantity = quantity;
		}
	}

	private static final class Spawn
	{
		final TileKey tile;
		final int itemId;
		int quantity;
		final int tick;

		Spawn(TileKey tile, int itemId, int quantity, int tick)
		{
			this.tile = tile;
			this.itemId = itemId;
			this.quantity = quantity;
			this.tick = tick;
		}
	}

	private static final class Drop
	{
		final String sourceKey;
		final boolean taskTarget;
		final int itemId;
		int quantity;
		final int tick;

		Drop(String sourceKey, boolean taskTarget, int itemId, int quantity, int tick)
		{
			this.sourceKey = sourceKey;
			this.taskTarget = taskTarget;
			this.itemId = itemId;
			this.quantity = quantity;
			this.tick = tick;
		}
	}

	private static final class Take
	{
		final TileKey tile;
		final int itemId;
		final int tick;

		Take(TileKey tile, int itemId, int tick)
		{
			this.tile = tile;
			this.itemId = itemId;
			this.tick = tick;
		}
	}

	private final List<Spawn> unclaimedSpawns = new ArrayList<>();
	private final Map<TileKey, List<Drop>> drops = new HashMap<>();
	private final List<Take> takes = new ArrayList<>();

	/** An item appeared on the floor (or an existing pile grew). */
	public void recordSpawn(TileKey tile, int itemId, int quantity, int tick)
	{
		if (tile == null || itemId <= 0 || quantity <= 0)
		{
			return;
		}
		unclaimedSpawns.add(new Spawn(tile, itemId, quantity, tick));
	}

	/**
	 * A monster's loot was reported. Claims matching floor spawns from the last
	 * couple of ticks around the monster and attributes them to the source.
	 *
	 * @param stacks pairs of {itemId, quantity}
	 */
	public void tagNpcLoot(String sourceKey, boolean taskTarget, TileKey npcTile, int npcSize, List<int[]> stacks, int tick)
	{
		if (sourceKey == null || npcTile == null || stacks == null)
		{
			return;
		}
		int size = Math.max(1, npcSize);
		for (int[] stack : stacks)
		{
			// First under or beside the monster; then anywhere close, for bosses
			// such as Kraken and Zulrah whose loot appears by the player instead.
			int remaining = claim(sourceKey, taskTarget, stack[0], stack[1], tick, spawn -> isUnderOrBeside(spawn, npcTile, size));
			claim(sourceKey, taskTarget, stack[0], remaining, tick, spawn -> spawn.distanceTo(npcTile) <= FAR_LOOT_DISTANCE);
		}
		unclaimedSpawns.removeIf(s -> s.quantity <= 0);
	}

	private int claim(String sourceKey, boolean taskTarget, int itemId, int quantity, int tick,
		java.util.function.Predicate<TileKey> where)
	{
		int remaining = quantity;
		for (Spawn spawn : unclaimedSpawns)
		{
			if (remaining <= 0)
			{
				break;
			}
			if (spawn.itemId != itemId || spawn.quantity <= 0
				|| tick - spawn.tick > SPAWN_MATCH_TICKS
				|| !where.test(spawn.tile))
			{
				continue;
			}
			int claimed = Math.min(remaining, spawn.quantity);
			spawn.quantity -= claimed;
			remaining -= claimed;
			drops.computeIfAbsent(spawn.tile, t -> new ArrayList<>())
				.add(new Drop(sourceKey, taskTarget, itemId, claimed, tick));
		}
		return remaining;
	}

	/**
	 * The player dropped tracked loot at their feet. It stays attributed to its
	 * source, so taking it back puts it back where it came from.
	 */
	public void recordPlayerDrop(String sourceKey, int itemId, int quantity, TileKey tile, int tick)
	{
		if (sourceKey == null || tile == null || itemId <= 0 || quantity <= 0)
		{
			return;
		}
		drops.computeIfAbsent(tile, t -> new ArrayList<>()).add(new Drop(sourceKey, false, itemId, quantity, tick));
	}

	/** The player chose "Take" on a floor item. */
	public void recordTake(TileKey tile, int itemId, int tick)
	{
		if (tile != null && itemId > 0)
		{
			takes.add(new Take(tile, itemId, tick));
		}
	}

	/**
	 * Some quantity of an item left a tile. Returns what counts as picked-up loot,
	 * or an empty list when the item was not a tracked drop or not taken by us.
	 */
	public List<Pickup> recordRemoval(TileKey tile, int itemId, int quantity, int tick, TileKey playerTile)
	{
		List<Pickup> result = new ArrayList<>();
		List<Drop> onTile = drops.get(tile);
		if (onTile == null || quantity <= 0)
		{
			return result;
		}

		boolean takenByPlayer = consumeTake(tile, itemId, tick)
			&& playerTile != null && tile.distanceTo(playerTile) <= PICKUP_REACH;

		int remaining = quantity;
		Iterator<Drop> it = onTile.iterator();
		while (it.hasNext() && remaining > 0)
		{
			Drop drop = it.next();
			if (drop.itemId != itemId)
			{
				continue;
			}
			int counted = Math.min(remaining, drop.quantity);
			remaining -= counted;
			drop.quantity -= counted;
			if (takenByPlayer)
			{
				result.add(new Pickup(drop.sourceKey, drop.taskTarget, itemId, counted));
			}
			if (drop.quantity <= 0)
			{
				it.remove();
			}
		}
		if (onTile.isEmpty())
		{
			drops.remove(tile);
		}
		return result;
	}

	public void expire(int tick)
	{
		unclaimedSpawns.removeIf(s -> tick - s.tick > SPAWN_MATCH_TICKS);
		takes.removeIf(t -> tick - t.tick > TAKE_WINDOW_TICKS);
		drops.values().forEach(list -> list.removeIf(d -> tick - d.tick > DROP_LIFETIME_TICKS));
		drops.values().removeIf(List::isEmpty);
	}

	public void clear()
	{
		unclaimedSpawns.clear();
		drops.clear();
		takes.clear();
	}

	int trackedDropCount()
	{
		int count = 0;
		for (List<Drop> list : drops.values())
		{
			count += list.size();
		}
		return count;
	}

	private boolean consumeTake(TileKey tile, int itemId, int tick)
	{
		Iterator<Take> it = takes.iterator();
		while (it.hasNext())
		{
			Take take = it.next();
			if (tick - take.tick > TAKE_WINDOW_TICKS)
			{
				it.remove();
				continue;
			}
			if (take.itemId == itemId && take.tile.equals(tile))
			{
				it.remove();
				return true;
			}
		}
		return false;
	}

	/** Loot lands under a monster's footprint or one tile around it. */
	private static boolean isUnderOrBeside(TileKey spawn, TileKey npcSouthWest, int size)
	{
		return spawn.plane == npcSouthWest.plane
			&& spawn.x >= npcSouthWest.x - 1 && spawn.x <= npcSouthWest.x + size
			&& spawn.y >= npcSouthWest.y - 1 && spawn.y <= npcSouthWest.y + size;
	}
}

package com.gildedledger.tracking;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/** Item-count changes between two snapshots of a container. */
public final class InventoryDiff
{
	private final Map<Integer, Integer> changes;

	private InventoryDiff(Map<Integer, Integer> changes)
	{
		this.changes = changes;
	}

	public static InventoryDiff between(Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		Map<Integer, Integer> changes = new HashMap<>();
		Set<Integer> ids = new HashSet<>(before.keySet());
		ids.addAll(after.keySet());
		for (int id : ids)
		{
			int delta = after.getOrDefault(id, 0) - before.getOrDefault(id, 0);
			if (delta != 0)
			{
				changes.put(id, delta);
			}
		}
		return new InventoryDiff(changes);
	}

	/** A diff from changes already worked out (id → signed change). */
	public static InventoryDiff of(Map<Integer, Integer> changes)
	{
		Map<Integer, Integer> copy = new HashMap<>(changes);
		copy.values().removeIf(v -> v == 0);
		return new InventoryDiff(copy);
	}

	/** Builds an id → total quantity map from parallel id/quantity arrays. */
	public static Map<Integer, Integer> counts(int[] ids, int[] quantities)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		for (int i = 0; i < ids.length; i++)
		{
			if (ids[i] > 0 && quantities[i] > 0)
			{
				counts.merge(ids[i], quantities[i], Integer::sum);
			}
		}
		return counts;
	}

	/**
	 * Cancels out items that only changed between noted and unnoted form, such as
	 * noting herbs at a tool leprechaun or a bank. Those are never loot or costs.
	 */
	public InventoryDiff withoutNoteConversions(ItemInfo items)
	{
		Map<Integer, Integer> result = new HashMap<>(changes);
		Map<Integer, Map<Integer, Integer>> byBase = new HashMap<>();
		for (Map.Entry<Integer, Integer> change : changes.entrySet())
		{
			byBase.computeIfAbsent(items.canonical(change.getKey()), k -> new HashMap<>())
				.put(change.getKey(), change.getValue());
		}
		for (Map<Integer, Integer> forms : byBase.values())
		{
			if (forms.size() < 2)
			{
				continue;
			}
			for (Map.Entry<Integer, Integer> lost : forms.entrySet())
			{
				for (Map.Entry<Integer, Integer> gained : forms.entrySet())
				{
					int out = -result.getOrDefault(lost.getKey(), 0);
					int in = result.getOrDefault(gained.getKey(), 0);
					if (out <= 0 || in <= 0)
					{
						continue;
					}
					int converted = Math.min(out, in);
					result.merge(lost.getKey(), converted, Integer::sum);
					result.merge(gained.getKey(), -converted, Integer::sum);
				}
			}
		}
		result.values().removeIf(v -> v == 0);
		return new InventoryDiff(result);
	}

	/**
	 * Removes changes that something else has already explained, such as a
	 * dropped item or a potion dose that was drunk. Each amount has the same sign
	 * as the change it explains; a change never flips sign.
	 */
	public InventoryDiff without(Map<Integer, Integer> explained)
	{
		Map<Integer, Integer> result = new HashMap<>(changes);
		explained.forEach((id, amount) ->
		{
			int current = result.getOrDefault(id, 0);
			if (current == 0 || amount == 0 || Integer.signum(current) != Integer.signum(amount))
			{
				return;
			}
			int left = Math.abs(amount) >= Math.abs(current) ? 0 : current - amount;
			if (left == 0)
			{
				result.remove(id);
			}
			else
			{
				result.put(id, left);
			}
		});
		return new InventoryDiff(result);
	}

	/** True when nothing was gained, e.g. a pure payment. */
	public boolean hasNoGains()
	{
		for (int delta : changes.values())
		{
			if (delta > 0)
			{
				return false;
			}
		}
		return true;
	}

	public Map<Integer, Integer> changes()
	{
		return changes;
	}

	public int change(int itemId)
	{
		return changes.getOrDefault(itemId, 0);
	}

	public boolean isEmpty()
	{
		return changes.isEmpty();
	}
}

package com.gildedledger.tracking;

/** Item lookups the trackers need, abstracted so they can be tested without a game client. */
public interface ItemInfo
{
	String name(int itemId);

	/** Grand Exchange value of one item; used for every supply cost. */
	long marketPrice(int itemId);

	boolean stackable(int itemId);

	/** Turns a noted or placeholder id into the base item id. */
	int canonical(int itemId);

	/** Can it be traded? */
	default boolean tradeable(int itemId)
	{
		return true;
	}

	/** The item with exactly this name (ignoring case), or -1. */
	default int idByName(String name)
	{
		return -1;
	}
}

package com.gildedledger.tracking;

import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Name-based rules for classifying items. Names are used instead of hard-coded
 * IDs so new potions, seeds and saplings work without a plugin update.
 */
public final class ItemRules
{
	private static final Pattern DOSE_SUFFIX = Pattern.compile("^(.*)\\((\\d)\\)$");
	private static final Pattern COMPOST_MESSAGE = Pattern.compile(
		"^You treat the .+ with (compost|supercompost|ultracompost)\\.?$", Pattern.CASE_INSENSITIVE);

	private ItemRules()
	{
	}

	/** "Prayer potion(3)" → 3. Items without a dose suffix count as one use. */
	public static int doses(String name)
	{
		if (name == null)
		{
			return 1;
		}
		Matcher m = DOSE_SUFFIX.matcher(name.trim());
		if (!m.matches())
		{
			return 1;
		}
		int doses = m.group(2).charAt(0) - '0';
		return doses >= 1 && doses <= 6 ? doses : 1;
	}

	/** "Prayer potion(3)" → "Prayer potion". */
	public static String withoutDoses(String name)
	{
		if (name == null)
		{
			return "";
		}
		Matcher m = DOSE_SUFFIX.matcher(name.trim());
		return m.matches() ? m.group(1).trim() : name.trim();
	}

	/** Value of one sip, from the price of the potion actually drunk. */
	public static long perDoseValue(long itemPrice, String name)
	{
		if (itemPrice <= 0)
		{
			return 0;
		}
		return Math.max(1, itemPrice / doses(name));
	}

	public static boolean isRune(String name, boolean stackable)
	{
		return stackable && name != null && name.toLowerCase(Locale.ENGLISH).endsWith(" rune");
	}

	/**
	 * Teleport tablets (including house tabs with Inside/Outside), teleport
	 * scrolls and similar. Matched broadly: the cost is only charged once the
	 * item actually leaves the inventory, so options that don't consume it cost nothing.
	 */
	public static boolean isTeleportConsumable(String name, String option)
	{
		if (name == null || option == null)
		{
			return false;
		}
		String n = name.toLowerCase(Locale.ENGLISH);
		String o = option.toLowerCase(Locale.ENGLISH).trim();
		boolean teleportItem = (n.contains("teleport") || n.contains("tablet") || n.endsWith(" tab")
			|| n.contains(" scroll")) && !n.contains("teleport crystal");
		boolean consumingOption = !o.isEmpty() && !o.equals("drop") && !o.equals("examine") && !o.equals("use")
			&& !o.equals("destroy") && !o.equals("check") && !o.equals("wield") && !o.equals("wear")
			&& !o.equals("remove") && !o.equals("cancel");
		return teleportItem && consumingOption;
	}

	/** Seeds, saplings and other things you put into a patch. */
	public static boolean isPlantable(String name)
	{
		if (name == null)
		{
			return false;
		}
		String n = name.toLowerCase(Locale.ENGLISH);
		return n.endsWith(" seed") || n.endsWith(" sapling") || n.endsWith(" acorn")
			|| n.endsWith(" spore") || n.endsWith(" seeds");
	}

	/** Money-like items: paying or receiving these is buying or selling, not processing. */
	public static boolean isCurrency(String name)
	{
		if (name == null)
		{
			return false;
		}
		String n = name.toLowerCase(Locale.ENGLISH);
		return n.equals("coins") || n.equals("platinum token") || n.equals("tokkul") || n.equals("trading sticks")
			|| n.equals("numulite") || n.equals("mark of grace") || n.equals("ecto-token") || n.equals("warrior guild token");
	}

	/** Reward currencies: never worth anything in the log, whatever their alch price. */
	private static final Set<String> ZERO_VALUE_CURRENCIES = Set.of(
		"mark of grace", "abyssal pearls", "molch pearl", "tokkul", "numulite", "trading sticks", "ecto-token",
		"warrior guild token", "golden nugget", "unidentified minerals", "stardust", "hallowed mark",
		"mermaid's tear", "termites", "agility arena ticket", "castle wars ticket", "pieces of eight",
		"brimhaven voucher", "soul fragment", "frozen tear", "minnow", "barronite shards");

	/**
	 * Items valued at nothing: clue scrolls, caskets and their containers (their alch
	 * price says nothing about the reward), and reward currencies like marks of grace.
	 */
	public static boolean isZeroValue(String name)
	{
		if (name == null)
		{
			return false;
		}
		String n = name.toLowerCase(Locale.ENGLISH).trim();
		return n.startsWith("clue scroll") || n.startsWith("clue bottle") || n.startsWith("clue geode")
			|| n.startsWith("clue nest") || n.startsWith("scroll box") || n.startsWith("reward casket")
			|| n.startsWith("challenge scroll") || n.startsWith("puzzle box") || n.startsWith("light box")
			|| ZERO_VALUE_CURRENCIES.contains(n);
	}

	/** Items that only exist inside a minigame and are gone when it ends. */
	private static final Set<String> MINIGAME_ITEMS = Set.of(
