		java.util.Map.entry("flockleader geerin", "Kree'arra"),
		java.util.Map.entry("wingman skree", "Kree'arra"),
		java.util.Map.entry("tstanon karlak", "K'ril Tsutsaroth"),
		java.util.Map.entry("zakl'n gritch", "K'ril Tsutsaroth"),
		java.util.Map.entry("balfrug kreeyath", "K'ril Tsutsaroth"),
		java.util.Map.entry("fumus", "Nex"),
		java.util.Map.entry("umbra", "Nex"),
		java.util.Map.entry("cruor", "Nex"),
		java.util.Map.entry("glacies", "Nex"),
		java.util.Map.entry("branda the fire queen", "Royal Titans"),
		java.util.Map.entry("eldric the ice king", "Royal Titans"),
		java.util.Map.entry("hueycoatl tail", "The Hueycoatl"),
		java.util.Map.entry("hueycoatl body", "The Hueycoatl"),
		java.util.Map.entry("ahrim the blighted", "Barrows"),
		java.util.Map.entry("dharok the wretched", "Barrows"),
		java.util.Map.entry("guthan the infested", "Barrows"),
		java.util.Map.entry("karil the tainted", "Barrows"),
		java.util.Map.entry("torag the corrupted", "Barrows"),
		java.util.Map.entry("verac the defiled", "Barrows"),
		java.util.Map.entry("great olm (left claw)", "Great Olm"),
		java.util.Map.entry("great olm (right claw)", "Great Olm"));

	/** The boss a monster belongs to (Hespori's flowers → Hespori), or the name unchanged. */
	public static String bossGroup(String npcName)
	{
		if (npcName == null)
		{
			return null;
		}
		String boss = BOSS_PARTS.get(npcName.toLowerCase(Locale.ENGLISH).trim());
		return boss != null ? boss : npcName;
	}

	/** Is this NPC a boss? */
	public static boolean isBoss(String npcName)
	{
		return npcName != null && BOSSES.contains(npcName.toLowerCase(Locale.ENGLISH).trim());
	}

	/** Tarnished items (a tarnished ring polishes into a real ring), valued at their alch price. */
	public static boolean isTarnished(String name)
	{
		return name != null && name.toLowerCase(Locale.ENGLISH).startsWith("tarnished");
	}

	/** Runecrafting essence pouches, degraded or not; they degrade and get repaired. */
	public static boolean isEssencePouch(String name)
	{
		if (name == null)
		{
			return false;
		}
		String n = name.toLowerCase(Locale.ENGLISH).trim();
		return n.matches("(small|medium|large|giant|colossal) pouch.*");
	}

	/**
	 * Items that change into another version of themselves as they're used (a slayer
	 * ring losing a charge, an essence pouch degrading): neither loot nor a cost.
	 */
	public static boolean isDegrading(String name)
	{
		if (name == null)
		{
			return false;
		}
		String n = name.toLowerCase(Locale.ENGLISH).trim();
		return isEssencePouch(name) || n.startsWith("slayer ring");
	}

	public static boolean isCompost(String name)
	{
		if (name == null)
		{
			return false;
		}
		String n = name.toLowerCase(Locale.ENGLISH);
		return n.equals("compost") || n.equals("supercompost") || n.equals("ultracompost");
	}

	/** Returns the compost name from "You treat the herb patch with ultracompost.", or null. */
	public static String compostFromMessage(String message)
	{
		if (message == null)
		{
			return null;
		}
		Matcher m = COMPOST_MESSAGE.matcher(message.trim());
		return m.matches() ? capitalize(m.group(1).toLowerCase(Locale.ENGLISH)) : null;
	}

	/** Tools and containers that move in and out of the inventory during farming and are never loot. */
	public static boolean isFarmingTool(String name)
	{
		if (name == null)
		{
			return true;
		}
		String n = name.toLowerCase(Locale.ENGLISH);
		return n.startsWith("watering can") || n.contains("compost bucket") || n.equals("bucket")
			|| n.equals("empty plant pot") || n.equals("plant pot") || n.equals("spade") || n.equals("rake")
			|| n.equals("seed dibber") || n.contains("secateurs") || n.equals("gardening trowel")
			|| n.equals("weeds") || n.startsWith("plant cure");
	}

	/** Crop name from what was planted: "Ranarr seed" → "Ranarr", "Magic sapling" → "Magic". */
	public static String cropFromPlantable(String name)
	{
		if (name == null)
		{
			return null;
		}
		String n = name.trim();
		String[] suffixes = {" seeds", " seed", " sapling", " acorn", " spore"};
		for (String suffix : suffixes)
		{
			if (n.toLowerCase(Locale.ENGLISH).endsWith(suffix))
			{
				return capitalize(n.substring(0, n.length() - suffix.length()).trim());
			}
		}
		return capitalize(n);
	}

	/**
	 * Crop name from the patch object's current appearance, used when the plugin
	 * never saw the planting. Generic appearances return null.
	 */
	public static String cropFromPatchAppearance(String name)
	{
		if (name == null)
		{
			return null;
		}
		String n = name.trim();
		String lower = n.toLowerCase(Locale.ENGLISH);
		for (String prefix : new String[]{"diseased ", "dead "})
		{
			if (lower.startsWith(prefix))
			{
				n = n.substring(prefix.length());
				lower = lower.substring(prefix.length());
			}
		}
		if (lower.isEmpty() || lower.equals("null") || lower.equals("herbs") || lower.contains("patch")
			|| lower.contains("stump") || lower.equals("weeds") || lower.equals("tree") || lower.equals("bush"))
		{
			return null;
		}
		for (String suffix : new String[]{" tree", " bush", " plant"})
		{
			if (lower.endsWith(suffix))
			{
				n = n.substring(0, n.length() - suffix.length());
				break;
			}
		}
		return capitalize(n.trim());
	}

	/** "Fruit Tree Patch" → "Fruit tree"; "Herb patch" → "Herb". */
	public static String patchCategory(String baseObjectName)
	{
		if (baseObjectName == null)
		{
			return "Farming";
		}
		String n = baseObjectName.trim().toLowerCase(Locale.ENGLISH);
		if (n.endsWith(" patch"))
		{
			n = n.substring(0, n.length() - " patch".length());
		}
		n = n.trim();
		if (n.isEmpty() || n.equals("null"))
		{
			return "Farming";
		}
		return capitalize(n);
	}

	public static String capitalize(String s)
	{
		if (s == null || s.isEmpty())
		{
			return s;
		}
		return Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.gildedledger.tracking;

import com.gildedledger.data.SourceCategory;
import com.gildedledger.data.SourceRecord;
import com.gildedledger.data.TrackerData;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.LongSupplier;

/**
 * The single place trackers write to. Holds the loaded account's data and
 * remembers whether anything changed since the last save.
 */
public class Ledger
{
	private static final int RECENT_LOOT_LIMIT = 2000;

	private static final class LootEntry
	{
		final String sourceKey;
		final int itemId;
		long quantity;

		LootEntry(String sourceKey, int itemId, long quantity)
		{
			this.sourceKey = sourceKey;
			this.itemId = itemId;
			this.quantity = quantity;
		}
	}

	/** Where recent loot came from, newest last, so a drop can be undone from the right source. */
	private final Deque<LootEntry> recentLoot = new ArrayDeque<>();
	private final LongSupplier clock;
	private TrackerData data = new TrackerData();
	private boolean dirty;
	private long revision;

	public Ledger(LongSupplier clock)
	{
		this.clock = clock;
	}

	public TrackerData data()
	{
		return data;
	}

	public void load(TrackerData loaded)
	{
		data = loaded == null ? new TrackerData() : loaded.normalize();
		recentLoot.clear();
		dirty = false;
		revision++;
	}

	public long now()
	{
		return clock.getAsLong();
	}

	public SourceRecord source(String key, String name, SourceCategory category)
	{
		return data.source(key, name, category, now());
	}

	public void addLoot(String key, String name, SourceCategory category, int itemId, long quantity)
	{
		source(key, name, category).addLoot(itemId, quantity, now());
		recentLoot.addLast(new LootEntry(key, itemId, quantity));
		while (recentLoot.size() > RECENT_LOOT_LIMIT)
		{
			recentLoot.removeFirst();
		}
		changed();
	}

	/**
	 * The player dropped some of an item: take it back out of the loot of the
	 * source that most recently gave it. Only loot the tracker logged this session
	 * is touched, so dropping something picked up off the floor changes nothing.
	 *
	 * @return how much was removed from each source, keyed by source key
	 */
	public Map<String, Long> removeDroppedLoot(int itemId, long quantity)
	{
		Map<String, Long> removedFrom = new LinkedHashMap<>();
		long remaining = quantity;
		Iterator<LootEntry> it = recentLoot.descendingIterator();
		while (it.hasNext() && remaining > 0)
		{
			LootEntry entry = it.next();
			if (entry.itemId != itemId)
			{
				continue;
			}
			SourceRecord record = data.sources.get(entry.sourceKey);
			long removed = record == null ? 0 : record.removeLoot(itemId, Math.min(remaining, entry.quantity), now());
			remaining -= removed;
			entry.quantity -= removed;
			if (removed > 0)
			{
				removedFrom.merge(entry.sourceKey, removed, Long::sum);
			}
			if (entry.quantity <= 0 || removed == 0)
			{
				it.remove();
			}
		}
		if (!removedFrom.isEmpty())
		{
			changed();
		}
		return removedFrom;
	}

	/** Carried items went into or out of storage; recent loot can no longer be matched to drops. */
	public void forgetLootHistory()
	{
		recentLoot.clear();
	}

	public void addSupply(String key, String name, SourceCategory category,
		String lineKey, int itemId, String lineName, String unit, long quantity, long gp)
	{
		source(key, name, category).addSupply(lineKey, itemId, lineName, unit, quantity, gp, now());
		changed();
	}

	/** Moves an already-charged supply from one source to another (compost following a new crop). */
	public void moveSupply(String fromKey, String toKey, String toName, SourceCategory category,
		String lineKey, int itemId, String lineName, long quantity, long gp)
	{
		SourceRecord from = data.sources.get(fromKey);
		if (from == null || !from.removeSupply(lineKey, quantity, gp))
		{
			return;
		}
		if (from.isEmpty())
		{
			data.sources.remove(fromKey);
		}
		source(toKey, toName, category).addSupply(lineKey, itemId, lineName, null, quantity, gp, now());
		changed();
	}

	/** Moves XP from one source to another (composting XP following a new crop). */
	public void moveXp(String fromKey, String toKey, String toName, SourceCategory category, String skill, long amount)
	{
		SourceRecord from = data.sources.get(fromKey);
		if (from == null || !from.removeXp(skill, amount))
		{
			return;
		}
		if (from.isEmpty())
		{
			data.sources.remove(fromKey);
		}
		source(toKey, toName, category).addXp(skill, amount, now());
		changed();
	}

	/** Folds a whole source into another one (renaming it when the other doesn't exist yet). */
	public void mergeInto(String fromKey, String toKey, String toName)
	{
		if (fromKey.equals(toKey))
		{
			return;
		}
		SourceRecord from = data.sources.remove(fromKey);
		if (from == null)
		{
			return;
		}
		SourceRecord to = data.sources.get(toKey);
		if (to == null)
		{
			from.key = toKey;
			from.name = toName;
			data.sources.put(toKey, from);
		}
		else
		{
			to.mergeFrom(from);
		}
		changed();
	}

	public void addXp(String key, String name, SourceCategory category, String skill, long amount)
	{
		source(key, name, category).addXp(skill, amount, now());
		changed();
	}

	public void incrementCount(String key, String name, SourceCategory category)
	{
		source(key, name, category).incrementCount(now());
		changed();
	}

	public void remove(String key)
	{
		if (data.sources.remove(key) != null)
		{
			changed();
		}
	}

	public void changed()
	{
		dirty = true;
		revision++;
	}

	public boolean isDirty()
	{
		return dirty;
	}

	public void markSaved()
	{
		dirty = false;
	}

	/** Increases on every change; the panel uses it to skip redundant redraws. */
	public long revision()
	{
		return revision;
	}
}

package com.gildedledger.tracking;

import com.gildedledger.data.SourceCategory;
import com.gildedledger.data.SourceRecord;
import com.gildedledger.data.SupplyLine;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Brings data saved by older versions in line with what's tracked now, every time a
 * profile loads (it changes nothing the second time):
 * <ul>
 *   <li>Items that are no longer tracked (minigame-only items like the Tears of Guthix
 *   stone bowl, a slayer ring losing charges, essence pouches degrading) are removed.</li>
 *   <li>Hespori seeds planted move from Farming to the Hespori kill in PvM.</li>
 *   <li>Farming entries for untradeable plants are remembered, so "Hide untradeable
 *   plants" can hide them.</li>
 *   <li>Monsters that are part of a boss fight (Hespori's flowers) merge into the boss.</li>
 * </ul>
 */
public final class LegacyTidy
{
	private LegacyTidy()
	{
	}

	public static void tidy(Ledger ledger, ItemInfo items)
	{
		List<SourceRecord> records = new ArrayList<>(ledger.data().sources.values());
		boolean changed = false;
		for (SourceRecord record : records)
		{
			changed |= dropUntrackedItems(record, items);
			if (record.category == SourceCategory.FARMING)
			{
				changed |= moveHesporiSeeds(ledger, record, items);
				noteUntradeablePlant(ledger, record, items);
			}
			if (record.isEmpty())
			{
				ledger.data().sources.remove(record.key);
				changed = true;
				continue;
			}
			if (record.category == SourceCategory.COMBAT && record.name != null)
			{
				// Boss parts (Hespori's flowers) join the boss.
				String boss = ItemRules.bossGroup(record.name);
				if (!boss.equals(record.name))
				{
					ledger.mergeInto(record.key, "npc:" + boss, boss);
					changed = true;
				}
			}
		}
		if (changed)
		{
			ledger.changed();
		}
	}

	private static boolean untracked(String name)
	{
		return ItemRules.isMinigameItem(name) || ItemRules.isDegrading(name);
	}

	private static boolean dropUntrackedItems(SourceRecord record, ItemInfo items)
	{
		boolean changed = record.loot.keySet().removeIf(id -> untracked(items.name(id)));
		changed |= record.supplies.values().removeIf(line -> untracked(line.name != null ? line.name : items.name(line.itemId)));
		return changed;
	}

	private static boolean moveHesporiSeeds(Ledger ledger, SourceRecord record, ItemInfo items)
	{
		boolean moved = false;
		for (Map.Entry<String, SupplyLine> e : new ArrayList<>(record.supplies.entrySet()))
		{
			SupplyLine line = e.getValue();
			if ("hespori seed".equalsIgnoreCase(items.name(line.itemId)))
			{
				ledger.moveSupply(record.key, "npc:" + FarmingTracker.HESPORI, FarmingTracker.HESPORI,
					SourceCategory.COMBAT, e.getKey(), line.itemId, line.name, line.quantity, line.gp);
				moved = true;
			}
		}
		return moved;
	}

	private static void noteUntradeablePlant(Ledger ledger, SourceRecord record, ItemInfo items)
	{
		if (record.name == null || FarmingTracker.HESPORI.equals(record.name) || "Other".equals(record.name))
		{
			return;
		}
		boolean untradeableSeed = record.supplies.values().stream()
			.anyMatch(line -> ItemRules.isPlantable(items.name(line.itemId)) && !items.tradeable(line.itemId));
		boolean untradeableHarvest = !record.loot.isEmpty()
			&& record.loot.keySet().stream().allMatch(id -> !items.tradeable(id));
		if (untradeableSeed || untradeableHarvest)
		{
			ledger.data().untradeableCrops.add(record.name);
		}
	}
}

package com.gildedledger.tracking;

import com.gildedledger.data.SourceCategory;
import java.util.Locale;
import java.util.Map;

/**
 * Minigame reward pulls: searching the Rewards Guardian (Guardians of the Rift), fishing
 * the Tempoross reward pool, the Wintertodt reward cart or supply crates, and so on.
 * Everything gained from a pull is loot for that minigame, filed under its skill, or
 * under Other when it belongs to no skill.
 */
public class MinigameRewards
{
	/** How long after the click (or the last item received) a pull keeps paying out. */
	static final int WINDOW_TICKS = 8;
	/** Waiting for the first item: a Big-search can take a while to start paying out. */
	static final int FIRST_ITEM_TICKS = 30;

	/** A minigame and the category its rewards go to. */
	public static final class Minigame
	{
		public final String name;
		public final SourceCategory category;
		private final String key;

		Minigame(String name, SourceCategory category)
		{
			this(name, category, "reward:" + name);
		}

		Minigame(String name, SourceCategory category, String key)
		{
			this.name = name;
			this.category = category;
			this.key = key;
		}

		public String key()
		{
			return key;
		}
	}

	private static final Minigame GOTR = new Minigame("Guardians of the Rift", SourceCategory.RUNECRAFTING);
	private static final Minigame TEMPOROSS = new Minigame("Tempoross", SourceCategory.FISHING);
	private static final Minigame WINTERTODT = new Minigame("Wintertodt", SourceCategory.FIREMAKING);
	private static final Minigame TRAWLER = new Minigame("Fishing Trawler", SourceCategory.FISHING);
	private static final Minigame SEPULCHRE = new Minigame("Hallowed Sepulchre", SourceCategory.AGILITY);
	private static final Minigame PLUNDER = new Minigame("Pyramid Plunder", SourceCategory.THIEVING);
	private static final Minigame RUMOURS = new Minigame("Hunter rumours", SourceCategory.HUNTER);
	private static final Minigame SOUL_WARS = new Minigame("Soul Wars", SourceCategory.OTHER);
	/** Motherlode Mine: the sack's ores join the same entry as the pay-dirt mined. */
	public static final Minigame MOTHERLODE = new Minigame(SkillGroups.MOTHERLODE, SourceCategory.MINING,
		"item:MINING:" + SkillGroups.MOTHERLODE);

	/** Vale Totems: the ents' offerings join the same entry as the logs and bows used. */
	public static final Minigame VALE_TOTEMS = new Minigame(SkillGroups.VALE_TOTEMS, SourceCategory.FLETCHING,
		"item:FLETCHING:" + SkillGroups.VALE_TOTEMS);

	/** Reward objects and NPCs, by name. */
	private static final Map<String, Minigame> TARGETS = Map.ofEntries(
		Map.entry("rewards guardian", GOTR),
		Map.entry("offerings", VALE_TOTEMS),
		Map.entry("vale offerings", VALE_TOTEMS),
		Map.entry("reward pool", TEMPOROSS),
		Map.entry("reward cart", WINTERTODT),
		Map.entry("reward crate", WINTERTODT),
		Map.entry("trawler net", TRAWLER),
		Map.entry("reward net", TRAWLER),
		Map.entry("grand hallowed coffin", SEPULCHRE),
		Map.entry("grand gold chest", PLUNDER));

	/** Reward items you open, by the start of their name. */
	private static final Map<String, Minigame> ITEMS = Map.ofEntries(
		Map.entry("intricate pouch", GOTR),
		Map.entry("supply crate", WINTERTODT),
		Map.entry("hunters' loot sack", RUMOURS),
		Map.entry("spoils of war", SOUL_WARS));

	private Minigame active;
	private int untilTick;

	/** The minigame a click on this object or NPC pulls rewards from, or null. */
	public static Minigame forTarget(String target, String option)
	{
		if (isLookingOnly(option))
		{
			return null;
		}
		if (lower(target).equals("sack") && lower(option).equals("search"))
		{
			// The Motherlode Mine sack, where pay-dirt from the hopper comes out as ore.
			return MOTHERLODE;
		}
		return TARGETS.get(lower(target));
	}

	/** The minigame a reward item belongs to, or null. */
	public static Minigame forItem(String itemName, String option)
	{
		if (isLookingOnly(option))
		{
			return null;
		}
		String n = lower(itemName);
		for (Map.Entry<String, Minigame> e : ITEMS.entrySet())
		{
			if (n.startsWith(e.getKey()))
			{
				return e.getValue();
			}
		}
		return null;
	}

	private static boolean isLookingOnly(String option)
	{
		String o = lower(option);
		return o.isEmpty() || o.equals("examine") || o.equals("check") || o.equals("talk-to") || o.equals("inspect")
			|| o.equals("drop") || o.equals("use") || o.equals("walk here") || o.equals("cancel");
	}

	public void onRewardClicked(Minigame minigame, int tick)
	{
		active = minigame;
		untilTick = tick + FIRST_ITEM_TICKS;
	}

	/** Any other click ends the pull. */
	public void onOtherClick()
	{
		active = null;
	}

	public boolean isActive(int tick)
	{
		return active != null && tick <= untilTick;
	}

	/**
	 * Items received during a pull are that minigame's loot (the crate or pouch opened is
	 * not a cost). Returns true when the change was a reward and has been booked.
	 */
	public boolean onCarriedChanges(InventoryDiff diff, int tick, Ledger ledger)
	{
		if (!isActive(tick))
		{
			active = null;
			return false;
		}
		boolean gained = false;
		for (Map.Entry<Integer, Integer> change : diff.changes().entrySet())
		{
			if (change.getValue() > 0)
			{
				ledger.addLoot(active.key(), active.name, active.category, change.getKey(), change.getValue());
				gained = true;
			}
		}
		if (gained)
		{
			ledger.incrementCount(active.key(), active.name, active.category);
			// Big-searches keep going on their own: stay open while items keep coming.
			untilTick = Math.max(untilTick, tick + WINDOW_TICKS * 2);
		}
		return true;
	}

	public void reset()
	{
		active = null;
	}

	private static String lower(String s)
	{
		return s == null ? "" : s.toLowerCase(Locale.ENGLISH).trim();
	}
}

package com.gildedledger.tracking;

import com.gildedledger.data.SourceCategory;
import com.gildedledger.data.SourceRecord;
import com.gildedledger.data.TaskRecord;
import com.gildedledger.data.TrackerData;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

/**
 * Supplies that may still need to move once we know more:
 * <ul>
 *   <li>General supplies used just before a fight (a super combat potion before the
 *   goblin, charges spent before the first kill) move to the monster when it dies.</li>
 *   <li>Blowpipe darts and scales are booked as an estimate per shot. When the
 *   blowpipe is checked, the estimate since the last check is corrected to the
 *   exact amount used.</li>
 * </ul>
 */
public class RecentSupplies
{
	/** Supplies used up to this long (2 minutes) before a fight count towards it. */
	public static final int PRE_FIGHT_TICKS = 200;

	/** One booking, kept so it can be moved or corrected later. */
	public static final class Booked
	{
		String key;
		String name;
		SourceCategory category;
		boolean task;
		final String lineKey;
		final int itemId;
		final String lineName;
		final String unit;
		long quantity;
		long gp;
		final int tick;
		final boolean countedUse;

		public Booked(String key, String name, SourceCategory category, boolean task, String lineKey, int itemId,
			String lineName, String unit, long quantity, long gp, int tick, boolean countedUse)
		{
			this.key = key;
			this.name = name;
			this.category = category;
			this.task = task;
			this.lineKey = lineKey;
			this.itemId = itemId;
			this.lineName = lineName;
			this.unit = unit;
			this.quantity = quantity;
			this.gp = gp;
			this.tick = tick;
			this.countedUse = countedUse;
		}
	}

	private final Ledger ledger;
	private final List<Booked> general = new ArrayList<>();
	private final List<Booked> blowpipe = new ArrayList<>();

	private int checkedDart = -1;
	private long checkedDarts = -1;
	private long checkedScales = -1;

	public RecentSupplies(Ledger ledger)
	{
		this.ledger = ledger;
	}

	/** A supply just booked to General supplies. */
	public void addGeneral(Booked booked)
	{
		general.add(booked);
	}

	/** Blowpipe darts or scales just booked (wherever they went). */
	public void addBlowpipe(Booked booked)
	{
		blowpipe.add(booked);
	}

	/** Boss fights can be long: supplies are kept this long (15 minutes) in case a boss dies. */
	public static final int BOSS_TICKS = 1500;

	/** Forgets general supplies too old to belong to any fight starting now. */
	public void expire(int tick)
	{
		general.removeIf(b -> tick - b.tick > BOSS_TICKS);
	}

	/**
	 * A monster died: general supplies used since {@code sinceTick} were for this fight,
	 * so they move from General supplies to the monster (and the Slayer task if it's one).
	 */
	public void moveGeneralToKill(String key, String name, boolean task, int sinceTick)
	{
		moveGeneralTo(key, name, SourceCategory.COMBAT, task, sinceTick);
	}

	/**
	 * Moves general supplies used since {@code sinceTick} to a source: the monster killed, or
	 * a skilling action boosted by the potion or food (a dragonfruit pie before fletching).
	 */
	public void moveGeneralTo(String key, String name, SourceCategory category, boolean task, int sinceTick)
	{
		TrackerData data = ledger.data();
		for (Iterator<Booked> it = general.iterator(); it.hasNext(); )
		{
			Booked b = it.next();
			if (b.tick < sinceTick)
			{
				continue;
			}
			it.remove();
			if (!TrackerData.GENERAL_SUPPLIES_KEY.equals(b.key))
			{
				continue;
			}
			SourceRecord from = data.sources.get(b.key);
			if (from == null || !from.removeSupply(b.lineKey, b.quantity, b.gp))
			{
				continue;
			}
			if (b.countedUse && from.count > 0)
			{
				from.count--;
			}
			if (from.isEmpty())
			{
				data.sources.remove(b.key);
			}
			ledger.source(key, name, category)
				.addSupply(b.lineKey, b.itemId, b.lineName, b.unit, b.quantity, b.gp, ledger.now());
			b.key = key;
			b.name = name;
			b.category = category;
			b.task = task;
			if (task)
			{
				adjustTask(b.gp);
			}
		}
		ledger.changed();
	}

	/** Darts or scales were loaded or taken out: the last check no longer tells us anything. */
	public void forgetBlowpipeCheck()
	{
		checkedDart = -1;
		checkedDarts = -1;
		checkedScales = -1;
		blowpipe.clear();
	}

	/**
	 * The blowpipe was checked. Corrects the per-shot estimate since the last check to
	 * what was really used. Returns true when a correction could be made.
	 *
	 * @param dartId the dart loaded, or -1 for none
	 * @param scaleId the item id of Zulrah's scales
	 */
	public boolean onBlowpipeCheck(int dartId, long darts, long scales, int scaleId, LongPrice price)
	{
		boolean corrected = false;
		if (checkedScales >= 0 && scales <= checkedScales)
		{
			correct(scaleId, checkedScales - scales, price);
			corrected = true;
		}
		if (checkedDarts >= 0 && dartId > 0 && dartId == checkedDart && darts <= checkedDarts)
		{
			correct(dartId, checkedDarts - darts, price);
			corrected = true;
		}
		checkedDart = dartId;
		checkedDarts = dartId > 0 ? darts : 0;
		checkedScales = scales;
		blowpipe.clear();
		if (corrected)
		{
			ledger.changed();
		}
		return corrected;
	}

	/** Prices an item. */
	public interface LongPrice
	{
		long of(int itemId);
	}

	private void correct(int itemId, long actual, LongPrice price)
	{
		long estimated = 0;
		Booked last = null;
		for (Booked b : blowpipe)
		{
			if (b.itemId == itemId)
			{
				estimated += b.quantity;
				last = b;
			}
		}
		long diff = actual - estimated;
		if (diff > 0)
		{
			// Used more than we guessed: the extra goes where the last shot went.
			String key = last != null ? last.key : TrackerData.GENERAL_SUPPLIES_KEY;
			String name = last != null ? last.name : TrackerData.GENERAL_SUPPLIES_NAME;
			SourceCategory category = last != null ? last.category : SourceCategory.GENERAL_SUPPLIES;
			long gp = price.of(itemId) * diff;
			String lineName = last != null ? last.lineName : null;
			ledger.source(key, name, category)
				.addSupply(String.valueOf(itemId), itemId, lineName, null, diff, gp, ledger.now());
			if (last != null && last.task)
			{
				adjustTask(gp);
			}
			return;
		}
		// Used fewer than we guessed: take the difference back, newest first.
		long refund = -diff;
		for (int i = blowpipe.size() - 1; i >= 0 && refund > 0; i--)
		{
			Booked b = blowpipe.get(i);
			if (b.itemId != itemId || b.quantity <= 0)
			{
				continue;
			}
			long take = Math.min(refund, b.quantity);
			long gp = b.quantity == 0 ? 0 : b.gp * take / b.quantity;
			SourceRecord from = ledger.data().sources.get(b.key);
			if (from != null && from.removeSupply(b.lineKey, take, gp))
			{
				if (from.isEmpty())
				{
					ledger.data().sources.remove(b.key);
				}
				b.quantity -= take;
				b.gp -= gp;
				refund -= take;
				if (b.task)
				{
					adjustTask(-gp);
				}
			}
		}
	}

	private void adjustTask(long gp)
	{
		TaskRecord task = ledger.data().currentTask;
		if (task != null && !task.isFinished())
		{
			task.supplyGp = Math.max(0, task.supplyGp + gp);
		}
	}

	public void reset()
	{
		general.clear();
		forgetBlowpipeCheck();
	}
}

package com.gildedledger.tracking;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Decides when to remind the player to re-pot, drink prayer or reload the cannon.
 * Each reminder fires once, and is armed again when the thing is topped back up.
 *
 * <p>Boosts: a divine potion's boost lasts as long as its timer. Any other boost
 * drops by one level every minute (90 seconds with Preserve), on a clock shared by
 * all stats, so a boost of 5 runs out four minutes after the next drop.
 */
public class Reminders
{
	public static final int DECAY_TICKS = 100;
	public static final int PRESERVE_DECAY_TICKS = 150;

	private final Map<String, Integer> lastBoost = new HashMap<>();
	private final Map<String, Integer> lastDivine = new HashMap<>();
	private final Map<String, Boolean> boostArmed = new HashMap<>();
	private int lastDecayTick = Integer.MIN_VALUE;

	private boolean prayerArmed = true;
	private int lastPrayer = -1;
	private int lastCannonballs = -1;
	private boolean cannonArmed = true;

	/**
	 * Called every tick with the current boost (boosted minus real level) of each
	 * combat skill, and the divine potion ticks left for it (0 if none).
	 * Returns the skills whose boost runs out within {@code warnTicks}.
	 */
	public List<String> onBoosts(int tick, Map<String, Integer> boosts, Map<String, Integer> divineTicks,
		boolean preserve, int warnTicks)
	{
		// A stat dropping by exactly one with no divine timer is the shared decay clock.
		for (Map.Entry<String, Integer> e : boosts.entrySet())
		{
			Integer before = lastBoost.get(e.getKey());
			int divine = divineTicks.getOrDefault(e.getKey(), 0);
			if (before != null && before > 0 && e.getValue() == before - 1 && divine <= 0)
			{
				lastDecayTick = tick;
			}
		}

		int interval = preserve ? PRESERVE_DECAY_TICKS : DECAY_TICKS;
		List<String> warn = new ArrayList<>();
		for (Map.Entry<String, Integer> e : boosts.entrySet())
		{
			String skill = e.getKey();
			int boost = e.getValue();
			int divine = divineTicks.getOrDefault(skill, 0);
			int before = lastBoost.getOrDefault(skill, 0);
			int divineBefore = lastDivine.getOrDefault(skill, 0);
			lastBoost.put(skill, boost);
			lastDivine.put(skill, divine);

			if (boost <= 0)
			{
				boostArmed.put(skill, false);
				continue;
			}
			long remaining = remainingTicks(tick, boost, divine, interval);
			boolean topUp = boost > before || divine > divineBefore;
			if (topUp)
			{
				// Freshly drunk: remind once it's nearly gone (unless it's already that short).
				boostArmed.put(skill, remaining > warnTicks);
				continue;
			}
			if (boostArmed.getOrDefault(skill, false) && remaining <= warnTicks)
			{
				boostArmed.put(skill, false);
				warn.add(skill);
			}
		}
		return warn;
	}

	/** Ticks until the boost is gone (or, for a divine potion, until its timer ends). */
	long remainingTicks(int tick, int boost, int divineTicks, int interval)
	{
		if (divineTicks > 0)
		{
			return divineTicks;
		}
		// Unknown clock: assume the next drop is due now, so the reminder is early rather than late.
		long sinceDrop = lastDecayTick == Integer.MIN_VALUE ? interval : Math.min(interval, tick - (long) lastDecayTick);
		long untilNextDrop = Math.max(0, interval - sinceDrop);
		return untilNextDrop + (long) (boost - 1) * interval;
	}

	/**
	 * True once when prayer drains to the threshold or below (not just for logging in
	 * with little prayer, or never using it).
	 */
	public boolean onPrayer(int points, int threshold)
	{
		int before = lastPrayer;
		lastPrayer = points;
		if (points > threshold)
		{
			prayerArmed = true;
			return false;
		}
		if (prayerArmed && threshold > 0 && before > points)
		{
			prayerArmed = false;
			return true;
		}
		return false;
	}

	/** True once when the cannon's balls run down to the threshold or below. */
	public boolean onCannonballs(int balls, int threshold, boolean placed)
	{
		int before = lastCannonballs;
		lastCannonballs = balls;
		if (!placed || balls > threshold)
		{
			cannonArmed = balls > threshold || !placed;
			return false;
		}
		if (cannonArmed && before > balls)
		{
			cannonArmed = false;
			return true;
		}
		return false;
	}

	public void reset()
	{
		lastBoost.clear();
		lastDivine.clear();
		boostArmed.clear();
		lastDecayTick = Integer.MIN_VALUE;
		prayerArmed = true;
		lastPrayer = -1;
		lastCannonballs = -1;
		cannonArmed = true;
	}
}

package com.gildedledger.tracking;

import com.gildedledger.data.GpSession;
import com.gildedledger.data.SourceCategory;
import com.gildedledger.data.SourceRecord;
import com.gildedledger.data.SupplyLine;
import com.gildedledger.data.TrackerData;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.UUID;
import java.util.function.IntToLongFunction;
import java.util.function.LongSupplier;

/**
 * GP/hour sessions. Start, pause, resume and end; while running, whatever every source
 * gains or spends counts towards the session. Each running stretch is measured by
 * comparing every source's totals at its start and end, so a pause leaves out
 * everything that happens during it.
 */
public class SessionTracker
{
	private final Ledger ledger;
	/** The price used for loot (GE, or 0 for most untradeables). */
	private final IntToLongFunction lootPrice;
	private final LongSupplier clock;

	public SessionTracker(Ledger ledger, IntToLongFunction lootPrice, LongSupplier clock)
	{
		this.ledger = ledger;
		this.lootPrice = lootPrice;
		this.clock = clock;
	}

	public GpSession active()
	{
		return ledger.data().activeSession;
	}

	public void start()
	{
		if (active() != null)
		{
			return;
		}
		long now = clock.getAsLong();
		GpSession session = new GpSession();
		session.id = UUID.randomUUID().toString();
		session.startedMillis = now;
		session.runningSinceMillis = now;
		takeStretchStart(session);
		ledger.data().activeSession = session;
		ledger.changed();
	}

	public void pause()
	{
		GpSession session = active();
		if (session == null || !session.isRunning())
		{
			return;
		}
		closeStretch(session, true);
		ledger.changed();
	}

	public void resume()
	{
		GpSession session = active();
		if (session == null || session.isRunning())
		{
			return;
		}
		session.runningSinceMillis = clock.getAsLong();
		takeStretchStart(session);
		ledger.changed();
	}

	/** Ends the session and files it in the log. */
	public void end()
	{
		GpSession session = active();
		if (session == null)
		{
			return;
		}
		if (session.isRunning())
		{
			closeStretch(session, true);
		}
		session.endedMillis = clock.getAsLong();
		session.title = titleFor(session);
		session.stretchStart.clear();
		session.stretchLoot.clear();
		session.stretchSupplies.clear();
		ledger.data().sessionLog.add(0, session);
		ledger.data().activeSession = null;
		ledger.changed();
	}

	/**
	 * After loading a saved session that was running (the client closed mid-session),
	 * keep what it booked but not the time the client was closed.
	 */
	public void pauseAfterRestart()
	{
		GpSession session = active();
		if (session != null && session.isRunning())
		{
			// Count the time up to when the client was last seen running, not the time it was closed.
			if (session.lastSeenMillis > session.runningSinceMillis)
			{
				session.activeMillis += session.lastSeenMillis - session.runningSinceMillis;
			}
			closeStretch(session, false);
			ledger.changed();
		}
	}

	/** Called every game tick: remembers that the session was still running now. */
	public void heartbeat()
	{
		GpSession session = active();
		if (session != null && session.isRunning())
		{
			session.lastSeenMillis = clock.getAsLong();
		}
	}

	/** The session as it stands right now, the running stretch included. */
	public GpSession live()
	{
		GpSession session = active();
		if (session == null)
		{
			return null;
		}
		GpSession view = new GpSession();
		view.id = session.id;
		view.startedMillis = session.startedMillis;
		view.activeMillis = session.activeMillis;
		view.runningSinceMillis = session.runningSinceMillis;
		view.profit = session.profit;
		view.xp = session.xp;
		session.activity.forEach((key, a) ->
			view.activity.put(key, new GpSession.Activity(a.name, a.category, a.count, a.profit, a.xp)));
		view.loot.putAll(session.loot);
		session.supplies.forEach((key, line) -> view.supplies.put(key, copy(line)));
		if (session.isRunning())
		{
			addStretch(view, session.stretchStart, snapshot());
			addItems(view, session.stretchLoot, session.stretchSupplies);
		}
		view.title = titleFor(view);
		return view;
	}

	public void rename(String id, String title)
	{
		for (GpSession session : ledger.data().sessionLog)
		{
			if (session.id.equals(id) && title != null && !title.trim().isEmpty())
			{
				session.title = title.trim();
				session.renamed = true;
				ledger.changed();
				return;
			}
		}
	}

	public void delete(String id)
	{
		if (ledger.data().sessionLog.removeIf(s -> s.id.equals(id)))
		{
			ledger.changed();
		}
	}

	public void clearLog()
	{
		ledger.data().sessionLog.clear();
		ledger.changed();
	}

	// ---------------------------------------------------------------- measuring

	private void closeStretch(GpSession session, boolean countTime)
	{
		if (countTime)
		{
			session.activeMillis += Math.max(0, clock.getAsLong() - session.runningSinceMillis);
		}
		addStretch(session, session.stretchStart, snapshot());
		addItems(session, session.stretchLoot, session.stretchSupplies);
		session.runningSinceMillis = 0;
		session.stretchStart = new HashMap<>();
		session.stretchLoot = new HashMap<>();
		session.stretchSupplies = new HashMap<>();
	}

	private void takeStretchStart(GpSession session)
	{
		session.stretchStart = snapshot();
		session.stretchLoot = allLoot();
		session.stretchSupplies = allSupplies();
	}

	/** Adds the items gained and used since the stretch began (an item dropped again counts back off). */
	private void addItems(GpSession session, Map<Integer, Long> lootBefore, Map<String, SupplyLine> suppliesBefore)
	{
		allLoot().forEach((id, qty) ->
		{
			long gained = qty - lootBefore.getOrDefault(id, 0L);
			if (gained != 0)
			{
				session.loot.merge(id, gained, Long::sum);
			}
		});
		session.loot.values().removeIf(q -> q <= 0);
		allSupplies().forEach((key, line) ->
		{
			SupplyLine was = suppliesBefore.get(key);
			long qty = line.quantity - (was == null ? 0 : was.quantity);
			long gp = line.gp - (was == null ? 0 : was.gp);
			if (qty > 0)
			{
				SupplyLine total = session.supplies.computeIfAbsent(key, k -> new SupplyLine(line.itemId, line.name, line.unit));
				total.quantity += qty;
				total.gp += gp;
			}
		});
	}

	/** Every source's loot added together, by item. */
	private Map<Integer, Long> allLoot()
	{
		Map<Integer, Long> all = new HashMap<>();
		for (SourceRecord record : ledger.data().sources.values())
		{
			record.loot.forEach((id, qty) -> all.merge(id, qty, Long::sum));
		}
		return all;
	}

	/** Every source's supplies added together, by supply line. */
	private Map<String, SupplyLine> allSupplies()
	{
		Map<String, SupplyLine> all = new HashMap<>();
		for (SourceRecord record : ledger.data().sources.values())
		{
			record.supplies.forEach((key, line) ->
			{
				SupplyLine total = all.computeIfAbsent(key, k -> new SupplyLine(line.itemId, line.name, line.unit));
				total.quantity += line.quantity;
				total.gp += line.gp;
			});
		}
		return all;
	}

	private static SupplyLine copy(SupplyLine line)
	{
		SupplyLine c = new SupplyLine(line.itemId, line.name, line.unit);
		c.quantity = line.quantity;
		c.gp = line.gp;
		return c;
	}

	/** Adds what changed between two snapshots to the session. Sources reset meanwhile are skipped. */
	private static void addStretch(GpSession session, Map<String, GpSession.Activity> before,
		Map<String, GpSession.Activity> after)
	{
		for (Map.Entry<String, GpSession.Activity> e : after.entrySet())
		{
			GpSession.Activity now = e.getValue();
			GpSession.Activity was = before.get(e.getKey());
			long count = now.count - (was == null ? 0 : was.count);
			long profit = now.profit - (was == null ? 0 : was.profit);
			long xp = now.xp - (was == null ? 0 : was.xp);
			if (count < 0 || xp < 0)
			{
				// The source was reset during the stretch: nothing sensible to add.
				continue;
			}
			if (count == 0 && profit == 0 && xp == 0)
			{
				continue;
			}
			session.profit += profit;
			session.xp += xp;
			GpSession.Activity total = session.activity.computeIfAbsent(e.getKey(),
				k -> new GpSession.Activity(now.name, now.category, 0, 0, 0));
			total.count += count;
			total.profit += profit;
			total.xp += xp;
		}
	}

	private Map<String, GpSession.Activity> snapshot()
	{
		Map<String, GpSession.Activity> snapshot = new HashMap<>();
		for (SourceRecord record : ledger.data().sources.values())
		{
			long xp = record.xp.values().stream().mapToLong(Long::longValue).sum();
			snapshot.put(record.key, new GpSession.Activity(record.name, record.category, record.count,
				record.lootValue(lootPrice) - record.supplyCost(), xp));
		}
		return snapshot;
	}

	// ---------------------------------------------------------------- naming

	/** The session's name: what was done most, e.g. "Blood rune crafting" or "Karambwan fishing". */
	static String titleFor(GpSession session)
	{
		if (session.renamed && session.title != null)
		{
			return session.title;
		}
		return session.activity.entrySet().stream()
			.filter(e -> e.getValue().category != SourceCategory.TELEPORTS
				&& e.getValue().category != SourceCategory.GENERAL_SUPPLIES)
			.max(Comparator.comparingLong((Map.Entry<String, GpSession.Activity> e) -> e.getValue().count)
				.thenComparingLong(e -> Math.abs(e.getValue().profit))
				.thenComparingLong(e -> e.getValue().xp))
			.map(e ->
			{
				GpSession.Activity a = e.getValue();
				if (e.getKey().startsWith("reward:"))
				{
					return a.name;
				}
				if (e.getKey().startsWith("other:"))
				{
					return a.category.getLabel();
				}
				return activityTitle(a.name, a.category);
			})
			.orElse("Session");
	}

	/** "Blood altar" + Runecrafting → "Blood rune crafting"; "Karambwan" + Fishing → "Karambwan fishing". */
	public static String activityTitle(String name, SourceCategory category)
	{
		if (name == null || category == null)
		{
			return "Session";
		}
		String n = name.trim();
		String lower = n.toLowerCase(Locale.ENGLISH);
		switch (category)
		{
			case COMBAT:
				return n;
			case RUNECRAFTING:
				if (lower.endsWith(" altar") && !lower.startsWith("ourania") && !lower.startsWith("dark"))
				{
					return n.substring(0, n.length() - " altar".length()) + " rune crafting";
				}
				return n + " runecrafting";
			case WOODCUTTING:
				return strip(n, " logs") + " woodcutting";
			case MINING:
				return lower.contains("motherlode") ? n : strip(strip(n, " rocks"), " ore") + " mining";
			case HUNTER:
				return n + " hunting";
			case MAGIC:
				return n;
			case OTHER:
				return n;
			default:
				return n + " " + category.getLabel().toLowerCase(Locale.ENGLISH);
		}
	}

	private static String strip(String s, String suffix)
	{
		return s.toLowerCase(Locale.ENGLISH).endsWith(suffix) ? s.substring(0, s.length() - suffix.length()) : s;
	}

	/** For tests and the plugin: the data the sessions live in. */
	TrackerData data()
	{
		return ledger.data();
	}
}

package com.gildedledger.tracking;

import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * How skilling actions are grouped in the panel:
 * <ul>
 *   <li>Runecrafting by altar ("Death altar"); anything that isn't an altar's rune is "Other".</li>
 *   <li>Fishing by the fish a spot gives ("Trout &amp; salmon", "Karambwanji").</li>
 *   <li>Mining by rock or vein ("Iron rocks", "Gem rocks").</li>
 *   <li>Hunter by the creature caught ("Red chinchompa", "Crimson swift").</li>
 *   <li>Herblore by potion, whatever the dose ("Prayer potion"), or by herb when cleaning.</li>
 * </ul>
 */
public final class SkillGroups
{
	public static final String OTHER = "Other";
	public static final String MOTHERLODE = "Motherlode Mine";
	public static final String VALE_TOTEMS = "Vale Totems";

	private static final Set<String> ALTAR_RUNES = Set.of(
		"air", "mind", "water", "earth", "fire", "body", "cosmic", "chaos", "astral", "nature", "law", "death",
		"blood", "soul", "wrath");

	/** Combination runes and the two altars they can be made at. */
	private static final Map<String, String[]> COMBINATION_RUNES = Map.of(
		"mist", new String[]{"air", "water"},
		"dust", new String[]{"air", "earth"},
		"mud", new String[]{"water", "earth"},
		"smoke", new String[]{"air", "fire"},
		"steam", new String[]{"water", "fire"},
		"lava", new String[]{"earth", "fire"});

	private static final Map<String, String> FISH_GROUPS = Map.ofEntries(
		Map.entry("shrimps", "Shrimps & anchovies"), Map.entry("anchovies", "Shrimps & anchovies"),
		Map.entry("sardine", "Sardine & herring"), Map.entry("herring", "Sardine & herring"),
		Map.entry("trout", "Trout & salmon"), Map.entry("salmon", "Trout & salmon"),
		Map.entry("tuna", "Tuna & swordfish"), Map.entry("swordfish", "Tuna & swordfish"),
		Map.entry("mackerel", "Mackerel, cod & bass"), Map.entry("cod", "Mackerel, cod & bass"),
		Map.entry("bass", "Mackerel, cod & bass"),
		Map.entry("leaping trout", "Barbarian fishing"), Map.entry("leaping salmon", "Barbarian fishing"),
		Map.entry("leaping sturgeon", "Barbarian fishing"));

	private static final Map<String, String> HUNTER_ITEMS = Map.ofEntries(
		Map.entry("red feather", "Crimson swift"), Map.entry("yellow feather", "Golden warbler"),
		Map.entry("orange feather", "Copper longtail"), Map.entry("blue feather", "Cerulean twitch"),
		Map.entry("stripy feather", "Tropical wagtail"),
		Map.entry("chinchompa", "Grey chinchompa"),
		Map.entry("polar kebbit fur", "Polar kebbit"), Map.entry("common kebbit fur", "Common kebbit"),
		Map.entry("feldip weasel fur", "Feldip weasel"), Map.entry("desert devil fur", "Desert devil"),
		Map.entry("spotted kebbit fur", "Spotted kebbit"), Map.entry("dark kebbit fur", "Dark kebbit"),
		Map.entry("dashing kebbit fur", "Dashing kebbit"), Map.entry("tatty larupia fur", "Spined larupia"),
		Map.entry("larupia fur", "Spined larupia"), Map.entry("tatty graahk fur", "Horned graahk"),
		Map.entry("graahk fur", "Horned graahk"), Map.entry("tatty kyatt fur", "Sabre-toothed kyatt"),
		Map.entry("kyatt fur", "Sabre-toothed kyatt"), Map.entry("swamp lizard", "Swamp lizard"),
		Map.entry("orange salamander", "Orange salamander"), Map.entry("red salamander", "Red salamander"),
		Map.entry("black salamander", "Black salamander"), Map.entry("tecu salamander", "Tecu salamander"));

	private SkillGroups()
	{
	}

	/**
	 * The altar a craft happened at.
	 *
	 * @param madeNames    every item made in the action
	 * @param runesUsed    names of runes used up (a combination rune's altar is the element <i>not</i> used)
	 */
	public static String runecraftingAltar(Collection<String> madeNames, Collection<String> runesUsed)
	{
		long runeTypes = madeNames.stream().filter(n -> lower(n).endsWith(" rune")).count();
		if (runeTypes > 1)
		{
			// Several kinds of rune at once: the Ourania (ZMI) altar.
			return "Ourania altar";
		}
		for (String made : madeNames)
		{
			String altar = altarFor(made, runesUsed);
			if (!OTHER.equals(altar))
			{
				return altar;
			}
		}
		return OTHER;
	}

	/** The altar for one item made, or "Other". */
	public static String altarFor(String made, Collection<String> runesUsed)
	{
		String n = lower(made);
		if (n.startsWith("dark essence"))
		{
			return "Dark altar";
		}
		String element = null;
		if (n.endsWith(" rune"))
		{
			element = n.substring(0, n.length() - " rune".length()).trim();
		}
		else if (n.endsWith(" tiara"))
		{
			element = n.substring(0, n.length() - " tiara".length()).trim();
		}
		if (element == null)
		{
			return OTHER;
		}
		if (ALTAR_RUNES.contains(element))
		{
			return ItemRules.capitalize(element) + " altar";
		}
		String[] pair = COMBINATION_RUNES.get(element);
		if (pair != null && runesUsed != null)
		{
			boolean usedFirst = runesUsed.stream().anyMatch(r -> lower(r).equals(pair[0] + " rune"));
			boolean usedSecond = runesUsed.stream().anyMatch(r -> lower(r).equals(pair[1] + " rune"));
			if (usedFirst != usedSecond)
			{
				return ItemRules.capitalize(usedFirst ? pair[1] : pair[0]) + " altar";
			}
		}
		return OTHER;
	}

	/** Mist, dust, mud, smoke, steam and lava runes. */
	public static boolean isCombinationRune(String name)
	{
		String n = lower(name);
		return n.endsWith(" rune") && COMBINATION_RUNES.containsKey(n.substring(0, n.length() - " rune".length()));
	}

	/** Is this a fish (rather than a casket or seaweed from the same spot)? */
	public static boolean isFish(String name)
	{
		String n = lower(name);
		return n.startsWith("raw ") || n.startsWith("leaping ") || n.equals("karambwanji") || n.equals("minnow")
			|| n.endsWith(" eel") || n.equals("frog spawn");
	}

	/** "Raw trout" and "Raw salmon" → "Trout &amp; salmon"; "Raw karambwanji" → "Karambwanji". */
	public static String fishGroup(String fishName)
	{
		String n = lower(fishName);
		if (n.startsWith("raw "))
		{
			n = n.substring(4);
		}
		String group = FISH_GROUPS.get(n);
		return group != null ? group : ItemRules.capitalize(n);
	}

	/**
	 * The rock or vein mined: the object's name when it has a useful one ("Iron rocks"),
	 * otherwise worked out from the ore.
	 */
	public static String miningRock(String targetName, String oreName)
	{
		String t = lower(targetName);
		if (t.equals("ore vein") || t.equals("depleted vein"))
		{
			return MOTHERLODE;
		}
		if (!t.isEmpty() && !t.equals("rocks") && !t.equals("rock"))
		{
			return ItemRules.capitalize(t);
		}
		return rockFromOre(oreName);
	}

	/** An altar group name ("Death altar", "Ourania altar", "Other"), as opposed to an item. */
	public static boolean isAltarGroup(String name)
	{
		String n = lower(name);
		return n.endsWith(" altar") || n.equals(lower(OTHER));
	}

	/** An ore or gem name, as opposed to a rock group like "Iron rocks". */
	public static boolean isOre(String name)
	{
		String n = lower(name);
		return n.endsWith(" ore") || n.equals("coal") || n.equals("clay") || n.startsWith("uncut ")
			|| n.equals("pay-dirt") || n.equals("ore vein") || n.startsWith("granite (") || n.startsWith("sandstone (") || n.equals("amethyst");
	}

	/** "Iron ore" → "Iron rocks", "Uncut ruby" → "Gem rocks", "Pay-dirt" → "Ore vein". */
	public static String rockFromOre(String oreName)
	{
		String n = lower(oreName);
		if (n.isEmpty())
		{
			return OTHER;
		}
		if (n.startsWith("uncut "))
		{
			return "Gem rocks";
		}
		if (n.equals("pay-dirt") || n.equals("ore vein"))
		{
			return MOTHERLODE;
		}
		if (n.startsWith("granite ("))
		{
			return "Granite rocks";
		}
		if (n.startsWith("sandstone ("))
		{
			return "Sandstone rocks";
		}
		if (n.equals("amethyst"))
		{
			return "Amethyst crystals";
		}
		if (n.endsWith(" ore"))
		{
			n = n.substring(0, n.length() - " ore".length());
		}
		return ItemRules.capitalize(n) + " rocks";
	}

	/** Trap objects, which aren't the creature. */
	public static boolean isTrap(String targetName)
	{
		String t = lower(targetName);
		return t.contains("trap") || t.contains("snare") || t.contains("box") || t.contains("net")
			|| t.contains("deadfall") || t.contains("pitfall") || t.contains("boulder") || t.contains("birdhouse")
			|| t.contains("young tree") || t.contains("bird house");
	}

	/** The creature behind a Hunter item: "Red feather" → "Crimson swift", "Baby impling jar" → "Baby impling". */
	public static String creatureFromItem(String itemName)
	{
		String n = lower(itemName);
		if (n.isEmpty())
		{
			return OTHER;
		}
		String creature = HUNTER_ITEMS.get(n);
		if (creature != null)
		{
			return creature;
		}
		if (n.endsWith(" jar"))
		{
			return ItemRules.capitalize(n.substring(0, n.length() - " jar".length()));
		}
		return ItemRules.capitalize(n);
	}

	/** "You've caught a crimson swift." → "Crimson swift". */
	public static String creatureFromMessage(String message)
	{
		if (message == null)
		{
			return null;
		}
		java.util.regex.Matcher m = CAUGHT.matcher(message.trim());
		return m.matches() ? ItemRules.capitalize(m.group(1).trim().toLowerCase(Locale.ENGLISH)) : null;
	}

	private static final java.util.regex.Pattern CAUGHT = java.util.regex.Pattern.compile(
		"You(?:'ve| have)? (?:caught|catch) (?:an? |the |some )?(.+?)[.!]?", java.util.regex.Pattern.CASE_INSENSITIVE);

	/**
	 * The item a gathering message says you got, as candidate item names (best first):
	 * "You catch some shrimps." → [Raw shrimps, Shrimps, Raw shrimp, Shrimp];
	 * "You get some yew logs." → [Yew logs]; "You just found a Ruby!" → [Uncut ruby].
	 * Empty if it isn't one. Used for catches that go straight into a fish barrel,
	 * log basket or gem bag, which never show up in the inventory.
	 */
	public static List<String> caughtItemNames(String message)
	{
		if (message == null)
		{
			return Collections.emptyList();
		}
		String m = message.trim();
		java.util.regex.Matcher fish = CATCH_FISH.matcher(m);
		if (fish.matches())
		{
			String x = fish.group(1).trim().toLowerCase(Locale.ENGLISH);
			String one = x.endsWith("s") ? x.substring(0, x.length() - 1) : x;
			return List.of(ItemRules.capitalize("raw " + x), ItemRules.capitalize(x),
				ItemRules.capitalize("raw " + one), ItemRules.capitalize(one));
		}
		java.util.regex.Matcher logs = GET_LOGS.matcher(m);
		if (logs.matches())
		{
			return List.of(ItemRules.capitalize(logs.group(1).trim().toLowerCase(Locale.ENGLISH)));
		}
		java.util.regex.Matcher gem = FOUND_GEM.matcher(m);
		if (gem.matches())
		{
			return List.of("Uncut " + gem.group(1).trim().toLowerCase(Locale.ENGLISH));
		}
		return Collections.emptyList();
	}

	private static final java.util.regex.Pattern CATCH_FISH = java.util.regex.Pattern.compile(
		"You catch (?:a |an |some )(.+?)[.!]", java.util.regex.Pattern.CASE_INSENSITIVE);
	private static final java.util.regex.Pattern GET_LOGS = java.util.regex.Pattern.compile(
		"You get some (.*?logs)\\b.*", java.util.regex.Pattern.CASE_INSENSITIVE);
	private static final java.util.regex.Pattern FOUND_GEM = java.util.regex.Pattern.compile(
		"You just (?:found|mined) (?:a |an )(.+?)!", java.util.regex.Pattern.CASE_INSENSITIVE);

	/** Messages saying a catch was burnt or smelted straight away (infernal tools), so it wasn't kept. */
	public static boolean isDestroyedCatch(String message)
	{
		String m = lower(message);
		return m.contains("incinerat") || m.contains("burn") || m.contains("smelt") || m.contains("infernal");
	}

	/** "Prayer potion(3)" → "Prayer potion"; a cleaned herb keeps its name. */
	public static String herblore(String itemName)
	{
		return ItemRules.withoutDoses(itemName);
	}

	private static String lower(String s)
	{
		return s == null ? "" : s.toLowerCase(Locale.ENGLISH).trim();
	}
}

package com.gildedledger.tracking;

import com.gildedledger.data.SourceCategory;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/** Which menu options start which kind of skilling, matched on the option text. */
public final class SkillRules
{
	private static final Map<String, String> FISHING_METHODS = Map.ofEntries(
		Map.entry("lure", "Fly fishing"),
		Map.entry("bait", "Bait fishing"),
		Map.entry("net", "Net fishing"),
		Map.entry("small net", "Net fishing"),
		Map.entry("big net", "Big net fishing"),
		Map.entry("cage", "Cage fishing"),
		Map.entry("harpoon", "Harpoon fishing"),
		Map.entry("use-rod", "Barbarian fishing"),
		Map.entry("fish", "Fishing"));

	/** Clicking a station with one of these options processes items. */
	private static final Set<String> PROCESS_OBJECT_OPTIONS = Set.of(
		"cook", "smelt", "smith", "spin", "weave", "craft", "form", "fire", "bake", "tan", "make", "fletch",
		"craft-rune", "bind", "offer", "pray-at", "build");

	/** Inventory item options that process the item directly. */
	private static final Set<String> PROCESS_ITEM_OPTIONS = Set.of("clean", "light", "crush", "grind", "bury", "scatter");

	private SkillRules()
	{
	}

	/** Gathering category for an option on a game object, or null. */
	public static SourceCategory gatherFromObject(String option)
	{
		String o = normalize(option);
		if (o.equals("chop down") || o.equals("chop") || o.equals("cut"))
		{
			return SourceCategory.WOODCUTTING;
		}
		if (o.equals("mine"))
		{
			return SourceCategory.MINING;
		}
		if (o.equals("steal-from") || o.equals("steal from"))
		{
			return SourceCategory.THIEVING;
		}
		if (FISHING_METHODS.containsKey(o))
		{
			return SourceCategory.FISHING;
		}
		return null;
	}

	/** Gathering category for an option on an NPC, or null. */
	public static SourceCategory gatherFromNpc(String option)
	{
		String o = normalize(option);
		if (FISHING_METHODS.containsKey(o))
		{
			return SourceCategory.FISHING;
		}
		if (o.equals("pickpocket"))
		{
			return SourceCategory.THIEVING;
		}
		if (o.equals("catch"))
		{
			return SourceCategory.HUNTER;
		}
		return null;
	}

	/** Fishing spots share a name, so fishing sources are named by method. */
	public static String fishingMethod(String option)
	{
		return FISHING_METHODS.getOrDefault(normalize(option), ItemRules.capitalize(normalize(option)));
	}

	public static boolean isProcessingObjectOption(String option)
	{
		return PROCESS_OBJECT_OPTIONS.contains(normalize(option));
	}

	public static boolean isProcessingItemOption(String option)
	{
		return PROCESS_ITEM_OPTIONS.contains(normalize(option));
	}

	/**
	 * A teleport spell in the spellbook, including diary-unlocked alternatives:
	 * "Cast" on Varrock Teleport, but also its "Grand Exchange" option, Camelot's
	 * "Seers'", Watchtower's "Yanille" and so on.
	 */
	public static boolean isTeleportSpell(String option, String target)
	{
		String o = normalize(option);
		return normalize(target).contains("teleport") && !o.isEmpty() && !o.equals("examine")
			&& !o.equals("autocast") && !o.equals("use");
	}

	/** Display name for a teleport spell: "Varrock Teleport" or "Varrock Teleport (Grand Exchange)". */
	public static String teleportSpellName(String option, String target)
	{
		String spell = target == null ? "Teleport" : target.trim();
		String o = normalize(option);
		return o.equals("cast") ? spell : spell + " (" + option.trim() + ")";
	}

	/**
	 * Options on objects and NPCs that are never skilling. Anything else gets a
	 * watch: if it gives XP (e.g. "Tend-to" on a Forester's campfire) it is tracked,
	 * and so is an item conversion done through an NPC or its dialogue (Talk-to the
	 * sawmill operator). Plain buying and selling are filtered out later.
	 */
	private static final Set<String> NOT_SKILLING = Set.of(
		"attack", "bank", "collect", "open", "close", "shut",
		"climb", "climb-up", "climb-down", "enter", "exit", "leave", "pass", "pass-through",
		"go-through", "cross", "jump", "jump-over", "jump-up", "jump-on", "balance", "leap",
		"vault", "hurdle", "squeeze-through", "walk-across", "walk-on", "swing-on", "grab",
		"teleport", "travel", "examine", "follow", "walk here", "exchange", "pay", "deposit",
		"use", "dismiss", "pick-up", "take", "search", "read", "look-at", "check",
		"history", "rewards", "loot", "claim", "board", "disembark", "quick-travel", "configure");

	public static boolean couldGiveSkillingXp(String option)
	{
		String o = normalize(option);
		return !o.isEmpty() && !NOT_SKILLING.contains(o);
	}

	/** Filling or emptying an essence or rune pouch only moves items around. */
	public static boolean isPouchShuffle(String itemName, String option)
	{
		return bagContents(itemName) != null && isBagOption(option);
	}

	private static boolean isBagOption(String option)
	{
		String o = normalize(option);
		return o.equals("fill") || o.equals("empty") || o.equals("deposit") || o.startsWith("empty ")
			|| o.equals("withdraw") || o.equals("take");
	}

	/**
	 * What a carried bag holds, as a test on item names, or null if this isn't a bag.
	 * Moving items between the bag and the inventory is never loot or a cost.
	 */
	public static java.util.function.Predicate<String> bagContents(String bagName)
	{
		String n = bagName == null ? "" : bagName.toLowerCase(Locale.ENGLISH);
		if (n.equals("rune pouch") || n.startsWith("rune pouch") || n.startsWith("divine rune pouch"))
		{
			return name -> ItemRules.isRune(name, true);
		}
		if (n.matches("(small|medium|large|giant|colossal) pouch.*"))
		{
			return name -> name.toLowerCase(Locale.ENGLISH).contains("essence");
		}
		if (n.contains("fish barrel") || n.contains("fish sack barrel"))
		{
			return SkillGroups::isFish;
		}
		if (n.contains("log basket") || n.contains("forestry basket"))
		{
			return name -> name.toLowerCase(Locale.ENGLISH).endsWith("logs");
		}
		if (n.contains("gem bag"))
		{
			return name -> name.toLowerCase(Locale.ENGLISH).startsWith("uncut ");
		}
		if (n.contains("herb sack"))
		{
			return name -> name.toLowerCase(Locale.ENGLISH).startsWith("grimy ");
		}
		if (n.contains("seed box"))
		{
			String[] seedy = {" seed", " seeds", " sapling", " spore", "acorn"};
			return name ->
			{
				String l = name.toLowerCase(Locale.ENGLISH);
				for (String suffix : seedy)
				{
					if (l.endsWith(suffix))
					{
						return true;
					}
				}
				return false;
			};
		}
		if (n.contains("coal bag"))
		{
			return name -> name.equalsIgnoreCase("coal") || name.toLowerCase(Locale.ENGLISH).endsWith(" ore");
		}
		return null;
	}

	private static String normalize(String option)
	{
		return option == null ? "" : option.trim().toLowerCase(Locale.ENGLISH);
	}
}

package com.gildedledger.tracking;

import com.gildedledger.data.SourceCategory;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Tracks everything that isn't combat, farming or a purchase. Every action is
 * filed under the skill that gave it the most XP; actions that give no XP at all
 * (combining crystal key halves, making unfinished potions) go to Processing.
 *
 * <ul>
 *   <li><b>Gathering</b>: clicking a tree, rock, fishing spot, stall or pickpocket
 *       target. Items gained are loot; stackable consumables used up (bait,
 *       feathers) are costs. Named after the target.</li>
 *   <li><b>Processing</b>: using an item on an item or on a station, or Clean,
 *       Light, Craft-rune and similar. Items used up are costs, items made are
 *       loot. Named after the main product.</li>
 *   <li><b>Anything else that gives XP</b>: clicking some other object or NPC
 *       (tending a Forester's campfire, for example). Only booked once XP arrives,
 *       so doors, ladders and shop counters never show up. Named after the object
 *       or NPC.</li>
 * </ul>
 *
 * An inventory change and the XP for it can land a tick apart, so a change with
 * no XP is held for one tick before deciding where it belongs. Any unrelated click
 * (walking, an NPC, a bank, a farming patch) ends the session.
 */
public class SkillingTracker
{
	static final int IDLE_TICKS = 100;
	static final int MAX_DISTANCE = 15;
	/** Lighting a fire removes the log a few ticks before the XP lands; wait this long for it. */
	static final int XP_WAIT_TICKS = 10;
	private static final int COINS = 995;

	private enum Mode
	{
		NONE, GATHERING, PROCESSING, OTHER
	}

	private final Ledger ledger;
	private final ItemInfo items;

	private Mode mode = Mode.NONE;
	private SourceCategory targetCategory;
	private String targetName;
	private TileKey targetTile;
	private int lastActivityTick;
	private String lastKey;
	/** The spell behind the current processing action, if it is one. */
	private String actionSpell;
	private String lastName;
	private SourceCategory lastCategory;
	private int lastBookedTick = Integer.MIN_VALUE / 2;

	/** Told about every action booked (so a boost drunk just before it can join it). */
	public interface ActionListener
	{
		void onAction(String key, String name, SourceCategory category);
	}

	private ActionListener actionListener = (key, name, category) -> { };

	public void setActionListener(ActionListener listener)
	{
		actionListener = listener;
	}
	private int lastTotemTick = Integer.MIN_VALUE / 2;
	/** Fletching within 5 minutes of using a Vale totem is for the totems. */
	static final int VALE_TOTEM_TICKS = 500;
	/** Items gained within this many ticks after an action, with no XP of their own, are part of it. */
	static final int TRAILING_GAIN_TICKS = 3;

	private final Map<Integer, Integer> tickChanges = new HashMap<>();
	private final Map<String, Long> tickXp = new HashMap<>();
	private final List<SupplyTracker.Use> tickSupplies = new ArrayList<>();

	/** Changes from the previous tick that came with no XP, waiting to see if XP follows. */
	/** XP with no items for this long after the last item change isn't the action's: it's "Other". */
	static final int XP_FOLLOW_TICKS = 5;
	private int lastItemTick = Integer.MIN_VALUE / 2;
	/** The group (fish, rock...) this session's catches go to, once known. */
	private String sessionGroup;
	private String pendingCreature;
	private int pendingCreatureTick = Integer.MIN_VALUE / 2;
	private int currentTick;
	private final Map<String, Long> pendingOtherXp = new HashMap<>();
	/** Fishing bait used before the session's first catch. */
	private final Map<Integer, Integer> earlyChanges = new HashMap<>();
	private final List<SupplyTracker.Use> earlySupplies = new ArrayList<>();
	private final Map<String, Long> earlyXp = new HashMap<>();
	/** Catches named in chat this tick (item → count). */
	private final Map<Integer, Integer> caughtThisTick = new HashMap<>();
	private int destroyedCatchTick = Integer.MIN_VALUE / 2;

	private final Map<Integer, Integer> heldChanges = new HashMap<>();
	private final List<SupplyTracker.Use> heldSupplies = new ArrayList<>();
	private int heldSinceTick;

	public SkillingTracker(Ledger ledger, ItemInfo items)
	{
		this.ledger = ledger;
		this.items = items;
	}

	/** The player clicked a gathering target, e.g. "Chop down" on a Yew tree. */
	public void onGatherClicked(SourceCategory category, String name, TileKey target, int tick)
	{
		if (category == null || name == null)
		{
			return;
		}
		flushHeld();
		lastKey = null;
		sessionGroup = null;
		mode = Mode.GATHERING;
		targetCategory = category;
		targetName = name;
		targetTile = target;
		lastActivityTick = tick;
	}

	/** The player started a processing action. */
	public void onProcessClicked(int tick)
	{
		onProcessClicked(tick, null);
	}

	/**
	 * The player started a processing action.
	 *
	 * @param spell the spell, when it's a spell (alching, Superglass Make): Magic is filed by spell
	 */
	public void onProcessClicked(int tick, String spell)
	{
		if (mode != Mode.PROCESSING)
		{
			flushHeld();
			lastKey = null;
			sessionGroup = null;
		}
		mode = Mode.PROCESSING;
		actionSpell = spell;
		lastActivityTick = tick;
	}

	/** Any other object or NPC; tracked only if it turns out to give XP. */
	public void onOtherTargetClicked(String name, TileKey target, int tick)
	{
		if (name == null)
		{
			onOtherAction();
			return;
		}
		flushHeld();
		lastKey = null;
		sessionGroup = null;
		mode = Mode.OTHER;
		targetName = name;
		targetTile = target;
		lastActivityTick = tick;
	}

	/** Anything that isn't part of the current skilling action. */
	public void onOtherAction()
	{
		flushHeld();
		mode = Mode.NONE;
	}

	public boolean isActive()
	{
		return mode != Mode.NONE;
	}

	public void onInventoryChanged(InventoryDiff diff)
	{
		if (mode != Mode.NONE)
		{
			diff.changes().forEach((id, delta) -> tickChanges.merge(id, delta, Integer::sum));
		}
	}

	public void onXp(String skill, long amount)
	{
		if (mode != Mode.NONE && amount > 0)
		{
			tickXp.merge(skill, amount, Long::sum);
		}
	}

	/** Food, potions, runes and so on used while skilling (e.g. runes for alching). */
	public boolean onSupplyUsed(SupplyTracker.Use use)
	{
		if (mode == Mode.NONE)
		{
			return false;
		}
		tickSupplies.add(use);
		return true;
	}

	/** XP from no action at all, such as a minigame's reward: the skill's "Other". */
	public void bookOtherXp(String skill, long amount)
	{
		SourceCategory category = SourceCategory.forSkill(skill);
		if (category == null || amount <= 0)
		{
			return;
		}
		ledger.addXp(otherKey(category), SkillGroups.OTHER, category, skill, amount);
	}

	public static String otherKey(SourceCategory category)
	{
		return "other:" + category.name();
	}

	/**
	 * Game messages: "You've caught a crimson swift." names the creature a trap caught,
	 * and "You catch a trout." / "You get some yew logs." / "You just found a Ruby!"
	 * name a catch, which counts even when it went straight into a fish barrel, log
	 * basket or gem bag instead of the inventory.
	 */
	public void onChatMessage(String message, int tick)
	{
		if (SkillGroups.isDestroyedCatch(message))
		{
			destroyedCatchTick = tick;
		}
		if (mode == Mode.GATHERING)
		{
			for (String name : SkillGroups.caughtItemNames(message))
			{
				int id = items.idByName(name);
				if (id > 0)
				{
					caughtThisTick.merge(id, 1, Integer::sum);
					break;
				}
			}
		}
		String creature = SkillGroups.creatureFromMessage(message);
		if (creature != null)
		{
			pendingCreature = creature;
			pendingCreatureTick = tick;
		}
	}

	/**
	 * A catch the game announced that never reached the inventory went into a fish
	 * barrel, log basket or gem bag: count it as if it had.
	 */
	private void addCatchesInBags(int tick)
	{
		if (mode == Mode.GATHERING && tick - destroyedCatchTick > 0)
		{
			caughtThisTick.forEach((id, count) ->
			{
				int gained = Math.max(0, tickChanges.getOrDefault(id, 0));
				if (gained < count)
				{
					tickChanges.merge(id, count - gained, Integer::sum);
				}
			});
		}
		caughtThisTick.clear();
	}

	/**
	 * XP in a tick with nothing gained or used, a while after the action last changed
	 * any items, isn't that action's (a minigame reward, for one): it goes to Other,
	 * unless items follow on the next tick.
	 */
	private boolean isLoneXp(int tick)
	{
		return !tickXp.isEmpty() && tickChanges.isEmpty() && tickSupplies.isEmpty()
			&& heldChanges.isEmpty() && heldSupplies.isEmpty() && tick - lastItemTick > XP_FOLLOW_TICKS;
	}

	public void onGameTick(int tick, TileKey playerTile)
	{
		currentTick = tick;
		addCatchesInBags(tick);
		boolean itemsThisTick = !tickChanges.isEmpty() || !tickSupplies.isEmpty();
		if (!pendingOtherXp.isEmpty())
		{
			// Last tick's lone XP: if items turned up now, it was this action's after all.
			if (itemsThisTick)
			{
				pendingOtherXp.forEach((skill, xp) -> tickXp.merge(skill, xp, Long::sum));
			}
			else
			{
				pendingOtherXp.forEach(this::bookOtherXp);
			}
			pendingOtherXp.clear();
		}
		if (itemsThisTick)
		{
			lastItemTick = tick;
		}
		if (mode != Mode.NONE && isLoneXp(tick))
		{
			pendingOtherXp.putAll(tickXp);
			tickXp.clear();
		}
		if (mode == Mode.GATHERING)
		{
			resolveGathering(tick);
		}
		else if (mode == Mode.PROCESSING)
		{
			resolveProcessing(tick);
		}
		else if (mode == Mode.OTHER)
		{
			resolveOther(tick);
		}
		tickChanges.clear();
		tickXp.clear();
		tickSupplies.clear();

		boolean idle = tick - lastActivityTick > IDLE_TICKS;
		boolean walkedAway = (mode == Mode.GATHERING || mode == Mode.OTHER)
			&& targetTile != null && playerTile != null && targetTile.distanceTo(playerTile) > MAX_DISTANCE;
		if (mode != Mode.NONE && (idle || walkedAway))
		{
			onOtherAction();
		}
	}

	public void reset()
	{
		mode = Mode.NONE;
		tickChanges.clear();
		tickXp.clear();
		tickSupplies.clear();
		heldChanges.clear();
		heldSupplies.clear();
		sessionGroup = null;
		pendingCreature = null;
		pendingOtherXp.clear();
		clearEarly();
	}

	// ---------------------------------------------------------------- gathering

	private void resolveGathering(int tick)
	{
		// Drift net fishing gives Fishing and Hunter XP: it goes wherever more XP went.
		SourceCategory bySkill = SourceCategory.forSkill(topSkill(tickXp));
		if (bySkill != null)
		{
			targetCategory = bySkill;
		}
		if (!tickChanges.isEmpty() || !tickXp.isEmpty() || !tickSupplies.isEmpty())
		{
			if (targetCategory == SourceCategory.FISHING && sessionGroup == null && !caughtFish(tickChanges))
			{
				// Bait used before the first catch: we don't know the fish yet, so keep it
				// until we do (a karambwanji used on a karambwan spot belongs to Karambwan).
				tickChanges.forEach((id, delta) -> earlyChanges.merge(id, delta, Integer::sum));
				earlySupplies.addAll(tickSupplies);
				tickXp.forEach((skill, xp) -> earlyXp.merge(skill, xp, Long::sum));
				lastActivityTick = tick;
				return;
			}
			Map<Integer, Integer> changes = new HashMap<>(tickChanges);
			List<SupplyTracker.Use> supplies = new ArrayList<>(tickSupplies);
			Map<String, Long> xp = new HashMap<>(tickXp);
			earlyChanges.forEach((id, delta) -> changes.merge(id, delta, Integer::sum));
			supplies.addAll(earlySupplies);
			earlyXp.forEach((skill, amount) -> xp.merge(skill, amount, Long::sum));
			clearEarly();
			bookAction(changes, supplies, xp, targetCategory, true);
			lastActivityTick = tick;
		}
	}

	private boolean caughtFish(Map<Integer, Integer> changes)
	{
		return changes.entrySet().stream().anyMatch(e -> e.getValue() > 0 && SkillGroups.isFish(items.name(e.getKey())));
	}

	/** The session ended before any fish was caught: book the bait under the spot as before. */
	private void flushEarly()
	{
		if (earlyChanges.isEmpty() && earlySupplies.isEmpty() && earlyXp.isEmpty())
		{
			return;
		}
		Map<Integer, Integer> changes = new HashMap<>(earlyChanges);
		List<SupplyTracker.Use> supplies = new ArrayList<>(earlySupplies);
		Map<String, Long> xp = new HashMap<>(earlyXp);
		clearEarly();
		bookAction(changes, supplies, xp, SourceCategory.FISHING, true);
	}

	private void clearEarly()
	{
		earlyChanges.clear();
		earlySupplies.clear();
		earlyXp.clear();
	}

	// ---------------------------------------------------------------- other XP actions

	private void resolveOther(int tick)
	{
		SourceCategory bySkill = SourceCategory.forSkill(topSkill(tickXp));
		if (bySkill == null)
		{
			// No XP yet: hold the changes in case XP follows. If none comes, an item
			// conversion (logs and coins into planks at the sawmill) is Processing.
			holdWithoutXp(tick);
			return;
		}
		bookAction(merged(), mergedSupplies(), tickXp, bySkill, false);
		lastActivityTick = tick;
		heldChanges.clear();
		heldSupplies.clear();
	}

	/**
	 * Books one action. Skills are split by item, not by how you did it: Oak logs
	 * burned with a tinderbox, on a campfire or at a Forester's campfire all land on
	 * "Oak logs"; runecrafting splits into Death rune, Blood rune and so on. Thieving
	 * is the exception and is split by NPC or stall.
	 *
	 * @param gathering items gained are the point; only stackable consumables
	 *                  (bait, feathers) count as costs
	 */
	private void bookAction(Map<Integer, Integer> changes, List<SupplyTracker.Use> supplies,
		Map<String, Long> xp, SourceCategory category, boolean gathering)
	{
		String name;
		String key;
		if (category == SourceCategory.THIEVING && targetName != null)
		{
			name = targetName;
			key = "target:" + category.name() + ":" + name;
		}
		else if (category == SourceCategory.MAGIC && mode == Mode.PROCESSING && actionSpell != null)
		{
			// Magic is split by spell: High Level Alchemy, Superglass Make, Plank Make...
			name = actionSpell;
			key = "spell:" + category.name() + ":" + name;
		}
		else
		{
			int item = mostValuable(changes, true);
			if (item <= 0 && !gathering)
			{
				item = mostValuable(changes, false);
			}
			String group = groupName(category, changes, gathering);
			if (group != null)
			{
				name = group;
				key = SkillGroups.OTHER.equals(group) ? otherKey(category) : "item:" + category.name() + ":" + name;
			}
			else if (item > 0)
			{
				name = items.name(item);
				key = "item:" + category.name() + ":" + name;
			}
			else if (lastKey != null && lastCategory == category)
			{
				// XP or bait only, e.g. the XP drop a tick after the catch.
				name = lastName;
				key = lastKey;
			}
			else if (targetName != null && gathering)
			{
				name = targetName;
				key = "target:" + category.name() + ":" + name;
			}
			else
			{
				return;
			}
		}
		lastKey = key;
		lastName = name;
		lastCategory = category;
		lastBookedTick = currentTick;
		actionListener.onAction(key, name, category);

		boolean gained = false;
		for (Map.Entry<Integer, Integer> change : changes.entrySet())
		{
			int id = change.getKey();
			int delta = change.getValue();
			if (delta > 0)
			{
				ledger.addLoot(key, name, category, id, delta);
				gained = true;
			}
			else if (delta < 0 && (!gathering || items.stackable(id)))
			{
				// Using up something this same entry made (a bow fletched, then offered to a
				// Vale totem) takes it back off the loot instead of costing it twice.
				long used = takeBackMadeItem(key, id, -delta);
				if (-delta - used > 0)
				{
					bookCost(key, name, category, id, -delta - used);
				}
			}
		}
		// One action, whether it made something (a bow, a log) or only used something up (a log burned).
		if (gathering ? gained : !changes.isEmpty())
		{
			ledger.incrementCount(key, name, category);
		}
		bookXpAndSupplies(key, name, category, xp, supplies);
	}

	/** Removes up to {@code quantity} of an item from an entry's loot; returns how many it removed. */
	private long takeBackMadeItem(String key, int itemId, long quantity)
	{
		com.gildedledger.data.SourceRecord record = ledger.data().sources.get(key);
		if (record == null || !record.loot.containsKey(itemId))
		{
			return 0;
		}
		long removed = record.removeLoot(itemId, quantity, ledger.now());
		if (removed > 0)
		{
			ledger.changed();
		}
		return removed;
	}

	/** A Vale totem was clicked: Fletching for the next few minutes is Vale Totems. */
	public void onValeTotemClicked(int tick)
	{
		lastTotemTick = tick;
	}

	/**
	 * The group an action belongs to for skills that are grouped by more than the item
	 * made (see {@link SkillGroups}), or null to name it after the item.
	 */
	private String groupName(SourceCategory category, Map<Integer, Integer> changes, boolean gathering)
	{
		List<String> made = new ArrayList<>();
		List<String> used = new ArrayList<>();
		changes.forEach((id, delta) -> (delta > 0 ? made : used).add(items.name(id)));
		switch (category)
		{
			case RUNECRAFTING:
				if (changes.isEmpty())
				{
					return null;
				}
				return made.isEmpty() ? SkillGroups.OTHER : SkillGroups.runecraftingAltar(made, used);
			case FISHING:
			{
				if (sessionGroup == null)
				{
					made.stream().filter(SkillGroups::isFish).findFirst()
						.ifPresent(fish -> sessionGroup = SkillGroups.fishGroup(fish));
				}
				return sessionGroup;
			}
			case MINING:
			{
				if (sessionGroup == null && (gathering || !made.isEmpty()))
				{
					String ore = made.isEmpty() ? null : made.get(0);
					String rock = SkillGroups.miningRock(gathering ? targetName : null, ore);
					sessionGroup = SkillGroups.OTHER.equals(rock) ? null : rock;
				}
				return sessionGroup;
			}
			case HUNTER:
			{
				if (currentTick - pendingCreatureTick <= 3 && pendingCreature != null)
				{
					String creature = pendingCreature;
					pendingCreature = null;
					return creature;
				}
				if (targetName != null && !SkillGroups.isTrap(targetName) && mode != Mode.PROCESSING)
				{
					// Caught by hand: the target is the creature (butterflies, implings).
					return targetName;
				}
				int best = mostValuable(changes, true);
				return best > 0 ? SkillGroups.creatureFromItem(items.name(best)) : null;
			}
			case FLETCHING:
				// Logs, bows and shields made for and given to Vale totems: one entry.
				return currentTick - lastTotemTick <= VALE_TOTEM_TICKS ? SkillGroups.VALE_TOTEMS : null;
			case HERBLORE:
			{
				int best = mostValuable(changes, true);
				return best > 0 ? SkillGroups.herblore(items.name(best)) : null;
			}
			default:
				return null;
		}
	}

	/**
	 * Renames older entries to the current grouping: runes into their altar, fish into
	 * their spot's group, ores into their rock, potions without their dose.
	 */
	public void tidyGroups()
	{
		List<com.gildedledger.data.SourceRecord> records = new ArrayList<>(ledger.data().sources.values());
		for (com.gildedledger.data.SourceRecord record : records)
		{
			if (record.key == null || !record.key.startsWith("item:") || record.name == null)
			{
				continue;
			}
			String group;
			switch (record.category)
			{
				case RUNECRAFTING:
					// Only old per-rune entries; altars (and Other) are already grouped.
					group = SkillGroups.isAltarGroup(record.name) ? null : SkillGroups.altarFor(record.name, null);
					break;
				case FISHING:
					group = SkillGroups.isFish(record.name) ? SkillGroups.fishGroup(record.name) : null;
					break;
				case MINING:
					// Only old per-ore entries; rocks and veins are already grouped.
					group = SkillGroups.isOre(record.name) ? SkillGroups.rockFromOre(record.name) : null;
					break;
				case HUNTER:
					group = SkillGroups.creatureFromItem(record.name);
					break;
				case HERBLORE:
					group = SkillGroups.herblore(record.name);
					break;
				default:
					group = null;
			}
			if (group == null || group.equals(record.name))
			{
				continue;
			}
			String key = SkillGroups.OTHER.equals(group)
				? otherKey(record.category) : "item:" + record.category.name() + ":" + group;
			ledger.mergeInto(record.key, key, group);
		}
	}

	// ---------------------------------------------------------------- processing

	private void resolveProcessing(int tick)
	{
		SourceCategory bySkill = SourceCategory.forSkill(topSkill(tickXp));
		boolean tickHasItems = !tickChanges.isEmpty() || !tickSupplies.isEmpty();
		if (tickHasItems || !tickXp.isEmpty())
		{
			lastActivityTick = tick;
		}

		if (bySkill != null && actionSpell != null && tickXp.containsKey("Magic"))
		{
			// A spell is Magic even when it also gives other XP (Superglass Make gives Crafting XP).
			bySkill = SourceCategory.MAGIC;
		}
		if (bySkill != null)
		{
			// XP arrived: this tick's changes plus any held from last tick belong to that skill.
			bookAction(merged(), mergedSupplies(), tickXp, bySkill, false);
			heldChanges.clear();
			heldSupplies.clear();
			return;
		}

		// No XP yet. Keep the changes until XP arrives; if none comes in time it's plain Processing.
		holdWithoutXp(tick);
	}

	/** Books held no-XP processing changes as Processing; held "other" changes are dropped. */
	private void holdWithoutXp(int tick)
	{
		boolean holding = !heldChanges.isEmpty() || !heldSupplies.isEmpty();
		if (holding && tick - heldSinceTick > XP_WAIT_TICKS)
		{
			flushHeld();
			holding = false;
		}
		if (!tickChanges.isEmpty() || !tickSupplies.isEmpty())
		{
			if (!holding)
			{
				heldSinceTick = tick;
			}
			tickChanges.forEach((id, delta) -> heldChanges.merge(id, delta, Integer::sum));
			heldChanges.values().removeIf(v -> v == 0);
			heldSupplies.addAll(tickSupplies);
		}
	}

	/**
	 * Settles changes that never got XP. A processing action is always Processing.
	 * For anything else clicked (an NPC or object), only a real conversion counts:
	 * items went in and different items came out (logs into planks at the sawmill,
	 * venator shards into dragon arrowtips), a coin fee included. Buying with coins
	 * or selling for coins is never tracked.
	 */
	private void flushHeld()
	{
		flushEarly();
		boolean held = !heldChanges.isEmpty() || !heldSupplies.isEmpty();
		if (held && lastKey != null && heldSupplies.isEmpty() && onlyGains(heldChanges)
			&& heldSinceTick - lastBookedTick <= TRAILING_GAIN_TICKS)
		{
			// Extra items right after an action with no XP of their own, like Runecrafting
			// bonus runes (Raiments of the Eye, abyssal lantern): part of that action.
			heldChanges.forEach((id, delta) ->
				ledger.addLoot(lastKey, lastName, lastCategory, id, delta));
			heldChanges.clear();
			return;
		}
		if (held && (mode == Mode.PROCESSING || (mode == Mode.OTHER && isConversion(heldChanges))))
		{
			bookAction(new HashMap<>(heldChanges), new ArrayList<>(heldSupplies),
				new HashMap<>(), SourceCategory.PROCESSING, false);
		}
		heldChanges.clear();
		heldSupplies.clear();
	}

	private static boolean onlyGains(Map<Integer, Integer> changes)
	{
		return !changes.isEmpty() && changes.values().stream().allMatch(v -> v > 0);
	}

	private boolean isConversion(Map<Integer, Integer> changes)
	{
		boolean itemsMade = false;
		boolean itemsUsed = false;
		for (Map.Entry<Integer, Integer> change : changes.entrySet())
		{
			if (ItemRules.isCurrency(items.name(change.getKey())))
			{
				continue;
			}
			itemsMade |= change.getValue() > 0;
			itemsUsed |= change.getValue() < 0;
		}
		return itemsMade && itemsUsed;
	}

	// ---------------------------------------------------------------- helpers

	private Map<Integer, Integer> merged()
	{
		Map<Integer, Integer> all = new HashMap<>(heldChanges);
		tickChanges.forEach((id, delta) -> all.merge(id, delta, Integer::sum));
		all.values().removeIf(v -> v == 0);
		return all;
	}

	private List<SupplyTracker.Use> mergedSupplies()
	{
		List<SupplyTracker.Use> all = new ArrayList<>(heldSupplies);
		all.addAll(tickSupplies);
		return all;
	}

	private static String topSkill(Map<String, Long> xp)
	{
		String best = null;
		long bestXp = 0;
		for (Map.Entry<String, Long> entry : xp.entrySet())
		{
			if (entry.getValue() > bestXp)
			{
				best = entry.getKey();
				bestXp = entry.getValue();
			}
		}
		return best;
	}

	/** Item with the largest total value among gains (or losses); coins only if nothing else changed. */
	private int mostValuable(Map<Integer, Integer> changes, boolean gains)
	{
		int best = -1;
		long bestValue = -1;
		for (Map.Entry<Integer, Integer> change : changes.entrySet())
		{
			int delta = change.getValue();
			if (gains ? delta <= 0 : delta >= 0)
			{
				continue;
			}
			int id = change.getKey();
			if (items.canonical(id) == COINS && changes.size() > 1)
			{
				continue;
			}
			long value = items.marketPrice(id) * Math.abs(delta);
			if (value > bestValue)
			{
				best = id;
				bestValue = value;
			}
		}
		return best;
	}

	private void bookXpAndSupplies(String key, String name, SourceCategory category,
		Map<String, Long> xp, List<SupplyTracker.Use> supplies)
	{
		for (Map.Entry<String, Long> entry : xp.entrySet())
		{
			ledger.addXp(key, name, category, entry.getKey(), entry.getValue());
		}
		for (SupplyTracker.Use use : supplies)
		{
			ledger.addSupply(key, name, category, use.lineKey, use.itemId, use.lineName, use.unit, use.quantity, use.gp);
		}
	}

	private void bookCost(String key, String name, SourceCategory category, int itemId, long quantity)
	{
		ledger.addSupply(key, name, category, String.valueOf(itemId), itemId, items.name(itemId), null,
			quantity, items.marketPrice(itemId) * quantity);
	}
}

package com.gildedledger.tracking;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;

/**
 * Confirms supply use before charging for it, so clicking "Eat" on a full
 * health bar or banking runes never counts.
 *
 * <ul>
 *   <li>Potions, food and teleports: an Eat/Drink/Break/Read click, then that
 *       item's inventory count dropping within a few ticks.</li>
 *   <li>Runes: runes leaving the inventory or rune pouch in the same tick as
 *       Magic XP or right after a Cast click.</li>
 * </ul>
 * Cannonballs and ammunition are confirmed by the plugin from varps and the
 * equipment container and passed straight to {@link #recordDirect}.
 */
public class SupplyTracker
{
	static final int CONSUME_WINDOW_TICKS = 3;
	static final int CAST_WINDOW_TICKS = 2;

	public enum Kind
	{
		POTION, FOOD, TELEPORT, RUNE, CANNONBALL, AMMO,
		/** Charges used by weapons and armour that hold their own (tridents, blowpipe, serpentine helm). */
		CHARGES
	}

	/** One confirmed use, priced and ready to be booked to a source. */
	public static final class Use
	{
		public final Kind kind;
		public final int itemId;
		public final String lineKey;
		public final String lineName;
		public final String unit;
		public final long quantity;
		public final long gp;
		/** The teleport this was spent on (tablet name or spell name), or null. */
		public final String teleport;
		/** True for the one line that should count as a single use (one cast, one tablet). */
		public final boolean countsAsUse;

		Use(Kind kind, int itemId, String lineKey, String lineName, String unit, long quantity, long gp)
		{
			this(kind, itemId, lineKey, lineName, unit, quantity, gp, null, true);
		}

		Use(Kind kind, int itemId, String lineKey, String lineName, String unit, long quantity, long gp,
			String teleport, boolean countsAsUse)
		{
			this.teleport = teleport;
			this.countsAsUse = countsAsUse;
			this.kind = kind;
			this.itemId = itemId;
			this.lineKey = lineKey;
			this.lineName = lineName;
			this.unit = unit;
			this.quantity = quantity;
			this.gp = gp;
		}
	}

	@FunctionalInterface
	public interface Sink
	{
		void accept(Use use);
	}

	private static final class Pending
	{
		final int countBefore;
		final int tick;
		final Kind kind;

		Pending(int countBefore, int tick, Kind kind)
		{
			this.countBefore = countBefore;
			this.tick = tick;
			this.kind = kind;
		}
	}

	private final ItemInfo items;
	private final Sink sink;
	private final Map<Integer, Pending> pending = new HashMap<>();
	private final Map<Integer, Integer> tickRuneLoss = new HashMap<>();
	/** Runes that left the rune pouch this tick, and those no spell used (for Runecrafting). */
	private final Map<Integer, Integer> tickPouchLoss = new HashMap<>();
	private final Map<Integer, Integer> unusedPouchRunes = new HashMap<>();
	private int lastCastTick = Integer.MIN_VALUE / 2;
	private int lastTeleportCastTick = Integer.MIN_VALUE / 2;
	private String lastTeleportSpell;
	private boolean magicXpThisTick;

	public SupplyTracker(ItemInfo items, Sink sink)
	{
		this.items = items;
		this.sink = sink;
	}

	public void onConsumeClicked(int itemId, Kind kind, int countBefore, int tick)
	{
		if (itemId > 0 && countBefore > 0)
		{
			pending.put(itemId, new Pending(countBefore, tick, kind));
		}
	}

	/**
	 * Checks pending clicks against the new inventory.
	 *
	 * @return ids of the items confirmed as eaten, drunk or broken this change
	 */
	public List<Integer> onInventoryChanged(IntUnaryOperator countOf, int tick)
	{
		List<Integer> confirmed = new ArrayList<>();
		Iterator<Map.Entry<Integer, Pending>> it = pending.entrySet().iterator();
		while (it.hasNext())
		{
			Map.Entry<Integer, Pending> entry = it.next();
			int itemId = entry.getKey();
			Pending p = entry.getValue();
			if (tick - p.tick > CONSUME_WINDOW_TICKS)
			{
				it.remove();
				continue;
			}
			if (countOf.applyAsInt(itemId) < p.countBefore)
			{
				it.remove();
				sink.accept(priceConsumable(itemId, p.kind));
				confirmed.add(itemId);
			}
		}
		return confirmed;
	}

	public void onCastClicked(int tick)
	{
		lastCastTick = tick;
	}

	/** A teleport spell was cast from the spellbook; its runes belong to Teleports. */
	public void onTeleportCast(String spellName, int tick)
	{
		lastCastTick = tick;
		lastTeleportCastTick = tick;
		lastTeleportSpell = spellName;
	}

	public void onMagicXp()
	{
		magicXpThisTick = true;
	}

	public void onRunesLost(int runeItemId, int quantity)
	{
		if (quantity > 0)
		{
			tickRuneLoss.merge(runeItemId, quantity, Integer::sum);
		}
	}

	/**
	 * Runes taken from the rune pouch. A spell's runes are booked as usual; runes no spell
	 * used (combination runecrafting draws its elemental runes from the pouch) are left for
	 * {@link #takeUnusedPouchRunes()}.
	 */
	public void onPouchRunesLost(int runeItemId, int quantity)
	{
		onRunesLost(runeItemId, quantity);
		if (quantity > 0)
		{
			tickPouchLoss.merge(runeItemId, quantity, Integer::sum);
		}
	}

	/** Rune pouch runes used this tick by something other than a spell. */
	public Map<Integer, Integer> takeUnusedPouchRunes()
	{
		Map<Integer, Integer> runes = new HashMap<>(unusedPouchRunes);
		unusedPouchRunes.clear();
		return runes;
	}

	/** A charge of something worn, priced per use (a binding necklace's 16 charges). */
	public static Use charge(int itemId, String lineKey, String lineName, String unit, long quantity, long gp)
	{
		return new Use(Kind.CHARGES, itemId, lineKey, lineName, unit, quantity, gp);
	}

	/** Books this tick's rune losses if a spell was cast, then resets per-tick state. */
	public void onGameTick(int tick)
	{
		boolean cast = magicXpThisTick || tick - lastCastTick <= CAST_WINDOW_TICKS;
		boolean teleport = tick - lastTeleportCastTick <= CAST_WINDOW_TICKS && lastTeleportSpell != null;
		if (cast)
		{
			boolean first = true;
			for (Map.Entry<Integer, Integer> loss : tickRuneLoss.entrySet())
			{
				int id = loss.getKey();
				int qty = loss.getValue();
				sink.accept(new Use(teleport ? Kind.TELEPORT : Kind.RUNE, id, String.valueOf(id), items.name(id), null, qty,
					items.marketPrice(id) * qty, teleport ? lastTeleportSpell : null, first));
				first = false;
			}
			if (teleport && !tickRuneLoss.isEmpty())
			{
				lastTeleportSpell = null;
			}
		}
		if (!cast)
		{
			tickPouchLoss.forEach((id, qty) -> unusedPouchRunes.merge(id, qty, Integer::sum));
		}
		tickPouchLoss.clear();
		tickRuneLoss.clear();
		magicXpThisTick = false;
		pending.values().removeIf(p -> tick - p.tick > CONSUME_WINDOW_TICKS);
	}

	/** For supplies confirmed elsewhere (cannonballs, ammo). */
	public void recordDirect(Kind kind, int itemId, long quantity)
	{
		if (quantity > 0)
		{
			sink.accept(new Use(kind, itemId, String.valueOf(itemId), items.name(itemId), null, quantity,
				items.marketPrice(itemId) * quantity));
		}
	}

	public void reset()
	{
		pending.clear();
		tickRuneLoss.clear();
		magicXpThisTick = false;
	}

	Use priceConsumable(int itemId, Kind kind)
	{
		String name = items.name(itemId);
		long price = items.marketPrice(itemId);
		if (kind == Kind.POTION)
		{
			String base = ItemRules.withoutDoses(name);
			return new Use(kind, itemId, "potion:" + base, base, "doses", 1, ItemRules.perDoseValue(price, name));
		}
		if (kind == Kind.TELEPORT)
		{
			return new Use(kind, itemId, String.valueOf(itemId), name, null, 1, price, name, true);
		}
		return new Use(kind, itemId, String.valueOf(itemId), name, null, 1, price);
	}
}

package com.gildedledger.tracking;

import java.util.Objects;

/** A world tile, kept free of RuneLite types so the drop logic is unit-testable. */
public final class TileKey
{
	public final int x;
	public final int y;
	public final int plane;

	public TileKey(int x, int y, int plane)
	{
		this.x = x;
		this.y = y;
		this.plane = plane;
	}

	/** Chebyshev distance, matching how OSRS measures "adjacent"; different planes are infinitely far. */
	public int distanceTo(TileKey other)
	{
		if (other == null || other.plane != plane)
		{
			return Integer.MAX_VALUE;
		}
		return Math.max(Math.abs(other.x - x), Math.abs(other.y - y));
	}

	public String pack()
	{
		return x + "," + y + "," + plane;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof TileKey))
		{
			return false;
		}
		TileKey other = (TileKey) o;
		return x == other.x && y == other.y && plane == other.plane;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(x, y, plane);
	}

	@Override
	public String toString()
	{
		return "(" + pack() + ")";
	}
}

package com.gildedledger.ui;

import java.awt.Font;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import net.runelite.client.ui.FontManager;

/**
 * The fonts the panel draws with, picked in the plugin's settings: RuneLite's RuneScape
 * fonts, a font already on the computer (Arial, Times New Roman, Courier New), or one of
 * the open-licence fonts that come with the plugin (see fonts/licenses).
 */
public final class Fonts
{
	/** Fonts packed with the plugin: family → {regular file, bold file or null, size scale}. */
	private static final Map<String, Object[]> BUNDLED = Map.of(
		"Pixelify Sans", new Object[]{"PixelifySans.ttf", null, 1.0f},
		"Silkscreen", new Object[]{"Silkscreen-Regular.ttf", "Silkscreen-Bold.ttf", 0.85f},
		"VT323", new Object[]{"VT323-Regular.ttf", null, 1.3f},
		"Roboto Condensed", new Object[]{"RobotoCondensed.ttf", null, 1.0f},
		"Barlow Semi Condensed", new Object[]{"BarlowSemiCondensed-Regular.ttf", "BarlowSemiCondensed-Bold.ttf", 1.05f},
		"IBM Plex Sans", new Object[]{"IBMPlexSans.ttf", null, 0.95f},
		"Source Sans 3", new Object[]{"SourceSans3-Regular.ttf", "SourceSans3-Bold.ttf", 1.05f},
		"JetBrains Mono", new Object[]{"JetBrainsMono.ttf", null, 0.9f},
		"Cinzel", new Object[]{"Cinzel.ttf", null, 0.95f});

	private static final Map<String, Font> LOADED = new HashMap<>();

	/** "RuneScape", "RuneScape (larger)", a font on the computer, or a bundled family. */
	private static String family = "RuneScape";

	private Fonts()
	{
	}

	/** Must be set before the panel is built. */
	public static void use(String fontFamily)
	{
		family = fontFamily == null ? "RuneScape" : fontFamily;
	}

	private static boolean runescape()
	{
		return family.startsWith("RuneScape");
	}

	private static float scale()
	{
		Object[] bundled = BUNDLED.get(family);
		return bundled == null ? 1f : (Float) bundled[2];
	}

	/** Labels, numbers and notes. */
	public static Font small()
	{
		if (family.equals("RuneScape"))
		{
			return FontManager.getRunescapeSmallFont();
		}
		if (runescape())
		{
			return FontManager.getRunescapeFont();
		}
		return font(false, 12f * scale());
	}

	/** Titles and profit figures. */
	public static Font bold()
	{
		return runescape() ? FontManager.getRunescapeBoldFont() : font(true, 12f * scale());
	}

	/** Big headline numbers (total profit, the session clock). */
	public static Font bold(float size)
	{
		return runescape() ? FontManager.getRunescapeBoldFont().deriveFont(size) : font(true, size * 0.8f * scale());
	}

	/**
	 * A font that can draw these characters: the given one if it can, otherwise the
	 * standard font at the same size (several fonts have no ▸ or ▾ arrows).
	 */
	public static Font thatCanShow(Font font, String text)
	{
		return font.canDisplayUpTo(text) == -1 ? font : new Font(Font.DIALOG, font.getStyle(), font.getSize());
	}

	private static Font font(boolean bold, float size)
	{
		Object[] bundled = BUNDLED.get(family);
		if (bundled == null)
		{
			// A font on the computer (Java falls back to a standard font if it isn't installed).
			return new Font(family, bold ? Font.BOLD : Font.PLAIN, Math.round(size));
		}
		String file = bold && bundled[1] != null ? (String) bundled[1] : (String) bundled[0];
		Font base = load(file);
		if (base == null)
		{
			return new Font(Font.SANS_SERIF, bold ? Font.BOLD : Font.PLAIN, Math.round(size));
		}
		// A family without its own bold file is made bold by Java.
		int style = bold && bundled[1] == null ? Font.BOLD : Font.PLAIN;
		return base.deriveFont(style, size);
	}

	private static synchronized Font load(String file)
	{
		return LOADED.computeIfAbsent(file, f ->
		{
			try (InputStream in = Fonts.class.getResourceAsStream("/com/gildedledger/fonts/" + f))
			{
				if (in == null)
				{
					return null;
				}
				Font font = Font.createFont(Font.TRUETYPE_FONT, in);
				// Registered so text Swing draws by family name (labels with HTML, like entry
				// names and XP bubbles) finds it too.
				java.awt.GraphicsEnvironment.getLocalGraphicsEnvironment().registerFont(font);
				return font;
			}
			catch (Exception e)
			{
				return null;
			}
		});
	}
}

