		/** Key is "sessionId\nnew title". */
		SESSION_RENAME,
		/** Key is the session id. */
		SESSION_DELETE,
		SESSION_CLEAR
	}

	private static final Color PROFIT_COLOR = ColorScheme.GRAND_EXCHANGE_PRICE;
