		JPanel box = new JPanel();
		box.setLayout(new BoxLayout(box, BoxLayout.Y_AXIS));
		box.setAlignmentX(LEFT_ALIGNMENT);

		// The header grows to fit: long names ("Insatiable mutated Bloodveld") wrap onto a second line.
		JPanel header = new FitHeightPanel(new BorderLayout(4, 0));
		header.setBackground(TITLE_BAR);
		header.setBorder(new EmptyBorder(7, 7, 7, 7));
		header.setAlignmentX(LEFT_ALIGNMENT);
		JLabel profit = new JLabel();
		profit.setFont(Fonts.bold());
		profit.setVerticalAlignment(SwingConstants.TOP);
		setProfit(profit, source.profit());
		int nameWidth = Math.max(60, CONTENT_WIDTH - 14 - 4 - 8 - profit.getPreferredSize().width);
		// Swing's HTML renders CSS pixels about a third wider than screen pixels.
		// Kill counts only mean something for monsters.
		String count = source.category == SourceCategory.COMBAT
			? "&nbsp;&nbsp;<font color='#a5a5a5'>x&nbsp;" + QuantityFormatter.formatNumber(source.count) + "</font>"
			: "";
		JLabel name = new JLabel("<html><div style='width:" + (nameWidth * 3 / 4) + "px'>" + escapeHtml(source.name)
			+ count + "</div></html>");
		name.setFont(Fonts.small());
		name.setForeground(Color.WHITE);
		name.setVerticalAlignment(SwingConstants.TOP);
		header.add(name, BorderLayout.CENTER);
		header.add(profit, BorderLayout.EAST);
		header.setToolTipText(source.category.getCountLabel() + ". Click to collapse, right-click to reset.");
		box.add(header);

		boolean open = expanded.contains(source.key);
		onPress(header, () ->
		{
			if (!expanded.remove(source.key))
			{
				expanded.add(source.key);
			}
			redraw();
		}, TITLE_BAR);
		JPopupMenu menu = new JPopupMenu();
		JMenuItem reset = new JMenuItem("Reset " + source.name);
		reset.addActionListener(e -> actions.accept(Action.RESET_SOURCE, source.key));
		menu.add(reset);
		header.setComponentPopupMenu(menu);

		if (!open)
		{
			return box;
		}

		if (!source.loot.isEmpty())
		{
			box.add(sectionLine("Loot", gp(source.lootValue), PROFIT_COLOR,
				"GE value; untradeables count as 0 (tarnished items at High Alchemy). HA total: " + gp(source.lootHa)));
			box.add(lootGrid(source.key, source.loot));
		}
		if (!source.supplies.isEmpty())
		{
			box.add(sectionLine("Supplies", gp(source.supplyGp), LOSS_COLOR, null));
			box.add(supplyGrid(source.key, source.supplies));
		}
		if (!source.xpBySkill.isEmpty())
		{
			box.add(Box.createVerticalStrut(5));
			box.add(xpBubbles(source.xpBySkill));
		}
		box.add(Box.createVerticalStrut(3));
		return box;
	}

	/** A whole non-PvM category as one table: its count, loot, supplies and XP. */
	private JPanel categoryTable(PanelModel.SourceView source)
	{
		JPanel table = new JPanel();
		table.setLayout(new BoxLayout(table, BoxLayout.Y_AXIS));
		table.setAlignmentX(LEFT_ALIGNMENT);
		if (!source.loot.isEmpty())
		{
			table.add(sectionLine("Loot", gp(source.lootValue), PROFIT_COLOR,
				"GE value; untradeables count as 0 (tarnished items at High Alchemy). HA total: " + gp(source.lootHa)));
			table.add(lootGrid(source.key, source.loot));
		}
		if (!source.supplies.isEmpty())
		{
			table.add(sectionLine("Supplies", gp(source.supplyGp), LOSS_COLOR, null));
			table.add(supplyGrid(source.key, source.supplies));
		}
		if (!source.xpBySkill.isEmpty())
		{
			table.add(Box.createVerticalStrut(5));
			table.add(xpBubbles(source.xpBySkill));
		}
		table.add(Box.createVerticalStrut(3));
		return table;
	}

	private static String countText(PanelModel.SourceView source)
	{
		return QuantityFormatter.formatNumber(source.count) + " " + source.category.getCountLabel().toLowerCase(Locale.ENGLISH);
	}

	private JPanel sectionLine(String label, String value, Color color, String tooltip)
	{
		JPanel line = row();
		line.setBorder(new EmptyBorder(6, 7, 3, 7));
		line.add(small(label, color), BorderLayout.WEST);
		line.add(small(value, color), BorderLayout.EAST);
		line.setToolTipText(tooltip);
		return line;
	}

	private JPanel lootGrid(String sourceKey, List<PanelModel.LootView> items)
	{
		JPanel grid = slotGrid(items.size());
		for (int i = 0; i < gridSlots(items.size()); i++)
		{
			if (i < items.size())
			{
				PanelModel.LootView item = items.get(i);
				grid.add(slot(item.itemId, item.quantity, lootTooltip(item), SLOT, item.excluded, sourceKey == null ? null
					: () -> actions.accept(Action.TOGGLE_LOOT, sourceKey + "\n" + item.itemId)));
			}
			else
			{
				grid.add(emptySlot(SLOT));
			}
		}
		return grid;
	}

	private JPanel supplyGrid(String sourceKey, List<PanelModel.SupplyView> supplies)
	{
		JPanel grid = slotGrid(supplies.size());
		for (int i = 0; i < gridSlots(supplies.size()); i++)
		{
			if (i < supplies.size())
			{
				PanelModel.SupplyView supply = supplies.get(i);
				grid.add(slot(supply.itemId, supply.quantity, supplyTooltip(supply), SUPPLY_SLOT, supply.excluded,
					sourceKey == null ? null
						: () -> actions.accept(Action.TOGGLE_SUPPLY, sourceKey + "\n" + supply.lineKey)));
			}
			else
			{
				grid.add(emptySlot(SUPPLY_SLOT));
			}
		}
		return grid;
	}

	private static int gridSlots(int items)
	{
		return Math.max(1, (items + ICON_COLUMNS - 1) / ICON_COLUMNS) * ICON_COLUMNS;
	}

	private static JPanel slotGrid(int items)
	{
		JPanel grid = new JPanel(new GridLayout(gridSlots(items) / ICON_COLUMNS, ICON_COLUMNS, 1, 1));
		grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
		grid.setAlignmentX(LEFT_ALIGNMENT);
		return grid;
	}

	/**
	 * One item slot. Right-click toggles whether the item counts towards profit;
	 * excluded items are drawn faded, like ignored items in the Loot Tracker.
	 */
	private JPanel slot(int itemId, long quantity, String tooltip, Color background, boolean excluded, Runnable toggle)
	{
		JPanel slot = emptySlot(background);
		JLabel icon = new JLabel();
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		icon.setVerticalAlignment(SwingConstants.CENTER);
		icon.setToolTipText(excluded ? tooltip.replace("</html>", "<br><i>Excluded from profit</i></html>") : tooltip);
		int qty = (int) Math.min(Integer.MAX_VALUE, quantity);
		AsyncBufferedImage image = itemManager.getImage(itemId, qty, qty > 1);
		if (excluded)
		{
			image.onLoaded(() -> SwingUtilities.invokeLater(() ->
				icon.setIcon(new ImageIcon(ImageUtil.alphaOffset(image, 0.3f)))));
		}
		else
		{
			image.addTo(icon);
		}
		slot.add(icon, BorderLayout.CENTER);
		if (toggle == null)
		{
			return slot;
		}

		JPopupMenu menu = new JPopupMenu();
		JMenuItem item = new JMenuItem(excluded ? "Include in profit" : "Exclude from profit");
		item.addActionListener(e -> toggle.run());
		menu.add(item);
		slot.setComponentPopupMenu(menu);
		icon.setInheritsPopupMenu(true);
		return slot;
	}

	private static JPanel emptySlot(Color background)
	{
		// BorderLayout, not the default FlowLayout: its 5px gap pushed icons down and cut off their bottom.
		JPanel slot = new JPanel(new BorderLayout());
		slot.setBackground(background);
		slot.setPreferredSize(new Dimension(36, 34));
		return slot;
	}

	/** Small rounded-looking tags, one per skill, wrapped to the panel width. */
	private static JPanel xpBubbles(Map<String, Long> xpBySkill)
	{
		JPanel rows = new JPanel();
		rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
		rows.setAlignmentX(LEFT_ALIGNMENT);
		JPanel current = null;
		int used = 0;
		for (Map.Entry<String, Long> entry : xpBySkill.entrySet())
		{
			JLabel bubble = new JLabel("<html>" + entry.getKey() + " <font color='#ffffff'>"
				+ QuantityFormatter.formatNumber(entry.getValue()) + "</font></html>");
			bubble.setFont(Fonts.small());
			bubble.setForeground(ColorScheme.TEXT_COLOR);
			bubble.setOpaque(true);
			bubble.setBackground(BUBBLE);
			bubble.setBorder(new EmptyBorder(2, 7, 2, 7));
			FontMetrics fm = bubble.getFontMetrics(bubble.getFont());
			int width = fm.stringWidth(entry.getKey() + " " + QuantityFormatter.formatNumber(entry.getValue())) + 18;
			if (current == null || used + width > CONTENT_WIDTH)
			{
				current = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
				current.setAlignmentX(LEFT_ALIGNMENT);
				current.setBorder(new EmptyBorder(0, 0, 3, 0));
				rows.add(current);
				used = 0;
			}
			if (used > 0)
			{
				current.add(Box.createHorizontalStrut(4));
			}
			current.add(bubble);
			used += width + 4;
		}
		return rows;
	}

	// ---------------------------------------------------------------- tooltips

	private static String lootTooltip(PanelModel.LootView item)
	{
		StringBuilder sb = new StringBuilder("<html>");
		sb.append(item.name).append(" x ").append(QuantityFormatter.formatNumber(item.quantity));
		if (item.itemId == ItemID.COINS)
		{
			return sb.append("</html>").toString();
		}
		if (item.tradeable)
		{
			sb.append("<br>GE: ").append(QuantityFormatter.quantityToStackSize(item.geTotal()));
			if (item.quantity > 1)
			{
				sb.append(" (").append(QuantityFormatter.quantityToStackSize(item.geEach)).append(" ea)");
			}
		}
		else
		{
			sb.append("<br>Untradeable, valued at High Alchemy");
		}
		sb.append("<br>HA: ").append(QuantityFormatter.quantityToStackSize(item.haTotal()));
		if (item.quantity > 1)
		{
			sb.append(" (").append(QuantityFormatter.quantityToStackSize(item.haEach)).append(" ea)");
		}
		return sb.append("</html>").toString();
	}

	private static String supplyTooltip(PanelModel.SupplyView supply)
	{
		String unit = supply.unit == null ? "" : " " + supply.unit;
		StringBuilder sb = new StringBuilder("<html>");
		sb.append(supply.name).append(" x ").append(QuantityFormatter.formatNumber(supply.quantity)).append(unit);
		sb.append("<br>Cost: ").append(QuantityFormatter.quantityToStackSize(supply.gp));
		if (supply.quantity > 1)
		{
			sb.append(" (").append(QuantityFormatter.quantityToStackSize(supply.gp / supply.quantity))
				.append(supply.unit == null ? " ea" : " per " + supply.unit.replaceAll("s$", "")).append(")");
		}
		return sb.append("</html>").toString();
	}

	// ---------------------------------------------------------------- helpers

	/**
	 * Toggles on mouse press rather than click: the panel redraws every tick while
	 * you're active, which would lose a click whose press and release straddle a redraw.
	 */
	private static void onPress(JPanel target, Runnable action, Color background)
	{
		target.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (e.getButton() == MouseEvent.BUTTON1)
				{
					action.run();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				target.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				target.setBackground(background);
			}
		});
	}

	private static JPanel indented(JPanel box)
	{
		JPanel wrap = new JPanel(new BorderLayout());
		wrap.setBorder(new EmptyBorder(0, 6, 0, 0));
		wrap.setAlignmentX(LEFT_ALIGNMENT);
		wrap.add(box, BorderLayout.CENTER);
		return wrap;
	}

	private static JPanel row()
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		row.setAlignmentX(LEFT_ALIGNMENT);
		return row;
	}

	private static String html(String label, String value, String valueColor)
	{
		return "<html><font color='#a5a5a5'>" + label + "</font> <font color='" + valueColor + "'>" + value + "</font></html>";
	}

	private static String gp(long value)
	{
		return QuantityFormatter.quantityToStackSize(value) + " gp";
	}

	private static void setProfit(JLabel label, long profit)
	{
		label.setText((profit > 0 ? "+" : "") + QuantityFormatter.quantityToStackSize(profit));
		label.setForeground(profit >= 0 ? PROFIT_COLOR : LOSS_COLOR);
	}

	private static JLabel small(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(Fonts.small());
		label.setForeground(color);
		return label;
	}

	private static JComponent note(String text)
	{
		javax.swing.JTextArea label = wrapping(text, ColorScheme.LIGHT_GRAY_COLOR);
		label.setBorder(new EmptyBorder(8, 2, 8, 2));
		return label;
	}

	private static String escapeHtml(String text)
	{
		return text == null ? "" : text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Stretches to the panel's width but only ever as tall as its contents need. */
	private static final class FitHeightPanel extends JPanel
	{
		FitHeightPanel(java.awt.LayoutManager layout)
		{
			super(layout);
		}

		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
		}
	}
}

package com.gildedledger.ui;

/**
 * Per-item prices for loot. The value used for profit is the Grand Exchange price.
 * Untradeable items are worth nothing, except the few that are really worth their
 * alch price (tarnished items, which polish into tradeable ones).
 */
public interface LootPrices
{
	long ge(int itemId);

	long highAlch(int itemId);

	boolean tradeable(int itemId);

	/** Untradeable items valued at their High Alchemy price anyway. */
	default boolean valuedAtAlch(int itemId)
	{
		return false;
	}

	/**
	 * GE price for tradeable items (their alch price if the GE has none); 0 for untradeable
	 * items unless {@link #valuedAtAlch} says otherwise.
	 */
	default long value(int itemId)
	{
		if (tradeable(itemId))
		{
			long ge = ge(itemId);
			return ge > 0 ? ge : highAlch(itemId);
		}
		return valuedAtAlch(itemId) ? highAlch(itemId) : 0;
	}
}

package com.gildedledger.ui;

import com.gildedledger.data.SourceCategory;
import com.gildedledger.data.SourceRecord;
import com.gildedledger.data.SupplyLine;
import com.gildedledger.data.TaskRecord;
import com.gildedledger.data.TrackerData;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;

/**
 * An immutable snapshot of the ledger with prices already applied. Built on the
 * client thread (where item lookups are allowed) and handed to Swing to draw.
 */
public final class PanelModel
{
	/** Skills in the order RuneLite's skill panel lists combat stats, then everything else. */
	private static final List<String> SKILL_ORDER = List.of(
		"Attack", "Strength", "Defence", "Ranged", "Magic", "Hitpoints", "Prayer", "Slayer",
		"Farming", "Woodcutting");

	public static final class LootView
	{
		public final int itemId;
		public final String name;
		public final long quantity;
		public final long geEach;
		public final long haEach;
		public final boolean tradeable;
		/** GE total, or HA total when untradeable. */
		public final long value;
		/** The player excluded this item from profit; shown greyed out. */
		public final boolean excluded;

		LootView(int itemId, String name, long quantity, LootPrices prices, boolean excluded)
		{
			this.excluded = excluded;
			this.itemId = itemId;
			this.name = name;
			this.quantity = quantity;
			this.geEach = prices.ge(itemId);
			this.haEach = prices.highAlch(itemId);
			this.tradeable = prices.tradeable(itemId);
			this.value = prices.value(itemId) * quantity;
		}

		public long geTotal()
		{
			return geEach * quantity;
		}

		public long haTotal()
		{
			return haEach * quantity;
		}
	}

	public static final class SupplyView
	{
		public final String lineKey;
		public final boolean excluded;
		public final int itemId;
		public final String name;
		public final long quantity;
		public final long gp;
		public final String unit;

		SupplyView(String lineKey, SupplyLine line, boolean excluded)
		{
			this.lineKey = lineKey;
			this.excluded = excluded;
			this.itemId = line.itemId;
			this.name = line.name;
			this.quantity = line.quantity;
			this.gp = line.gp;
			this.unit = line.unit;
		}
	}

	public static final class SourceView
	{
		public final String key;
		public final String name;
		public final SourceCategory category;
		public final long count;
		public final long lootValue;
		public final long lootHa;
		public final long supplyGp;
		public final long xp;
		/** Skill name → XP, in skill-panel order. */
		public final Map<String, Long> xpBySkill;
		public final List<LootView> loot;
		public final List<SupplyView> supplies;
		public final long lastUpdatedMillis;

		SourceView(SourceRecord r, List<LootView> loot, List<SupplyView> supplies)
		{
			this.key = r.key;
			this.name = r.name;
			this.category = r.category;
			this.count = r.count;
			long value = 0;
			long ha = 0;
			for (LootView item : loot)
			{
				if (!item.excluded)
				{
					value += item.value;
					ha += item.haTotal();
				}
			}
			this.lootValue = value;
			this.lootHa = ha;
			this.supplyGp = r.supplyCost();
			this.xp = r.totalXp();
			this.xpBySkill = orderedXp(r.xp);
			this.loot = loot;
			this.supplies = supplies;
			this.lastUpdatedMillis = r.lastUpdatedMillis;
		}

		public long profit()
		{
			return lootValue - supplyGp;
		}
	}

	public static final class TaskView
	{
		public final String name;
		public final String location;
		public final int remaining;
		public final int initial;
		public final long kills;
		public final long lootGp;
		public final long supplyGp;
		public final long xp;
		public final long slayerXp;
		public final boolean finished;

		TaskView(TaskRecord t)
		{
			this.name = t.taskName;
			this.location = t.location;
			this.remaining = t.remainingAmount;
			this.initial = t.initialAmount;
			this.kills = t.kills;
			this.lootGp = t.lootGp;
			this.supplyGp = t.supplyGp;
			this.xp = t.xp;
			this.slayerXp = t.slayerXp;
			this.finished = t.isFinished();
		}

		public long profit()
		{
			return lootGp - supplyGp;
		}
	}

	public final boolean ready;
	public final TaskView task;
	public final List<SourceView> sources;

	private PanelModel(boolean ready, TaskView task, List<SourceView> sources)
	{
		this.ready = ready;
		this.task = task;
		this.sources = sources;
	}

	public static PanelModel build(TrackerData data, LootPrices prices, IntFunction<String> itemName, boolean ready)
	{
		return build(data, prices, itemName, ready, false);
	}

	/**
	 * @param combineSkills show each skill as one combined table instead of one entry
	 *                      per item; PvM always keeps one entry per monster
	 */
	public static PanelModel build(TrackerData data, LootPrices prices, IntFunction<String> itemName, boolean ready,
		boolean combineSkills)
	{
		return build(data, prices, itemName, ready, combineSkills, Collections.emptySet());
	}

	/**
	 * @param hidden categories left out of the panel and its totals (still tracked)
	 */
	public static PanelModel build(TrackerData data, LootPrices prices, IntFunction<String> itemName, boolean ready,
		boolean combineSkills, java.util.Set<SourceCategory> hidden)
	{
		return build(data, prices, itemName, ready, combineSkills, r -> hidden.contains(r.category));
	}

	/**
	 * @param hidden entries left out of the panel and its totals (still tracked): hidden
	 *               skills, and untradeable plants when that setting is on
	 */
	public static PanelModel build(TrackerData data, LootPrices prices, IntFunction<String> itemName, boolean ready,
		boolean combineSkills, java.util.function.Predicate<SourceRecord> hidden)
	{
		List<SourceView> views = new ArrayList<>();
		for (SourceRecord record : displayRecords(data, combineSkills, hidden))
		{
			if (hidden.test(record))
			{
				continue;
			}
			List<LootView> loot = new ArrayList<>();
			for (Map.Entry<Integer, Long> e : record.loot.entrySet())
			{
				loot.add(new LootView(e.getKey(), itemName.apply(e.getKey()), e.getValue(), prices,
					record.excludedLoot.contains(e.getKey())));
			}
			loot.sort(Comparator.comparingLong((LootView v) -> v.value).reversed());

			List<SupplyView> supplies = new ArrayList<>();
			for (Map.Entry<String, SupplyLine> line : record.supplies.entrySet())
			{
				supplies.add(new SupplyView(line.getKey(), line.getValue(), record.excludedSupplies.contains(line.getKey())));
			}
			supplies.sort(Comparator.comparingLong((SupplyView v) -> v.gp).reversed());

			views.add(new SourceView(record, Collections.unmodifiableList(loot), Collections.unmodifiableList(supplies)));
		}
		TaskView task = data.currentTask == null ? null : new TaskView(data.currentTask);
		return new PanelModel(ready, task, Collections.unmodifiableList(views));
	}

	/** The saved records, or with skills merged into one record per category for display. */
	private static List<SourceRecord> displayRecords(TrackerData data, boolean combineSkills,
		java.util.function.Predicate<SourceRecord> hidden)
	{
		List<SourceRecord> records = new ArrayList<>();
		Map<SourceCategory, SourceRecord> combined = new EnumMap<>(SourceCategory.class);
		for (SourceRecord record : data.sources.values())
		{
			if (record.isEmpty() || (combineSkills && record.category != SourceCategory.COMBAT && hidden.test(record)))
			{
				// Hidden entries (an untradeable plant) stay out of their category's table too.
				continue;
			}
			if (!combineSkills || record.category == SourceCategory.COMBAT)
			{
				records.add(record);
				continue;
			}
			SourceRecord table = combined.get(record.category);
			if (table == null)
			{
				table = new SourceRecord(COMBINED_PREFIX + record.category.name(), record.category.getLabel(),
					record.category, Long.MAX_VALUE);
				table.lastUpdatedMillis = 0;
				combined.put(record.category, table);
				records.add(table);
			}
			table.mergeFrom(copyOf(record));
		}
		return records;
	}

	/** A deep copy, so merging for display never changes the saved records. */
	private static SourceRecord copyOf(SourceRecord r)
	{
		SourceRecord copy = new SourceRecord(r.key, r.name, r.category, r.firstSeenMillis);
		copy.count = r.count;
		copy.lastUpdatedMillis = r.lastUpdatedMillis;
		copy.loot.putAll(r.loot);
		copy.xp.putAll(r.xp);
		copy.excludedLoot.addAll(r.excludedLoot);
		copy.excludedSupplies.addAll(r.excludedSupplies);
		r.supplies.forEach((key, line) ->
		{
			SupplyLine dup = new SupplyLine(line.itemId, line.name, line.unit);
			dup.quantity = line.quantity;
			dup.gp = line.gp;
			copy.supplies.put(key, dup);
		});
		return copy;
	}

	/** Key prefix of a skill shown as one combined table. */
	public static final String COMBINED_PREFIX = "category:";

	public static Map<String, Long> orderedXp(Map<String, Long> xp)
	{
		Map<String, Long> ordered = new LinkedHashMap<>();
		for (String skill : SKILL_ORDER)
		{
			Long amount = xp.get(skill);
			if (amount != null && amount > 0)
			{
				ordered.put(skill, amount);
			}
		}
		xp.forEach((skill, amount) ->
		{
			if (!ordered.containsKey(skill) && amount != null && amount > 0)
			{
				ordered.put(skill, amount);
			}
		});
		return Collections.unmodifiableMap(ordered);
	}

	/** One session's loot and supplies, all sources together, for the session log. */
	public static final class SessionDetail
	{
		public final List<LootView> loot;
		public final List<SupplyView> supplies;
		public final long lootValue;
		public final long supplyGp;

		SessionDetail(List<LootView> loot, List<SupplyView> supplies)
		{
			this.loot = loot;
			this.supplies = supplies;
			this.lootValue = loot.stream().mapToLong(l -> l.value).sum();
			this.supplyGp = supplies.stream().mapToLong(v -> v.gp).sum();
		}
	}

	public static SessionDetail sessionDetail(com.gildedledger.data.GpSession session, LootPrices prices,
		IntFunction<String> itemName)
	{
		List<LootView> loot = new ArrayList<>();
		session.loot.forEach((id, qty) -> loot.add(new LootView(id, itemName.apply(id), qty, prices, false)));
		loot.sort(Comparator.comparingLong((LootView v) -> v.value).reversed());
		List<SupplyView> supplies = new ArrayList<>();
		session.supplies.forEach((key, line) -> supplies.add(new SupplyView(key, line, false)));
		supplies.sort(Comparator.comparingLong((SupplyView v) -> v.gp).reversed());
		return new SessionDetail(Collections.unmodifiableList(loot), Collections.unmodifiableList(supplies));
	}
}

package com.gildedledger.ui;

import com.gildedledger.data.GpSession;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Date;
import java.util.List;
import java.util.function.BiConsumer;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.QuantityFormatter;

/**
 * GP/hour sessions: the card on the main view (timer, profit, GP/hour and the
 * start / pause / resume / end buttons) and the session log view.
 */
class SessionPanel
{
	private static final Color PROFIT_COLOR = ColorScheme.GRAND_EXCHANGE_PRICE;
	private static final Color LOSS_COLOR = new Color(235, 90, 90);
	private static final String SORT_GP_HOUR = "Sort by GP/hour";
	private static final String SORT_LATEST = "Sort by latest";

	private final BiConsumer<GildedLedgerPanel.Action, String> actions;
	private final Runnable showLog;
	private final Runnable showMain;
	private final java.util.function.Consumer<GpSession> openSession;

	final JPanel card = new JPanel();
	final JPanel logView = new JPanel(new BorderLayout(0, 8));

	private final JLabel status = small("", ColorScheme.LIGHT_GRAY_COLOR);
	private final JLabel timer = new JLabel();
	private final JLabel profit = new JLabel();
	private final JLabel rate = small("", ColorScheme.LIGHT_GRAY_COLOR);
	private final JLabel title = small("", ColorScheme.LIGHT_GRAY_COLOR);
	private final JPanel stats = new JPanel();
	private final JPanel buttons = new JPanel(new GridLayout(1, 2, 4, 0));
	private final JPanel logList = new JPanel();
	private final JComboBox<String> sort = new JComboBox<>(new String[]{SORT_GP_HOUR, SORT_LATEST});

	private GpSession live;
	private List<GpSession> log = new ArrayList<>();
	/** Which buttons are showing, so they're only rebuilt when that changes. */
	private String buttonState = "";

	SessionPanel(BiConsumer<GildedLedgerPanel.Action, String> actions, Runnable showLog, Runnable showMain,
		java.util.function.Consumer<GpSession> openSession)
	{
		this.actions = actions;
		this.openSession = openSession;
		this.showLog = showLog;
		this.showMain = showMain;
		buildCard();
		buildLogView();
		// The clock ticks every second while a session runs.
		new Timer(1000, e -> tick()).start();
	}

	// ---------------------------------------------------------------- the card

	private void buildCard()
	{
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new EmptyBorder(8, 10, 8, 10));
		card.setAlignmentX(JPanel.LEFT_ALIGNMENT);

		JPanel head = row();
		head.add(small("GP/hour session", ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.WEST);
		head.add(status, BorderLayout.EAST);
		card.add(head);

		stats.setLayout(new BoxLayout(stats, BoxLayout.Y_AXIS));
		stats.setOpaque(false);
		stats.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		JPanel clock = row();
		timer.setFont(Fonts.bold(20f));
		timer.setForeground(java.awt.Color.WHITE);
		profit.setFont(Fonts.bold());
		clock.add(timer, BorderLayout.WEST);
		clock.add(profit, BorderLayout.EAST);
		stats.add(Box.createVerticalStrut(4));
		stats.add(clock);
		JPanel detail = row();
		detail.add(title, BorderLayout.WEST);
		detail.add(rate, BorderLayout.EAST);
		stats.add(detail);
		card.add(stats);

		card.add(Box.createVerticalStrut(6));
		buttons.setOpaque(false);
		buttons.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		card.add(buttons);
		card.add(Box.createVerticalStrut(4));
		JButton seeLog = new JButton("See session log");
		seeLog.addActionListener(e -> showLog.run());
		JPanel logRow = new JPanel(new GridLayout(1, 1));
		logRow.setOpaque(false);
		logRow.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		logRow.add(seeLog);
		card.add(logRow);
		setButtons();
	}

	private void setButtons()
	{
		String state = live == null ? "none" : live.isRunning() ? "running" : "paused";
		if (state.equals(buttonState))
		{
			return;
		}
		buttonState = state;
		buttons.removeAll();
		switch (state)
		{
			case "none":
				buttons.setLayout(new GridLayout(1, 1));
				buttons.add(button("Start session", GildedLedgerPanel.Action.SESSION_START));
				break;
			case "running":
				buttons.setLayout(new GridLayout(1, 2, 4, 0));
				buttons.add(button("Pause", GildedLedgerPanel.Action.SESSION_PAUSE));
				buttons.add(button("End session", GildedLedgerPanel.Action.SESSION_END));
				break;
			default:
				buttons.setLayout(new GridLayout(1, 2, 4, 0));
				buttons.add(button("Resume", GildedLedgerPanel.Action.SESSION_RESUME));
				buttons.add(button("End session", GildedLedgerPanel.Action.SESSION_END));
		}
		buttons.revalidate();
		buttons.repaint();
	}

	private JButton button(String text, GildedLedgerPanel.Action action)
	{
		JButton b = new JButton(text);
		b.addActionListener(e -> actions.accept(action, null));
		return b;
	}

	/** Called on the Swing thread with the session as it stands, and the log. */
	void update(GpSession live, List<GpSession> log)
	{
		this.live = live;
		this.log = new ArrayList<>(log);
		setButtons();
		stats.setVisible(live != null);
		tick();
		redrawLog();
	}

	/** Refreshes the clock and GP/hour from the last numbers, once a second. */
	private void tick()
	{
		if (live == null)
		{
			status.setText("");
			return;
		}
		long active = live.activeMillis + (live.isRunning() ? Math.max(0, System.currentTimeMillis() - live.runningSinceMillis) : 0);
		timer.setText(duration(active));
		setProfit(profit, live.profit);
		long perHour = GpSession.gpPerHour(live.profit, active);
		rate.setText(QuantityFormatter.quantityToStackSize(perHour) + " gp/hr");
		rate.setForeground(perHour >= 0 ? PROFIT_COLOR : LOSS_COLOR);
		title.setText(live.title == null ? "" : live.title);
		status.setText(live.isRunning() ? "Running" : "Paused");
		status.setForeground(live.isRunning() ? PROFIT_COLOR : ColorScheme.BRAND_ORANGE);
	}

	// ---------------------------------------------------------------- the log

	private void buildLogView()
	{
		logView.setOpaque(false);
		JPanel top = new JPanel(new BorderLayout(6, 0));
		JButton back = new JButton("Back");
		back.addActionListener(e -> showMain.run());
		top.add(back, BorderLayout.WEST);
		JLabel heading = new JLabel("Session log");
		heading.setFont(Fonts.bold());
		heading.setForeground(java.awt.Color.WHITE);
		top.add(heading, BorderLayout.CENTER);

		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		top.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		header.add(top);
		header.add(Box.createVerticalStrut(6));
		sort.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		sort.addActionListener(e -> redrawLog());
		header.add(sort);

		logList.setLayout(new BoxLayout(logList, BoxLayout.Y_AXIS));

		JButton clear = new JButton("Clear log");
		clear.addActionListener(e ->
		{
			if (JOptionPane.showConfirmDialog(logView, "Delete every session in the log? This cannot be undone.",
				"Clear log", JOptionPane.YES_NO_OPTION) == JOptionPane.YES_OPTION)
			{
				actions.accept(GildedLedgerPanel.Action.SESSION_CLEAR, null);
			}
		});

		logView.add(header, BorderLayout.NORTH);
		logView.add(logList, BorderLayout.CENTER);
		logView.add(clear, BorderLayout.SOUTH);
	}

	private void redrawLog()
	{
		logList.removeAll();
		List<GpSession> sessions = new ArrayList<>(log);
		if (SORT_GP_HOUR.equals(sort.getSelectedItem()))
		{
			sessions.sort(Comparator.comparingLong((GpSession s) -> s.gpPerHour()).reversed());
		}
		else
		{
			sessions.sort(Comparator.comparingLong((GpSession s) -> s.endedMillis).reversed());
		}
		if (sessions.isEmpty())
		{
			javax.swing.JTextArea empty = GildedLedgerPanel.wrapping("No sessions yet. Start one from the main page.",
				ColorScheme.LIGHT_GRAY_COLOR);
			empty.setAlignmentX(JPanel.LEFT_ALIGNMENT);
			logList.add(empty);
		}
		for (GpSession session : sessions)
		{
			logList.add(sessionRow(session));
			logList.add(Box.createVerticalStrut(4));
		}
		logList.revalidate();
		logList.repaint();
	}

	private JPanel sessionRow(GpSession session)
	{
		JPanel box = new JPanel();
		box.setLayout(new BoxLayout(box, BoxLayout.Y_AXIS));
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(new EmptyBorder(6, 8, 6, 8));
		box.setAlignmentX(JPanel.LEFT_ALIGNMENT);

		// Name on its own line (wrapping if long), then when and how long, then profit and GP/hour,
		// so nothing overlaps on a narrow panel.
		javax.swing.JTextArea name = GildedLedgerPanel.wrapping(session.title == null ? "Session" : session.title,
			java.awt.Color.WHITE);
		name.setFont(Fonts.bold());
		box.add(name);

		JPanel second = row();
		String when = new SimpleDateFormat("MMM d, h:mm a").format(new Date(session.endedMillis));
		second.add(small(when, ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.WEST);
		second.add(small(duration(session.activeMillis), ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.EAST);
		box.add(second);

		JPanel third = row();
		JLabel total = small("", PROFIT_COLOR);
		setProfit(total, session.profit);
		third.add(total, BorderLayout.WEST);
		long perHour = session.gpPerHour();
		third.add(small(QuantityFormatter.quantityToStackSize(perHour) + " gp/hr", perHour >= 0 ? PROFIT_COLOR : LOSS_COLOR),
			BorderLayout.EAST);
		box.add(third);

		JPopupMenu menu = new JPopupMenu();
		JMenuItem rename = new JMenuItem("Rename session");
		rename.addActionListener(e ->
		{
			Object answer = JOptionPane.showInputDialog(logView, "New name for this session:", "Rename session",
				JOptionPane.PLAIN_MESSAGE, null, null, session.title);
			if (answer != null && !answer.toString().trim().isEmpty())
			{
				actions.accept(GildedLedgerPanel.Action.SESSION_RENAME, session.id + "\n" + answer.toString().trim());
			}
		});
		JMenuItem delete = new JMenuItem("Delete session");
		delete.addActionListener(e -> actions.accept(GildedLedgerPanel.Action.SESSION_DELETE, session.id));
		menu.add(rename);
		menu.add(delete);
		box.setComponentPopupMenu(menu);
		for (java.awt.Component child : box.getComponents())
		{
			((javax.swing.JComponent) child).setInheritsPopupMenu(true);
			if (child instanceof JPanel)
			{
				for (java.awt.Component label : ((JPanel) child).getComponents())
				{
					((javax.swing.JComponent) label).setInheritsPopupMenu(true);
				}
			}
		}
		box.setToolTipText("Click to see its loot and supplies; right-click to rename or delete");
		box.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
		java.awt.event.MouseAdapter open = new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseClicked(java.awt.event.MouseEvent e)
			{
				if (javax.swing.SwingUtilities.isLeftMouseButton(e))
				{
					openSession.accept(session);
				}
			}
		};
		box.addMouseListener(open);
		// The wrapping title is a text area, which takes its own clicks: pass them on.
		name.addMouseListener(open);
		name.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
		return box;
	}

	// ---------------------------------------------------------------- helpers

	/** 1:02:33, or 4:05 under an hour. */
	static String duration(long millis)
	{
		long seconds = Math.max(0, millis / 1000);
		long h = seconds / 3600;
		long m = (seconds % 3600) / 60;
		long s = seconds % 60;
		return h > 0 ? String.format("%d:%02d:%02d", h, m, s) : String.format("%d:%02d", m, s);
	}

	private static JPanel row()
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		row.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		return row;
	}

	private static JLabel small(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(Fonts.small());
		label.setForeground(color);
		return label;
	}

	private static void setProfit(JLabel label, long value)
	{
		label.setText((value > 0 ? "+" : "") + QuantityFormatter.quantityToStackSize(value) + " gp");
		label.setForeground(value >= 0 ? PROFIT_COLOR : LOSS_COLOR);
	}
}

package com.gildedledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class ChargedWeaponsTest
{
	@Test
	public void poweredStavesCostTheirRechargeRunes()
	{
		List<int[]> swamp = ChargedWeapons.costPerAttack("Trident of the swamp (e)", ChargedWeapons.POWERED_STAFF_ATTACK);
		assertEquals(4, swamp.size());
		assertTrue(swamp.stream().anyMatch(c -> c[0] == ItemID.SNAKEBOSS_SCALE && c[1] == 1));

		// The older high-level magic animation counts too.
		assertEquals(4, ChargedWeapons.costPerAttack("Trident of the swamp", ChargedWeapons.HIGH_LEVEL_MAGIC_ATTACK).size());

		List<int[]> scythe = ChargedWeapons.costPerAttack("Holy scythe of vitur", ChargedWeapons.SCYTHE_ATTACK);
		assertTrue(scythe.stream().anyMatch(c -> c[0] == ItemID.VIAL_BLOOD && c[2] == 100));
		assertEquals(1, ChargedWeapons.costPerAttack("Craw's bow", ChargedWeapons.BOW_ATTACK).size());
		assertTrue(ChargedWeapons.costPerAttack("Craw's bow (u)", ChargedWeapons.BOW_ATTACK).isEmpty());

		List<int[]> seas = ChargedWeapons.costPerAttack("Trident of the seas", ChargedWeapons.POWERED_STAFF_ATTACK);
		assertTrue(seas.stream().anyMatch(c -> c[0] == ItemID.COINS && c[1] == 10));

		List<int[]> sang = ChargedWeapons.costPerAttack("Holy sanguinesti staff", ChargedWeapons.POWERED_STAFF_ATTACK);
		assertEquals(ItemID.BLOODRUNE, sang.get(0)[0]);
		assertEquals(3, sang.get(0)[1]);

		List<int[]> shadow = ChargedWeapons.costPerAttack("Tumeken's shadow", ChargedWeapons.SHADOW_ATTACK);
		assertTrue(shadow.stream().anyMatch(c -> c[0] == ItemID.SOULRUNE && c[1] == 2));
		assertTrue(shadow.stream().anyMatch(c -> c[0] == ItemID.CHAOSRUNE && c[1] == 5));
	}

	@Test
	public void otherAnimationsAndUnchargedWeaponsCostNothing()
	{
		assertTrue(ChargedWeapons.costPerAttack("Trident of the seas", 829).isEmpty());
		assertTrue(ChargedWeapons.costPerAttack("Tumeken's shadow (uncharged)", ChargedWeapons.SHADOW_ATTACK).isEmpty());
		assertTrue(ChargedWeapons.costPerAttack("Abyssal whip", ChargedWeapons.POWERED_STAFF_ATTACK).isEmpty());
	}

	@Test
	public void blowpipeHelmsAndDarts()
	{
		assertTrue(ChargedWeapons.isBlowpipe("Toxic blowpipe"));
		assertTrue(ChargedWeapons.isBlowpipe("Blazing blowpipe"));
		assertFalse(ChargedWeapons.isBlowpipe("Toxic blowpipe (empty)"));
		assertEquals(0.20, ChargedWeapons.dartLossRate("Ava's assembler"), 1e-9);
		assertEquals(0.28, ChargedWeapons.dartLossRate("Max cape"), 1e-9);
		assertEquals(0.28, ChargedWeapons.dartLossRate("Ranging cape(t)"), 1e-9);
		assertEquals(1.0, ChargedWeapons.dartLossRate(null), 1e-9);
		assertTrue(ChargedWeapons.isScaleHelm("Serpentine helm"));
		assertFalse(ChargedWeapons.isScaleHelm("Serpentine helm (uncharged)"));
		assertEquals("Adamant dart", ChargedWeapons.dartFromCheckMessage("Darts: Adamant dart x 1,234. Scales: 5,678 (35.0%)."));
		assertNull(ChargedWeapons.dartFromCheckMessage("Darts: None. Scales: 0 (0.0%)."));
		long[] counts = ChargedWeapons.blowpipeCheckCounts("Darts: Amethyst dart x 1,234. Scales: 5,678 (35.0%).");
		assertEquals(1234, counts[0]);
		assertEquals(5678, counts[1]);
		assertEquals(0, ChargedWeapons.blowpipeCheckCounts("Darts: None. Scales: 12 (0.1%).")[0]);
		assertNull(ChargedWeapons.blowpipeCheckCounts("You eat the shark."));
	}
}

package com.gildedledger;

import com.gildedledger.tracking.ItemInfo;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/** In-memory item table for tests. */
public class FakeItems implements ItemInfo
{
	private final Map<Integer, String> names = new HashMap<>();
	private final Map<Integer, Long> prices = new HashMap<>();
	private final Set<Integer> stackable = new HashSet<>();
	private final Map<Integer, Integer> noted = new HashMap<>();
	private final java.util.Set<Integer> untradeable = new java.util.HashSet<>();

	public FakeItems untradeable(int id, String name)
	{
		names.put(id, name);
		untradeable.add(id);
		return this;
	}

	@Override
	public boolean tradeable(int itemId)
	{
		return !untradeable.contains(itemId);
	}

	public FakeItems add(int id, String name, long price)
	{
		names.put(id, name);
		prices.put(id, price);
		return this;
	}

	public FakeItems stackable(int id, String name, long price)
	{
		add(id, name, price);
		stackable.add(id);
		return this;
	}

	public FakeItems noted(int notedId, int baseId)
	{
		noted.put(notedId, baseId);
		stackable.add(notedId);
		names.put(notedId, names.get(baseId));
		return this;
	}

	@Override
	public int idByName(String name)
	{
		for (Map.Entry<Integer, String> e : names.entrySet())
		{
			if (e.getValue().equalsIgnoreCase(name) && !noted.containsKey(e.getKey()))
			{
				return e.getKey();
			}
		}
		return -1;
	}

	@Override
	public String name(int itemId)
	{
		return names.getOrDefault(itemId, "");
	}

	@Override
	public long marketPrice(int itemId)
	{
		return prices.getOrDefault(canonical(itemId), 0L);
	}

	@Override
	public boolean stackable(int itemId)
	{
		return stackable.contains(itemId);
	}

	@Override
	public int canonical(int itemId)
	{
		return noted.getOrDefault(itemId, itemId);
	}
}

