public class MinigameRewardsTest
{
	private static InventoryDiff change(int... idAndDelta)
	{
		Map<Integer, Integer> before = new HashMap<>();
		Map<Integer, Integer> after = new HashMap<>();
		for (int i = 0; i < idAndDelta.length; i += 2)
		{
			before.put(idAndDelta[i], 1000);
			after.put(idAndDelta[i], 1000 + idAndDelta[i + 1]);
		}
		return InventoryDiff.between(before, after);
	}

	@Test
	public void rewardPullsAreLootForTheMinigamesSkill()
	{
		assertEquals(SourceCategory.RUNECRAFTING, MinigameRewards.forTarget("Rewards Guardian", "Search").category);
		assertEquals(SourceCategory.FISHING, MinigameRewards.forTarget("Reward pool", "Fish").category);
		assertEquals(SourceCategory.FIREMAKING, MinigameRewards.forItem("Supply crate", "Open").category);
		assertEquals(SourceCategory.OTHER, MinigameRewards.forItem("Spoils of war", "Open").category);
		assertNull(MinigameRewards.forTarget("Rewards Guardian", "Examine"));
		assertNull(MinigameRewards.forTarget("Bank booth", "Bank"));

		Ledger ledger = new Ledger(() -> 1L);
		MinigameRewards rewards = new MinigameRewards();
		rewards.onRewardClicked(MinigameRewards.forTarget("Rewards Guardian", "Search"), 10);
		assertTrue(rewards.onCarriedChanges(change(565, 120), 11, ledger));
		assertTrue(rewards.onCarriedChanges(change(26813, 1), 14, ledger));
		SourceRecord gotr = ledger.data().sources.get("reward:Guardians of the Rift");
		assertEquals(SourceCategory.RUNECRAFTING, gotr.category);
		assertEquals(2, gotr.loot.size());
		assertEquals(2, gotr.count);

		// Opening a supply crate: the crate isn't a cost.
		rewards.onRewardClicked(MinigameRewards.forItem("Supply crate", "Open"), 30);
		assertTrue(rewards.onCarriedChanges(change(20703, -1, 1515, 12), 31, ledger));
		SourceRecord wintertodt = ledger.data().sources.get("reward:Wintertodt");
		assertEquals(12L, (long) wintertodt.loot.get(1515));
		assertTrue(wintertodt.supplies.isEmpty());

		// Long after, or after clicking something else, items are nothing to do with it.
		assertFalse(rewards.onCarriedChanges(change(1515, 1), 75, ledger));
		rewards.onRewardClicked(MinigameRewards.forTarget("Reward pool", "Fish"), 80);
		rewards.onOtherClick();
		assertFalse(rewards.onCarriedChanges(change(1515, 1), 81, ledger));
	}

	@Test
	public void motherlodeSackJoinsTheMotherlodeEntry()
	{
		MinigameRewards.Minigame mlm = MinigameRewards.forTarget("Sack", "Search");
		assertEquals(SourceCategory.MINING, mlm.category);
		assertEquals("item:MINING:Motherlode Mine", mlm.key());
		assertEquals("Motherlode Mine", com.gildedledger.tracking.SkillGroups.miningRock("Ore vein", "Pay-dirt"));
		assertNull(MinigameRewards.forTarget("Sack", "Examine"));

		Ledger ledger = new Ledger(() -> 1L);
		ledger.addXp("item:MINING:Motherlode Mine", "Motherlode Mine", SourceCategory.MINING, "Mining", 600);
		MinigameRewards rewards = new MinigameRewards();
		rewards.onRewardClicked(mlm, 5);
		rewards.onCarriedChanges(change(447, 10, 453, 6), 6, ledger);
		SourceRecord entry = ledger.data().sources.get("item:MINING:Motherlode Mine");
		assertEquals(10L, (long) entry.loot.get(447));
		assertEquals(600L, (long) entry.xp.get("Mining"));
	}

	@Test
	public void hiddenSkillsLeaveThePanelButStayTracked()
	{
		TrackerData data = new TrackerData();
		data.source("npc:Goblin", "Goblin", SourceCategory.COMBAT, 1).addLoot(1, 1, 1);
		data.source("item:FISHING:Karambwanji", "Karambwanji", SourceCategory.FISHING, 1).addLoot(1, 1, 1);
		data.source("item:MINING:Iron rocks", "Iron rocks", SourceCategory.MINING, 1).addLoot(1, 1, 1);
		LootPrices prices = new LootPrices()
		{
			public long ge(int id)
			{
				return 10;
			}

			public long highAlch(int id)
			{
				return 5;
			}

			public boolean tradeable(int id)
			{
				return true;
			}
		};
		PanelModel model = PanelModel.build(data, prices, id -> "", true, false, EnumSet.of(SourceCategory.FISHING));
		assertEquals(2, model.sources.size());
		assertTrue(model.sources.stream().noneMatch(v -> v.category == SourceCategory.FISHING));
		assertEquals(3, data.sources.size());
		assertTrue(SourceCategory.FISHING.isSkill());
		assertFalse(SourceCategory.FARMING.isSkill());
		assertFalse(SourceCategory.COMBAT.isSkill());
	}
}

package com.gildedledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gildedledger.data.SourceCategory;
import com.gildedledger.data.TrackerData;
import com.gildedledger.ui.LootPrices;
import com.gildedledger.ui.PanelModel;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class PanelModelTest
{
	private static final int WHIP = 4151;
	private static final int DEFENDER = 12954;
	private static final int CLUE = 2722;
	private static final int TARNISHED_RING = 31000;

	/** Whip trades for 1.5M; the defender and the clue can't be traded. */
	private static final LootPrices PRICES = new LootPrices()
	{
		@Override
		public long ge(int itemId)
		{
			return itemId == WHIP ? 1_500_000 : 0;
		}

		@Override
		public long highAlch(int itemId)
		{
			return itemId == WHIP ? 72_000 : itemId == DEFENDER ? 30_000 : itemId == TARNISHED_RING ? 1_800 : 0;
		}

		@Override
		public boolean valuedAtAlch(int itemId)
		{
			return itemId == TARNISHED_RING;
		}

		@Override
		public boolean tradeable(int itemId)
		{
			return itemId == WHIP;
		}
	};

	@Test
	public void tradeableLootUsesGeAndUntradeablesAreWorthNothingExceptTarnished()
	{
		TrackerData data = new TrackerData();
		data.source("npc:Abyssal demon", "Abyssal demon", SourceCategory.COMBAT, 1).addLoot(WHIP, 2, 1);
		data.source("npc:Abyssal demon", "Abyssal demon", SourceCategory.COMBAT, 1).addLoot(DEFENDER, 1, 1);
		data.source("npc:Abyssal demon", "Abyssal demon", SourceCategory.COMBAT, 1).addLoot(CLUE, 1, 1);
		data.source("npc:Abyssal demon", "Abyssal demon", SourceCategory.COMBAT, 1).addLoot(TARNISHED_RING, 1, 1);

		PanelModel.SourceView demon = PanelModel.build(data, PRICES, id -> "item" + id, true).sources.get(0);

		// Whips at GE, the tarnished ring at its alch price, the defender and clue at nothing.
		assertEquals(3_000_000 + 1_800, demon.lootValue);
		assertEquals(WHIP, demon.loot.get(0).itemId);
		assertTrue(demon.loot.stream().anyMatch(l -> l.itemId == DEFENDER && !l.tradeable && l.value == 0));
	}

	@Test
	public void excludedItemsDoNotCountTowardsProfit()
	{
		TrackerData data = new TrackerData();
		com.gildedledger.data.SourceRecord demon = data.source("npc:Abyssal demon", "Abyssal demon", SourceCategory.COMBAT, 1);
		demon.addLoot(WHIP, 1, 1);
		demon.addLoot(DEFENDER, 1, 1);
		demon.addSupply("2434", 2434, "Prayer potion", "doses", 4, 10_000, 1);
		demon.addSupply("385", 385, "Shark", null, 2, 1_800, 1);

		demon.toggleLootExcluded(DEFENDER);
		demon.toggleSupplyExcluded("385");
		PanelModel.SourceView view = PanelModel.build(data, PRICES, id -> "", true).sources.get(0);
		assertEquals(1_500_000, view.lootValue);
		assertEquals(10_000, view.supplyGp);
		assertTrue(view.loot.stream().anyMatch(l -> l.itemId == DEFENDER && l.excluded));

		// Toggling again counts it once more.
		demon.toggleLootExcluded(DEFENDER);
		assertEquals(1_500_000, PanelModel.build(data, PRICES, id -> "", true).sources.get(0).lootValue);
	}

	@Test
	public void skillsCanBeShownAsOneTable()
	{
		TrackerData data = new TrackerData();
		data.source("item:WOODCUTTING:Yew logs", "Yew logs", SourceCategory.WOODCUTTING, 1).addLoot(WHIP, 3, 1);
		data.source("item:WOODCUTTING:Magic logs", "Magic logs", SourceCategory.WOODCUTTING, 1).addLoot(WHIP, 2, 1);
		data.source("npc:Goblin", "Goblin", SourceCategory.COMBAT, 1).addLoot(WHIP, 1, 1);
		data.source("npc:Cow", "Cow", SourceCategory.COMBAT, 1).addLoot(WHIP, 1, 1);

		assertEquals(4, PanelModel.build(data, PRICES, id -> "", true, false).sources.size());
		List<PanelModel.SourceView> combined = PanelModel.build(data, PRICES, id -> "", true, true).sources;
		assertEquals(3, combined.size());
		PanelModel.SourceView woodcutting = combined.stream()
			.filter(v -> v.category == SourceCategory.WOODCUTTING).findFirst().get();
		assertEquals(5L, woodcutting.loot.get(0).quantity);
		assertEquals(3L, (long) data.sources.get("item:WOODCUTTING:Yew logs").loot.get(WHIP));
	}

	@Test
	public void xpIsSplitBySkillInSkillPanelOrderWithATotal()
	{
		TrackerData data = new TrackerData();
		data.source("npc:Goblin", "Goblin", SourceCategory.COMBAT, 1).addXp("Hitpoints", 40, 1);
		data.source("npc:Goblin", "Goblin", SourceCategory.COMBAT, 1).addXp("Slayer", 20, 1);
		data.source("npc:Goblin", "Goblin", SourceCategory.COMBAT, 1).addXp("Strength", 120, 1);
		data.source("npc:Goblin", "Goblin", SourceCategory.COMBAT, 1).addXp("Attack", 10, 1);

		PanelModel.SourceView goblin = PanelModel.build(data, PRICES, id -> "", true).sources.get(0);

		List<String> order = new ArrayList<>(goblin.xpBySkill.keySet());
		assertEquals(List.of("Attack", "Strength", "Hitpoints", "Slayer"), order);
		assertEquals(190, goblin.xp);
	}
}

package com.gildedledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.gildedledger.data.SourceCategory;
import com.gildedledger.data.SourceRecord;
import com.gildedledger.data.TaskRecord;
import com.gildedledger.data.TrackerData;
import com.gildedledger.tracking.Ledger;
import com.gildedledger.tracking.RecentSupplies;
import org.junit.Before;
import org.junit.Test;

public class RecentSuppliesTest
{
	private static final int SUPER_COMBAT = 12695;
	private static final int SCALES = 12934;
	private static final int AMETHYST_DART = 25849;

	private Ledger ledger;
	private RecentSupplies recent;

	@Before
	public void setUp()
	{
		ledger = new Ledger(() -> 1_000L);
		recent = new RecentSupplies(ledger);
	}

	private RecentSupplies.Booked general(String lineKey, int itemId, String name, long qty, long gp, int tick)
	{
		ledger.addSupply(TrackerData.GENERAL_SUPPLIES_KEY, TrackerData.GENERAL_SUPPLIES_NAME,
			SourceCategory.GENERAL_SUPPLIES, lineKey, itemId, name, "doses", qty, gp);
		ledger.incrementCount(TrackerData.GENERAL_SUPPLIES_KEY, TrackerData.GENERAL_SUPPLIES_NAME,
			SourceCategory.GENERAL_SUPPLIES);
		RecentSupplies.Booked b = new RecentSupplies.Booked(TrackerData.GENERAL_SUPPLIES_KEY,
			TrackerData.GENERAL_SUPPLIES_NAME, SourceCategory.GENERAL_SUPPLIES, false, lineKey, itemId, name, "doses",
			qty, gp, tick, true);
		recent.addGeneral(b);
		return b;
	}

	@Test
	public void potionBeforeTheFightMovesToTheKill()
	{
		general("12695", SUPER_COMBAT, "Super combat potion", 1, 4_000, 100);
		ledger.data().currentTask = new TaskRecord("Goblins", null, 50, 50, 1);

		// The fight starts at tick 150, the goblin dies at 160.
		recent.moveGeneralToKill("npc:Goblin", "Goblin", true, 150 - RecentSupplies.PRE_FIGHT_TICKS);

		assertNull(ledger.data().sources.get(TrackerData.GENERAL_SUPPLIES_KEY));
		SourceRecord goblin = ledger.data().sources.get("npc:Goblin");
		assertEquals(4_000, goblin.supplyCost());
		assertEquals("doses", goblin.supplies.get("12695").unit);
		assertEquals(4_000, ledger.data().currentTask.supplyGp);
	}

	@Test
	public void suppliesLongBeforeTheFightStayInGeneral()
	{
		general("12695", SUPER_COMBAT, "Super combat potion", 1, 4_000, 100);
		recent.moveGeneralToKill("npc:Goblin", "Goblin", false, 1_000 - RecentSupplies.PRE_FIGHT_TICKS);
		assertEquals(4_000, ledger.data().sources.get(TrackerData.GENERAL_SUPPLIES_KEY).supplyCost());
		assertNull(ledger.data().sources.get("npc:Goblin"));
	}

	private void blowpipe(String key, String name, int itemId, long qty, long each, int tick)
	{
		ledger.addSupply(key, name, SourceCategory.COMBAT, String.valueOf(itemId), itemId, "x", null, qty, qty * each);
		recent.addBlowpipe(new RecentSupplies.Booked(key, name, SourceCategory.COMBAT, false, String.valueOf(itemId),
			itemId, "x", null, qty, qty * each, tick, false));
	}

	@Test
	public void blowpipeCheckCorrectsTheEstimate()
	{
		recent.onBlowpipeCheck(AMETHYST_DART, 1_000, 5_000, SCALES, id -> 0);
		// Estimated 10 scales and 3 darts...
		blowpipe("npc:Zulrah", "Zulrah", SCALES, 10, 150, 1);
		blowpipe("npc:Zulrah", "Zulrah", AMETHYST_DART, 3, 1_000, 1);
		// ...but the Check shows 12 scales and 2 darts were used.
		recent.onBlowpipeCheck(AMETHYST_DART, 998, 4_988, SCALES, id -> id == SCALES ? 150 : 1_000);

		SourceRecord zulrah = ledger.data().sources.get("npc:Zulrah");
		assertEquals(12, zulrah.supplies.get(String.valueOf(SCALES)).quantity);
		assertEquals(1_800, zulrah.supplies.get(String.valueOf(SCALES)).gp);
		assertEquals(2, zulrah.supplies.get(String.valueOf(AMETHYST_DART)).quantity);
		assertEquals(2_000, zulrah.supplies.get(String.valueOf(AMETHYST_DART)).gp);
	}

	@Test
	public void reloadingBetweenChecksSkipsTheCorrection()
	{
		recent.onBlowpipeCheck(AMETHYST_DART, 10, 100, SCALES, id -> 0);
		blowpipe("npc:Zulrah", "Zulrah", SCALES, 4, 150, 1);
		recent.forgetBlowpipeCheck();
		recent.onBlowpipeCheck(AMETHYST_DART, 500, 9_000, SCALES, id -> 150);
		assertEquals(4, ledger.data().sources.get("npc:Zulrah").supplies.get(String.valueOf(SCALES)).quantity);
	}
}

package com.gildedledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gildedledger.tracking.Reminders;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class RemindersTest
{
	private static final int WARN = 50; // 30 seconds

	@Test
	public void superCombatBoostIsRemindedOnceBeforeItRunsOut()
	{
		Reminders r = new Reminders();
		// Drink: +5 to each melee stat.
		Map<String, Integer> boosted = Map.of("Attack", 5, "Strength", 5, "Defence", 5);
		assertTrue(r.onBoosts(0, boosted, Collections.emptyMap(), false, WARN).isEmpty());
		// The shared clock ticks: one level drops at tick 30, then every 100 ticks.
		int boost = 5;
		List<String> warned = Collections.emptyList();
		int warnedAt = -1;
		for (int tick = 1; tick < 500 && warnedAt < 0; tick++)
		{
			if (tick == 30 || (tick > 30 && (tick - 30) % 100 == 0))
			{
				boost--;
			}
			warned = r.onBoosts(tick, Map.of("Attack", boost, "Strength", boost, "Defence", boost),
				Collections.emptyMap(), false, WARN);
			if (!warned.isEmpty())
			{
				warnedAt = tick;
			}
		}
		// Last level drops at tick 430, so the reminder comes 50 ticks before.
		assertEquals(380, warnedAt);
		assertEquals(3, warned.size());
	}

	@Test
	public void divinePotionsUseTheirTimer()
	{
		Reminders r = new Reminders();
		r.onBoosts(0, Map.of("Ranged", 13), Map.of("Ranged", 500), false, WARN);
		assertTrue(r.onBoosts(1, Map.of("Ranged", 13), Map.of("Ranged", 60), false, WARN).isEmpty());
		assertEquals(List.of("Ranged"), r.onBoosts(2, Map.of("Ranged", 13), Map.of("Ranged", 50), false, WARN));
		// Only once.
		assertTrue(r.onBoosts(3, Map.of("Ranged", 13), Map.of("Ranged", 40), false, WARN).isEmpty());
	}

	@Test
	public void prayerRemindsOnceWhenItDrainsLow()
	{
		Reminders r = new Reminders();
		assertFalse(r.onPrayer(5, 10)); // logged in with low prayer: no nag
		assertFalse(r.onPrayer(30, 10));
		assertFalse(r.onPrayer(11, 10));
		assertTrue(r.onPrayer(10, 10));
		assertFalse(r.onPrayer(9, 10));
		assertFalse(r.onPrayer(40, 10)); // drank a prayer potion: armed again
		assertTrue(r.onPrayer(8, 10));
	}

	@Test
	public void cannonRemindsWhenRunningLow()
	{
		Reminders r = new Reminders();
		assertFalse(r.onCannonballs(30, 5, true));
		assertFalse(r.onCannonballs(6, 5, true));
		assertTrue(r.onCannonballs(5, 5, true));
		assertFalse(r.onCannonballs(4, 5, true));
		assertFalse(r.onCannonballs(30, 5, true));
		assertTrue(r.onCannonballs(0, 5, true));
	}
}

package com.gildedledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.gildedledger.data.GpSession;
import com.gildedledger.data.SourceCategory;
import com.gildedledger.tracking.Ledger;
import com.gildedledger.tracking.SessionTracker;
import com.gildedledger.tracking.ItemRules;
import org.junit.Before;
import org.junit.Test;

public class SessionTrackerTest
{
	private static final int BLOOD_RUNE = 565;
	private static final int KARAMBWAN = 3142;

	private long now = 1_000_000;
	private Ledger ledger;
	private SessionTracker sessions;

	@Before
	public void setUp()
	{
		ledger = new Ledger(() -> now);
		// Blood runes 400 gp, karambwan 180 gp.
		sessions = new SessionTracker(ledger, id -> id == BLOOD_RUNE ? 400 : id == KARAMBWAN ? 180 : 0, () -> now);
	}

	private void craftBloods(int runes)
	{
		ledger.addLoot("item:RUNECRAFTING:Blood altar", "Blood altar", SourceCategory.RUNECRAFTING, BLOOD_RUNE, runes);
		ledger.incrementCount("item:RUNECRAFTING:Blood altar", "Blood altar", SourceCategory.RUNECRAFTING);
	}

	@Test
	public void profitBeforeTheSessionAndWhilePausedDoesNotCount()
	{
		craftBloods(100); // before the session

		sessions.start();
		craftBloods(10);
		now += 30 * 60_000; // 30 minutes
		sessions.pause();
		assertFalse(sessions.active().isRunning());

		craftBloods(50); // while paused: doesn't count
		now += 60 * 60_000;
		sessions.resume();
		craftBloods(5);
		now += 30 * 60_000;

		GpSession live = sessions.live();
		assertEquals(15 * 400, live.profit);
		sessions.end();

		assertNull(sessions.active());
		GpSession done = ledger.data().sessionLog.get(0);
		assertEquals(15 * 400, done.profit);
		assertEquals(60 * 60_000, done.activeMillis);
		assertEquals(6_000, done.gpPerHour());
		assertEquals("Blood rune crafting", done.title);
	}

	@Test
	public void sessionsAreNamedAfterWhatWasDoneMost()
	{
		sessions.start();
		craftBloods(1);
		for (int i = 0; i < 3; i++)
		{
			ledger.addLoot("item:FISHING:Karambwan", "Karambwan", SourceCategory.FISHING, KARAMBWAN, 1);
			ledger.incrementCount("item:FISHING:Karambwan", "Karambwan", SourceCategory.FISHING);
		}
		now += 60_000;
		sessions.end();
		assertEquals("Karambwan fishing", ledger.data().sessionLog.get(0).title);

		assertEquals("Iron mining", SessionTracker.activityTitle("Iron rocks", SourceCategory.MINING));
		assertEquals("Yew woodcutting", SessionTracker.activityTitle("Yew logs", SourceCategory.WOODCUTTING));
		assertEquals("Abyssal demon", SessionTracker.activityTitle("Abyssal demon", SourceCategory.COMBAT));
		assertEquals("Ourania altar runecrafting", SessionTracker.activityTitle("Ourania altar", SourceCategory.RUNECRAFTING));
	}

	@Test
	public void aSessionKeepsItsOwnLootAndSuppliesAsOneTable()
	{
		craftBloods(100); // before
		ledger.addSupply("item:RUNECRAFTING:Blood altar", "Blood altar", SourceCategory.RUNECRAFTING,
			"7936", 7936, "Pure essence", null, 100, 200);

		sessions.start();
		craftBloods(20);
		ledger.addSupply("item:RUNECRAFTING:Blood altar", "Blood altar", SourceCategory.RUNECRAFTING,
			"7936", 7936, "Pure essence", null, 20, 40);
		ledger.addLoot("item:FISHING:Karambwan", "Karambwan", SourceCategory.FISHING, KARAMBWAN, 3);
		sessions.pause();
		craftBloods(50); // paused
		sessions.resume();
		craftBloods(5);
		now += 60_000;
		sessions.end();

		GpSession done = ledger.data().sessionLog.get(0);
		assertEquals(25L, (long) done.loot.get(BLOOD_RUNE));
		assertEquals(3L, (long) done.loot.get(KARAMBWAN));
		assertEquals(20L, done.supplies.get("7936").quantity);
		assertEquals(40L, done.supplies.get("7936").gp);
	}

	@Test
	public void renameDeleteAndClear()
	{
		sessions.start();
		now += 1000;
		sessions.end();
		sessions.start();
		now += 1000;
		sessions.end();
		String id = ledger.data().sessionLog.get(0).id;
		sessions.rename(id, "My trip");
		assertEquals("My trip", ledger.data().sessionLog.get(0).title);
		assertTrue(ledger.data().sessionLog.get(0).renamed);
		sessions.delete(id);
		assertEquals(1, ledger.data().sessionLog.size());
		sessions.clearLog();
		assertTrue(ledger.data().sessionLog.isEmpty());
	}

	@Test
	public void restartingTheClientKeepsTheTimePlayedButNotTheTimeAway()
	{
		sessions.start();
		craftBloods(2);
		now += 5 * 60_000;
		sessions.heartbeat(); // last tick before the client closed
		now += 60 * 60_000; // closed for an hour
		sessions.pauseAfterRestart();
		assertEquals(5 * 60_000, sessions.active().activeMillis);
		assertEquals(800, sessions.active().profit);
	}

	@Test
	public void restartingWithNoTicksSeenCountsNoTime()
	{
		sessions.start();
		craftBloods(2);
		now += 10 * 60_000;
		sessions.pauseAfterRestart();
		assertFalse(sessions.active().isRunning());
		assertEquals(0, sessions.active().activeMillis);
		assertEquals(800, sessions.active().profit);
	}

	@Test
	public void bossPartsAreFiledUnderTheBoss()
	{
		assertEquals("Hespori", ItemRules.bossGroup("Flower"));
		assertEquals("Zulrah", ItemRules.bossGroup("Snakeling"));
		assertEquals("Grotesque Guardians", ItemRules.bossGroup("Dusk"));
		assertEquals("Goblin", ItemRules.bossGroup("Goblin"));
	}
}

