	@Test
	public void tidyingTwiceLeavesGroupedEntriesAlone()
	{
		ledger.data().source("item:RUNECRAFTING:Death altar", "Death altar", SourceCategory.RUNECRAFTING, 1)
			.addXp("Runecraft", 100, 1);
